VN.registerScenario("ch06", [

  /* =====================================================
     ============ パート1: EP88〜100 (前半) ===============
     ===================================================== */

  // ---------------------------------------------------
  // Scene 1: el_taken — ｜刹那《せつな》の安寧、崩壊 (EP88)
  // ---------------------------------------------------
  { label: "el_taken" },
  { chapter: { no: "第六章", title: "神魔編" } },
  { bg: "bathhouse_base" },
  { bgm: "comedy" },
  { text: "魔王を封印して、一週間が経った。" },
  { text: "永遠に続くかと思われた日常は、いとも容易く崩れ去る事になる。" },
  { name: "ティア", who: "tia", expr: "normal", text: "そう言えば、どうして魔王をアカツキや｜魔杖《まじょう》が封印しなかったの？魔剣グレモリーに封印の方法を聞いたのはアカツキと｜魔杖《まじょう》でしょ？" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "何かを封印する際には原則、封印術の才能が必要なんだよ、それを使えるのが俺だけだったから俺がやった、それだけの話だ" },
  { name: "ティア", who: "tia", expr: "laugh", text: "それなら魔剣グレモリーを作る必要は無かったんじゃないの？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "ティアには言ってなかったか、俺が才能を発揮できるのは短い時間の間だけなんだ、だからグレモリーに封印の方法を聞いておく必要があった" },
  { chara: [
    { slot: "left",   id: "akatsuki", expr: "serious" },
    { slot: "center", id: "yamato",   expr: "normal" },
    { slot: "right",  id: "tia",      expr: "normal" },
  ] },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "ヤマトさんの言う通り、グレモリーさんの知識は役立ちましたよ、｜魔窟《まくつ》のような迷宮を媒体にして封印を行う、これが分からなければ先日の作戦は上手くいきませんでしたからね" },
  { name: "ティア", who: "tia", expr: "normal", text: "ふーん、そうなんだ" },
  { chara: [
    { slot: "left",   id: "crocell",  expr: "normal" },
    { slot: "center", id: "yamato",   expr: "normal" },
    { slot: "right",  id: "zeno",     expr: "smile" },
  ] },
  { text: "今は朝食の場。珍しく皆が集まっている。普段は各自自由に行動している為、こうして全員が揃うのは魔王封印以降初めてだ。人数は……俺、クロセル、アカツキ、ティア、エル、勇者、V、ファイ、瀬野……9人か、多すぎだろ。" },
  { chara: { slot: "right", id: "bolt", expr: "smile" } },
  { name: "V", who: "bolt", expr: "normal", text: "それにしてもやっぱり凄いですね、本当に魔王を封印してしまうなんて" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "Vは最近そればっかだな、付いて来たかったのか？" },
  { name: "V", who: "bolt", expr: "smile", text: "いえ……僕が付いて行っても足手まといになるだけでしょうから……でも、本当にヤマトさんには感謝しています" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "……V、俺に対しても敬語になったな" },
  { name: "V", who: "bolt", expr: "normal", text: "今やヤマトさんも敬うべき相手ですからね、当然ですよ、それに……これで兄の無念は晴らされたと言えます" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "兄？お前に兄なんて居たのか？" },
  { name: "V", who: "bolt", expr: "sad", text: "えぇまぁ……魔王に殺されてしまったんですけどね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうだったのか" },
  { text: "魔王オセは公国を滅ぼした以外、人里に直接侵攻した事はない。それでありながら魔王の被害にあっているという事は……Vの兄は魔族か勇者だったのか、或いは公国から逃げてきたのか。疑問には思うが、問い詰めるべき事でもない。俺には興味のないことだ。" },
  { chara: { slot: "left", id: "akatsuki", expr: "normal" } },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "それにしても……私とヤマトさん以外にあそこから来た人が居たなんて驚きですね" },
  { chara: { slot: "right", id: "zeno", expr: "smile" } },
  { name: "瀬野", who: "zeno", expr: "normal", text: "僕も驚いてるよ、ヤマト以外にあそこから来た人が居たなんてね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "瀬野は俺を殺した奴らに殺されてこっちに来たのか？" },
  { name: "瀬野", who: "zeno", expr: "serious", text: "そうだけど……言ってなかった？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "想像はついていたが、直接聞いたのは初めてだな" },
  { name: "瀬野", who: "zeno", expr: "smile", text: "そうだっけ、それで……ヤマトは今までどうしてたの？" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "それを話すと長くなるな……瀬野の方はどうなんだ？" },
  { name: "瀬野", who: "zeno", expr: "serious", text: "僕はヤマトと別れた後、皇帝に才能を見込まれて帝国に仕えてたんだ。皇帝が魔王になった後、魔王は僕達の過去を調べたみたいでね、魔王に脅されて僕は魔族になり、魔王の側に置かれる事になった、ヤマトと戦う際の保険として" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "聞いてる限りだとアカツキの経歴に似てるが、仕える相手が悪かったな" },
  { name: "瀬野", who: "zeno", expr: "normal", text: "そうだね" },
  { text: "瀬野の経歴は大体は俺の予想通りと言った所か。ただ、気になる点はある。" },
  { chara: { slot: "left", id: "crocell", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そう言えば瀬野の才能ってなんなんだ？" },
  { name: "瀬野", who: "zeno", expr: "sad", text: "前に言ってなかった？『時間操作3』『空間操作3』『射撃術5』『機械技術5』だけど……" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "……射撃術と機械技術以外意味不明なんだが……クロセル、解説頼む" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "\"操作\"系の才能は魔術の上位互換的才能だと言って良い、詠唱や魔法陣、魔力や触媒などの準備、過程を必要とせずに魔術と同様の効果を得られる才能だ" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "なんだそのチート的才能は……" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "とても珍しい才能だな、それを二つも持っているというのは、ディザビリティと同等なまでに｜稀有《けう》な存在だぞ" },
  { name: "瀬野", who: "zeno", expr: "sad", text: "そうなんだ……でも僕が皇帝に見込まれたのは機械技術の才能なんだけどね……" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "帝国は飛行船やら｜機甲兵《きこうへい》やら、機械技術で長けた国だったからな、帝国にとってゼノは優秀な人材だったのだろう" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "なるほどな、瀬野は戦闘経験はあるのか？" },
  { name: "瀬野", who: "zeno", expr: "serious", text: "護身用に自作の拳銃は持ってるけど……使った事は一度も無いよ、僕が戦うまでもなかったしね" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "才能だけ見れば私より優秀ですね……ヤマトさんの友達って事は前世の行いが特別良かった訳でも無いでしょうし……解せません" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "やっぱ才能に前世の行いって関係無さそうだよな……そもそも検証のしようがないから今まで認知されてなかったんだろうが" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "前世と呼べる物が分かるのは私達だけですからね、そもそもあれは前世では無いのかもしれませんが" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "才能は決まった以上もう変えられないのだから前世云々を気にする必要は無いな" },
  { text: "三人目の異世界転生者である瀬野が現れたが、未だに異世界転生の実態は分からない。ただ、俺と瀬野はほぼ同時刻、同じ場所で死んだ。そして二人とも異世界に転生した。つまり、あの場所、或いはあの時刻が、異世界転生を果たす何らかの条件だったと推測出来る。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "この調子だと、帰る手段はまだ分からなそうだな……" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ご主人は……帰りたいのか？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "まだ考えてる途中だ、決めるのは方法が見つかってからでも良いだろう" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "それもそうだな" },
  { text: "あの世界に残してきた物、霧雨組の事ぐらいだろうか。俺が居なくなった後も何とかやれているだろうか。何だかんだ言ってもあいつらだって背中を預け合った仲間だ。人並みに心配はする。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そう言えば勇者が静かだな" },
  { chara: { slot: "right", id: "nicholas", expr: "depressed" } },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "おい勇者、何落ち込んでるんだよ、お前は救世の英雄になったんだろ" },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "そうだけど……僕にはもう祝福がないんだ……戦いたくない……死にたくないよ……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "いつもの勢いはどうしたんだよ……" },
  { name: "ティア", who: "tia", expr: "normal", text: "わたしは祝福なんて必要ないわ、本当なら返してあげても良いのよ？" },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "神は僕を見捨てたんだ……｜抜刀斎《ばっとうさい》ニコンは死んだ……僕はもうただのニコラスだ……" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "ダメだこいつ……" },
  { text: "祝福がティアに移った事で完全に意気消沈している。まぁ今まで当然のように持っていた不死性が失われたら、不安になる気持ちは分かるが。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "人は死ぬのが当たり前なんだぞ……不老不死が当然だと思うなよ" },
  { text: "俺は呆れたように言い放つ。しかし、勇者の様子が明るくなる事はない。暫くはショックを受けるのも仕方ないか、いつか勝手に立ち直るだろう。" },
  { chara: [
    { slot: "center", id: "yamato", expr: "sad" },
    { slot: "right",  id: "el",     expr: "smile" },
  ] },
  { name: "エル", who: "el", expr: "troubled", text: "ふぅ、これだけの人数になると家事をするのもちょっと大変だね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "エルが家事が得意と言っても才能指数は1だろ？無理はするなよ" },
  { name: "エル", who: "el", expr: "smile", text: "あはは……大丈夫だよ、この身体は結構丈夫なんだ" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "それなら良いが……" },
  { text: "給仕をするエルと少し言葉を交わした所で、遠くから戸を叩く音が聞こえる。" },
  { name: "エル", who: "el", expr: "normal", text: "っと、こんな時間にお客さんなんて珍しいね、ちょっと行ってくるよ" },
  { chara: { slot: "left", id: "akatsuki", expr: "serious" } },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "まだ公衆浴場は営業時間外ですし……ちょっと直感を感じたので、私も見てきます" },
  { text: "アカツキとエルは玄関に向かった。なんだろう……胸騒ぎがする。出来れば｜杞憂《きゆう》だと良いが。俺はパンをスープで胃に流し込むと、そのまま席を立つ。" },
  { name: "ティア", who: "tia", expr: "laugh", text: "ヤマトも行くの？" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "あぁ、ちょっと見てくる" },
  { text: "ティアに見送られ、俺は玄関へと向かった。その途中、廊下を歩いている所で、声が聞こえてくる。" },
  { hide: "all" },
  { bgm: "tension" },
  { name: "アカツキ", text: "どういう事ですか？エルさんを連行するなんて……" },
  { name: "福音使徒", text: "エンド様の命令だ、大人しく付いて来い" },
  { name: "福音使徒", text: "エルさん、身に覚えは？" },
  { name: "エル", text: "私は何も……" },
  { name: "アカツキ", text: "待って下さい、エルさん一人だけを連行するのは許可できません、私も付いて行きます" },
  { name: "福音使徒", text: "駄目だ、エンド様にはその少女一人を連れてくるように命じられた、そして抵抗するようなら武力行使を認める、ともな" },
  { name: "アカツキ", text: "そんな……" },
  { text: "嫌な予感はどうやら的中したらしい。俺は慌てて駆け出した。" },
  { chara: [
    { slot: "center", id: "yamato", expr: "surprised" },
    { slot: "right",  id: "el",     expr: "sad" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "エル！" },
  { name: "エル", who: "el", expr: "sad", text: "ヤマトさん！" },
  { text: "廊下の角を曲がり、玄関の様子が俺の目に飛び込んでくる。二人の福音使徒に両腕を掴まれ拘束されたエル。その前で、両手を横にぼそぼそと何か呟く福音使徒が一人。そして福音使徒に阻まれ、俺の方へと振り向くアカツキ。" },
  { text: "才能の解放をするまでもない。エルとアカツキが戦闘する意思を持てば対処できる相手だ。だが、福音使徒を傷付けるという事は聖教会、教国を敵に回す事になる。それは出来ない。" },
  { text: "此処は……大人しく引き下がるしか無いのか……" },
  { chara: { slot: "center", id: "yamato", expr: "angry" } },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "待て！せめて説明を！" },
  { name: "エル", who: "el", expr: "sad", text: "ヤマト様……ごめん……" },
  { name: "福音使徒", text: "――空間魔術……｜帰還《リコール》" },
  { text: "まずい、手を広げている男が呟いていたのは魔術の詠唱だ。" },
  { se: "magic" },
  { fx: "flash" },
  { hide: "right" },
  { text: "辺りに光が満ちる。俺は慌ててエルへと手を伸ばす。が……その手は届く事無く、エルの姿は三人の福音使徒と共に消え失せた。" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "くそっ……逃したか……アカツキ、この状況をどう分析する" },
  { chara: { slot: "right", id: "akatsuki", expr: "serious" } },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "少なくともエルさんが殺される事はない……と思います、でも彼女は私達に何かを隠している、それが恐らく……エルさんが連行された理由です" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "エルが隠し事？仮にそんな事があったとして、聖教会は関係ないだろ" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "いえ、その逆です、関係あるから連行されたのかと……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "くそっ……取り敢えず聖教会に行くぞ、教皇に直接話を聞いた方が早い" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "そうですね、私も付いて行きます、ヤマトさんはクロセルさんを連れて来て下さい" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "それは……最悪戦闘になると仮定しての事か？" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "いえ、それもありますが、クロセルさんの知識と分析の才能があった方が有利に事を運べると思ったので" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "それもそうか、分かった、連れて来る" },
  { text: "人生にアクシデントは付き物だ。平坦なまま、何も起きない人生なんて無い。山があるなら谷もある。それにしては、些か山が続き過ぎている気がするが。少しぐらいは落ち着いて谷を満喫したかったというのに。" },
  { hide: "all" },
  { chara: [
    { slot: "center", id: "yamato",  expr: "serious" },
    { slot: "right",  id: "crocell", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "はぁ……クロセル、出掛けるぞ" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "どうしたのだご主人、そんなに慌てて" },
  { text: "少し走った程度で息が切れる身体ではない。なのに息が切れ、動悸を覚えるというのは……動揺が原因だろうか。俺は一度頭を冷やす為に深呼吸をすると、クロセルに事情を告げる。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "エルが聖教会に連行された、これから教皇に話を聞きに行く" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "なんだと……？それは確かなのか" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "この目で見たんだから間違いない" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "そうか、分かった、我も付いて行く" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "おう、助かる" },
  { text: "こうして、クロセルとアカツキを連れ、俺達は聖教会へと向かう事になった。" },

  // ---------------------------------------------------
  // Scene 2: nicholas_and_god — 勇者と神 (EP89〜90)
  // ---------------------------------------------------
  { label: "nicholas_and_god" },
  { hide: "all" },
  { bg: "arcadia_lower" },
  { comment: "EP89: 面会謝絶 → 勇者ルートでの上層潜入" },
  { chara: [
    { slot: "left",   id: "akatsuki", expr: "serious" },
    { slot: "center", id: "yamato",   expr: "angry" },
    { slot: "right",  id: "crocell",  expr: "normal" },
  ] },
  { text: "教皇から話を聞く為に、俺達は最寄りの教会へと足を踏み入れた。少し視線を泳がせれば、アダンの後継人である施設長を見つける。民衆に公にはされていないが、違法奴隷売買の摘発、そして魔王封印の首謀者として、聖教会の上層部で俺の名前は通っている。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "おい施設長！" },
  { name: "福音使徒", text: "ヤマトさんですか、良く来て下さいました、今日は何の用事で？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "教皇を呼び出せ、今すぐにだ！" },
  { name: "福音使徒", text: "これまた突然ですね……分かりました、確認を取ってきます" },
  { text: "俺がやや強い語調で告げると、施設長は少しだけ怯むように身を竦ませ、俺に小さくお辞儀をすると、駆け足で教会の奥へと走っていく。" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ご主人……落ち着け" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "俺は十分に落ち着いてる。ただ、今こうしてる間、エルの身に何があるか分からない、だから急いでるだけだ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "急ぐのは良いですけど……関係ない福音使徒に当たるのは良くないと思いますよ" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "別に八つ当たりした訳じゃねぇよ、少し強く言っといた方が事が早く進むと思っただけで……" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ご主人、エルの事を心配するのだな、少し妬けるが我は嬉しい" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "何言ってるんだ……エルは仲間だろ……心配するのは当然……" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "少し前のヤマトさんはクロセルさん以外に興味が無い、私達なんてどうなっても良い、みたいな態度でしたけど" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "う……そうだったか……？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "我は今のご主人が好きだぞ、優しいご主人が大好きだ" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "馬鹿にするんじゃねぇ、仲間だから心配するだけであって、誰に対しても優しい訳じゃない、俺は本質的に利己的だ" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "うむ、まぁそういう事にしておいてやろう" },
  { text: "いつも思うが、クロセルは何を言ってるんだ。ただ、こればっかりは何度言っても分からないようだから諦めている。実際、多少丸くなった自覚はあるのだ。それでも俺が英雄ではなく｜咎人《とがびと》である事に変わりはないのだが。" },
  { text: "そんな風に二人と話していると、暫くして施設長の福音使徒が戻って来る。だが、その周りに教皇の姿は見当たらない。薄々察していた事ではあるが、この様子だと……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "教皇はどうした？" },
  { name: "福音使徒", text: "すいません、ヤマトさん。エンド様は今忙しく、お会い出来ないそうです" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "何か伝言とかは無いのか？" },
  { name: "福音使徒", text: "特にありません" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうか……教皇は今上層だな？" },
  { name: "福音使徒", text: "えぇまぁ、そうですが" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そうか、ご苦労だったな" },
  { text: "教皇への面会はあっさりと拒絶された。だが予測が確信に変わっただけ収穫と言えるだろう。要するに、教皇は俺達に会う気は無い、と。つまりはそういうことだ。" },
  { text: "俺は施設長から背を向けると、そのまま教会の出口へと歩いて行く。そして、教会から出ると、クロセルとアカツキに向き直り、問い掛ける。" },
  { chara: { slot: "center", id: "yamato", expr: "smirk" } },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "クロセル、エルは何処に居ると思う" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "教皇の居る場所、上層だろうな" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、俺もそう思う。ならする事は一つだな" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "ヤマトさん……もしかして" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "勿論、上層に行く" },
  { text: "俺はそうはっきりと言い切ると、拠点の方向へと歩き出す。そして、アカツキはそんな俺の前に立ち塞がり、慌てた様子で言葉を続ける。" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "ダメです！そんな事をすれば……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "分かってる、勇者でない俺達が行くのは罪に問われ、聖教会と敵対する事になる、要するに悪手だ" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "ならどうするんですか？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "簡単な話だ、俺達の中に、上層に立ち入れる人間が居るだろう？" },
  { text: "俺は小首を傾げながら、ニヤリと口角を上げる。それに対して、アカツキは思い付いたかのように呟いた。" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "勇者ニコラス……それとティア様ですか" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そうだ、あの二人なら神の御告げという大義名分を装って上層に侵入できる" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "確かに良い考えではあると思いますが……あの二人だけに任せるのは少し不安が……" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "安心しろ、我も杖の形態を取れば付いて行ける" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "同様にグレモリーも持ち込めるが……あいつは別に要らないか" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "ラプラスさんは論外ですから、クロセルさんと勇者二名の三人で向かう事になる感じですか" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "ん？ラプラス……？あいつは勇者が殺したはずじゃ……" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "我と同じで仮初の肉体だからな、本体である剣を破壊しない限り、生き続ける" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "なんで破壊しないんだよ、クロセルと同じって事は自由に肉体を持てる訳で……危険じゃないのか？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "本来、魔の力を持った意思持つ武器はエネルギーが無い限り動けない、だから武器を使う者、要するに契約者からエネルギーを得てその真価を発揮するのが一般的だ" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "主に生命力とか魔力ですね、魔王や魔族を除いて、魔術の才能が無い人間には魔力が無いので、大抵、多くの者は寿命を削って武器を扱います" },
  { text: "能力を持った武器が動くにはエネルギーが要る、人が食事を取らないと動けないのと同じ、極めて当たり前の事ではあるのだが。この事実を俺は初めて知った。だがちょっと待て。つまり俺はクロセルから何かを奪われているのか？" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "クロセル……お前あんだけ派手に暴れてくれてるが……まさか俺の生命力を……" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "安心しろご主人、我はご主人から何のエネルギーも得ていない" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "どういうことだ？今お前は魔の力を持った武器はエネルギーが無いと動けないって" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "どうやら我は特別らしいな、無尽蔵に魔力が湧き上がってくる故に、外部のエネルギーには依存しないのだ" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "本来存在するはずの代償を無視して力を行使出来るのか、どう考えても理外のぶっ壊れ武器じゃねぇか" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ふふっ、褒めてるのか？" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "呆れてるんだよ……" },
  { text: "今更だが、俺はとんでもない武器を拾ってしまったらしい。ただ、これで魔剣や｜魔杖《まじょう》などに契約者が必要な理由が分かった。契約者を失ったラプラスや契約をしていないグレモリーは力を行使できないのだ。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "まぁ、取り敢えずさっきの方針で上層に出向いてくれ、教皇から話を聞き出せればパーフェクト、そうでなくてもエルの無事が確認できれば文句はない" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "うむ、我と勇者に任せておけ" },
  { text: "という事で、俺達は一度拠点に戻り、勇者とティアにこの話をしたのだが……" },
  { hide: "all" },
  { chara: [
    { slot: "left",   id: "akatsuki", expr: "normal" },
    { slot: "center", id: "nicholas", expr: "depressed" },
    { slot: "right",  id: "yamato",   expr: "smirk" },
  ] },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "嫌だ……行きたくない……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "そう言えばこいつ祝福を失ったショックで鬱だったんだな……すっかり忘れてた" },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "教皇は強いんだ……僕は知ってる、だから歯向かったりしたら殺される……嫌だ……怖いよ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "おいおい、エルもお前も、一緒に戦ってきた仲間だろ？助けてやりたいとは思わないのか？" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "僕なんかが行っても役に立たないさ……どうせ僕はただの勇者……ただ高IQに容姿端麗で腕が立つだけの残念な男だよ" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "今のお前に自尊心があるのか無いのか分からなくなるな……" },
  { text: "勇者を置いてティアだけを行かせる訳にもいかない。さて、どうしたものか……" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "俺なんかが励ましても意味ないな……此処は女性陣に協力して貰うしか無いか" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "え……私は嫌ですよ？" },
  { chara: { slot: "lcenter", id: "crocell", expr: "laugh" } },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "我は魅力的なレディだからな！ここは我に任せても良いのだぞ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "クロセル、ティア、ファイ……と、やってくれそうなのがガキしか居ねぇな" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "失礼だな！我はこう見えても一番年上なのだぞ！？" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "見た目が幼すぎるんだよ、まともな女性と言うとアカツキぐらいしか……" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "えー……ニコラスさんなら小さい子もいけると思いますけど" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "気持ちは分かるがここは協力してくれ……" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "はぁ、仕方ないですね……任されました" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "じゃあ頼んだぞ" },
  { text: "という訳で、アカツキを残して俺とクロセルは勇者の部屋を出た。後はアカツキ次第だ。色仕掛けが出来るような性格ではないが、人を立てて説得するという点では一番適任だろう。" },
  { hide: "all" },
  { chara: [
    { slot: "left",  id: "yamato",  expr: "smirk" },
    { slot: "right", id: "crocell", expr: "normal" },
  ] },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ご主人は……我を子供だと思っていたのか？" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "少なくとも見た目はな、大人の色気はまぁ多少……あると思ってるぞ" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "そうか！ふふっ……やはりご主人も我に欲情するのだな" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "悪いが俺に少女趣味は無いんだ、残念だったな" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "嘘だろう？我に欲情している、いや……欲情していたのは事実の筈だ" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "クロセル、お前俺の心を読んだんだな……あれほどやめろと言ってるのに……" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "うぐっ……だが事実だろう？" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "まぁな、俺が少女趣味なんじゃない、相手がお前だから欲情するんだ、勘違いするなよ" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "っ……！そ……そうか……我だから欲情してしまうのだな、なるほど、それなら仕方ない" },
  { text: "俺はクロセルの頭に拳を落とす。ばしんと弾かれる手の感触に、何だか少しだけ懐かしさを覚える。当の本人はと言うと、俺から視線を逸らして赤くなっている。" },
  { text: "可愛いと思ってしまう辺り、俺はもう完全にダメらしい。殊更クロセルに対しては、隠せる物でも無いのだが、俺の口から言うにはまだ早いだろう。最も、言う時が来るとは限らないが。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "んで、そういうお前はどうなんだ？俺を大人の男性として見ているのか？" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ふふん！我からすればご主人はまだお子様だな！あの教皇の爺も我からすれば……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "嘘だろ？" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "えっ……ご主人は心が読めない癖に何を……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "お前も隠し事が下手だな、その反応で全部バレてるよ、馬鹿" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "なっ……くっ……純粋な我の気持ちを弄びおって……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "そうだよ、お前と同じで俺の心だって純粋なんだ、覗き見するのは悪趣味だぞ" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "う……うむ……そうだな……悪かった" },
  { text: "こうは言っているが、俺もだいぶクロセルの事を理解してきた。クロセルにとって相手の心を読んでしまうのは癖のような物なのだろう。意識すれば一時的に行わない事は出来るが、無意識の状態では自然と行ってしまう。そういう物だと納得している。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "それにしてもアカツキの奴……遅いな……この様子だと、やっぱりダメか……" },
  { text: "俺が肩を落とし、そう諦めようとした瞬間の事だった。背後の扉が開き、中から人影が飛び出てくる。咄嗟のことで避けきれず、人影は俺を蹴り飛ばし、俺は地面とキスする事になる。" },
  { chara: { slot: "center", id: "nicholas", expr: "laugh" } },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "てってってっててー！僕！復活！" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "勇者……てめぇ……" },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "この仕事が出来るのは僕だけ、大英雄である僕だけなんだ、今すぐエルちゃんを助けに行かなくては！" },
  { text: "俺は勇者を睨み付けながら立ち上がり、全力で顔をぶん殴る。そして弾かれる。" },
  { text: "人を蹴り飛ばしておいて謝りもしないこいつに心底腹が立つが、物に当たったらアカツキに怒られる。俺は苛立ちを収める為に取り敢えず深呼吸をする事にした。そして、気付いた。勇者がいつもの調子に戻っている。アカツキは一体何を吹き込んだんだ……" },
  { chara: { slot: "lcenter", id: "yamato", expr: "smirk" } },
  { chara: { slot: "left", id: "tia", expr: "normal" } },
  { name: "ティア", who: "tia", expr: "sad", text: "ヤマト、勇者ニコラスはどう？" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あぁ、大丈夫そうだ、ただ勢い余って変な事をしでかさないか、しっかり見張っといてくれ" },
  { name: "ティア", who: "tia", expr: "normal", text: "わかったわ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "それと……クロセルはティアに預けておくか" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "うむ、そうだな、剣士が杖を持つより魔術師が杖を持っている方が自然だろう" },
  { text: "クロセルの身体が光の粒子となって消滅し、後には一本の｜禍々しい《まがまがしい》杖が残された。俺はそれを拾うと、ティアに渡す。" },
  { hide: "right" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "じゃあ三人とも、任せたぞ" },
  { name: "ティア", who: "tia", expr: "normal", text: "任せなさい！" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "僕に任せてくれ！エルちゃんは僕が必ず助け出す！" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "いや……取り敢えずは教皇に話を聞いて無事を確認するだけで良いんだ、奪還は必要ない" },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "あは……あはは……これでエルちゃんは僕の物だ……" },
  { chara: { slot: "right", id: "akatsuki", expr: "serious" } },
  { text: "勇者に続いて部屋から出てきたアカツキに、声を掛ける。そしてアカツキの様子だが、青ざめた様子で少し震えている。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "アカツキ、こいつ本当に大丈夫なのか？" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "ぶっちゃけやらかしたかもしれません……まぁやる気を出して貰えたので結果オーライという事で……" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "では行ってくる！" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "おう……行って来い、くれぐれも目的を見誤るなよー……" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "行っちゃいましたね……" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "行ったな……" },
  { hide: "left" },
  { hide: "center" },
  { text: "ティアと勇者が拠点から出て行くのを見届けると、俺とアカツキはほぼ同時に溜息を吐いた。" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "心配ですね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "取り敢えずクロセルが居るから……最悪の事態にはならないと信じよう" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "そうだと良いんですが……" },
  { text: "アカツキの言う通り、心配ではあるが、まぁ何とかなるだろう。万が一、成果が無くても別の策は既に用意してある。気楽に待つとしよう。" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "ヤマトさん、暇ですか？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あ？暇っちゃ暇だが" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "ならエルさんがやる筈だった家事の消化、手伝って貰えます？" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "あぁそうか……エルが居ないと家事をやれる人間が居なくなるのか……" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "私も特別得意って訳ではないので……出来れば手伝って欲しいんですが" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "分かったよ、手伝えば良いんだろ" },
  { text: "面倒な仕事はやりたくないが、暇しているのは事実だ。三人が帰ってくるまでアカツキの手伝いをするとしよう。こうして俺は、三人が帰ってくるまでの間、アカツキと一緒に家事に明け暮れるのだった。" },
  { hide: "all" },
  { bg: "arcadia_middle" },
  { comment: "EP90: 勇者ニコラス視点 — 神との｜謁見《えっけん》の回想" },
  { pov: "nicholas" },
  { chara: [
    { slot: "center", id: "nicholas", expr: "serious" },
    { slot: "right",  id: "tia",      expr: "normal" },
  ] },
  { name: "福音使徒", text: "止まれ！" },
  { text: "聖都アルカディア中層。そこに位置する聖教会の施設。此処は福音使徒の幹部しか入れない領域。故に、福音使徒の制服を着ていない僕達に対しては当然のように抑止の声が掛かる。" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "通してくれ、僕は勇者ニコラスだ" },
  { name: "ティア", who: "tia", expr: "laugh", text: "祝福の勇者ティアよ" },
  { text: "僕は隣を見る。そこには僕に代わって祝福を手に入れた勇者ティアが居た。あの時、勇者ティアの命が助かったのは祝福のお陰だ。それは分かっている。神も、あの時はああするしか無かったんだろう。ただ、気掛かりなのは一つだけ。" },
  { text: "――僕に祝福が返還されることはなかったという事だ。神は僕を見捨てたのだろうか。僕は祝福を受けた\"あの日\"を思い出す。" },
  { fade: "white" },
  { hide: "all" },
  { bg: "arcadia_upper" },
  { chara: { slot: "center", id: "nicholas", expr: "serious" } },
  { fade: "in" },
  { text: "あの日、勇者の才能を持つ僕は、冒険者として王国で旅をしていた。仲間と共にギルドの依頼をこなす日々。僕は剣術の卓越した才能を持っていた。故に、そんな日々を退屈と感じた事もあった。" },
  { text: "勇者の才能を持っていても、戦う相手は居ない。世界の脅威になる者は居ない。あの頃は平和だった。戦争もない、魔族も居ない、魔王も居ない。" },
  { text: "勇者の才能は飾りだ。他人からそう言われた事もあった。才能に恵まれ、実力のある僕は、英雄ではなく、疎ましい嫌われ者だった。そんな日々が続く中、僕の元に聖教会の使徒がやって来た。" },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "あの……聖教会が僕なんかに何の用事が……" },
  { name: "福音使徒", text: "神の命令だ、付いて来い" },
  { text: "神からの召喚。御告げを聞いた事はあったが、直接会うのは初めてだ。僕は不安だった。僕は勇者である。神の意思の代行者だ。だが、僕は神の為に、世界の為に、何かした事は今まで無かった。" },
  { text: "だから不安だった。神は僕に何か罰を与えるのかもしれない。そう思いながら、僕は聖都の上層へと出向き、遂に神の前に立った。" },
  { name: "神", text: "貴方は勇者ニコラスですね" },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "は……はい、そうです" },
  { bgm: "mystery" },
  { chara: [
    { slot: "center", id: "nicholas",   expr: "surprised" },
    { slot: "right",  id: "el_goddess", expr: "normal" },
  ] },
  { text: "神は少女の姿をしていた。白い衣一枚を纏った、幼い少女の姿をしていた。僕は恐縮すると同時に安堵した。この少女の声は、いつも御告げで聞いているあの声だ。だから驚く事はなかった。" },
  { text: "僕も神も立ち上がっているが、身長差がある為、僕が神を見下ろす形になっている。不敬ではないかと不安になり、僕は辺りをきょろきょろと見渡す。" },
  { text: "が、その部屋には神と僕を除いて人は誰一人も居なかった。" },
  { name: "神", who: "el_goddess", expr: "smile", text: "ふふっ……そんなに恐縮しなくても良いんですよ、誰も見ていませんから" },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "そうですね……すいません" },
  { name: "神", who: "el_goddess", expr: "normal", text: "さて、単刀直入に問いましょう、今日貴方を此処に呼んだのは何故だと思いますか？" },
  { text: "ドキリと胸が跳ねる。何かを言い渡される覚悟は出来ていたが、質問の形を取って問われるのは想定外だった。僕は内心パニックになる。何か答えなければ。思考が空回りして、額に汗が流れる。そして僕は、頭に浮かんだ言葉をそのまま口にしてしまった。" },
  { chara: { slot: "center", id: "nicholas", expr: "serious" } },
  { name: "ニコラス", who: "nicholas", expr: "surprised", text: "か……神様は僕に罰を与える為に……此処に呼んだのだと……そう思いました" },
  { name: "神", who: "el_goddess", expr: "smile", text: "あはっ……あははは！" },
  { text: "少女……いや神は、その時、愉快だとばかりに笑いだした。本当に、こうして傍から見れば｜無垢《むく》で幼さを宿したただの少女だ。この世界を作り出した創造神には、到底見えない。" },
  { name: "神", who: "el_goddess", expr: "smile", text: "あは……面白いですね、貴方は" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "は……はぁ……？" },
  { name: "神", who: "el_goddess", expr: "sad", text: "しょうがないですね、答えを教えてあげましょう、私が貴方を此処に呼んだのは、貴方に祝福を与える為です" },
  { chara: { slot: "center", id: "nicholas", expr: "surprised" } },
  { name: "ニコラス", who: "nicholas", expr: "surprised", text: "僕に……祝福を？" },
  { text: "その時、僕は神の言っていることを正しく理解できていなかった。そもそも、祝福という物が存在する事自体、僕は知らなかったからだ。先々代の魔王、グレモリーの時代。祝福の勇者は居なかった。" },
  { text: "或いは、必要なかったのかもしれない。だから、当時の世界では祝福の存在は広く認知されていなかったのだ。" },
  { name: "神", who: "el_goddess", expr: "normal", text: "その通り、私は貴方に祝福を与える事にしました" },
  { name: "ニコラス", who: "nicholas", expr: "surprised", text: "えっと……すいません、祝福とは？" },
  { name: "神", who: "el_goddess", expr: "smile", text: "え……貴方は祝福を知らないのですか？" },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "すいません、名前は聞いた事があるんですが、具体的にどういう物かは……" },
  { name: "神", who: "el_goddess", expr: "sad", text: "しょうがないですね、私が説明してあげます、祝福というのは……要するに不老不死の才能です" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "不老不死？" },
  { name: "神", who: "el_goddess", expr: "normal", text: "そうです、煮られても焼かれても斬られても寿命でも死なない力です、魅力的でしょう？" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "確かに……魅力的な力ではあると思います、でも何故僕に……？" },
  { name: "神", who: "el_goddess", expr: "sad", text: "それはですね……" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "それは？" },
  { name: "神", who: "el_goddess", expr: "smile", text: "面白そうだったからです、貴方に祝福を与えれば、愉快な物語を紡いでくれる、そう思ったから私は貴方に祝福を与える事にしました" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "は……はぁ？" },
  { text: "神は、純真｜無垢《むく》で一切の悪意の無い、満面の笑顔で言い放つ。その時……僕は恐ろしいと思った。この少女が、神であり、世界を動かす力を持っているという事に。" },
  { name: "神", who: "el_goddess", expr: "sad", text: "祝福の勇者ニコラス……だけじゃインパクトが足りないですし異名でも付けましょうか、そうですね……｜抜刀斎《ばっとうさい》ニコンとかどうです？" },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "僕の武器は刀じゃなくて剣なんですが……" },
  { name: "神", who: "el_goddess", expr: "normal", text: "私が付けた名前が不満ですか？" },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "いえ……そういう訳では……" },
  { text: "神の命令は絶対だ。神が決めた事なら、最初から僕に拒否権なんて無い。だから僕は今日から祝福の勇者であり、｜抜刀斎《ばっとうさい》ニコンだ。こうして諦め……受け入れてしまえば意外と気楽かもしれない。" },
  { name: "神", who: "el_goddess", expr: "normal", text: "では｜抜刀斎《ばっとうさい》ニコン、貴方に祝福を与えます" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "はい、分かりました" },
  { text: "神が宣言し、僕がそれを肯定する。そして僕は、神から祝福を授かるのを待っていたのだが……長い間、静寂が続く。きっと、神聖な儀式故に時間がかかっているのかもしれない。僕は根気良く待たねばならないと気を引き締める。" },
  { chara: { slot: "right", id: "el_goddess", expr: "blank" } },
  { name: "神", who: "el_goddess", expr: "smile", text: "……いつまで呆けて突っ立っているつもりですか？" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "え？" },
  { name: "神", who: "el_goddess", expr: "sad", text: "終わりましたよ、帰ってよし" },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "まだ何もされてないんですが……" },
  { name: "神", who: "el_goddess", expr: "blank", text: "うん……？既に祝福は与えましたよ？試しに一度死んでみますか？" },
  { fx: "shake" },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "結構です！僕が悪かったので……どうか殺さないで……" },
  { name: "神", who: "el_goddess", expr: "normal", text: "そうですか……折角戦闘系の才能を持った肉体を得たので少し剣を振ってみたかったのですが" },
  { text: "残念そうに俯く。神は本気だ、本気で祝福の力を試す為に僕を殺そうとした。そこに躊躇いの感情は一切無かった。やはり僕の神に対する考えは変わらない。神は恐ろしい存在だ。" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "僕は帰って良いんですかね？" },
  { name: "神", who: "el_goddess", expr: "smile", text: "そう言った筈ですが" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "分かりました、ありがとうございます" },
  { name: "神", who: "el_goddess", expr: "smile", text: "今後の活躍に期待していますよ、｜抜刀斎《ばっとうさい》ニコン" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "はい、頑張ります" },
  { text: "こうして、僕は祝福を授かったのだ。そう、こうしてあれから何年も経った。僕は祝福の勇者として、この世界の悪を払い、正義を貫いてきた。ヤマト君の力を借りて、魔王の封印も成し遂げたのだ。" },
  { text: "僕は、立派に勇者として生きていた筈だ。それなのに、僕は祝福を剥奪された。神にとって、もう僕は用済みなのだろうか。" },
  { text: "――否。そうじゃない。物事はもっと単純なんだ。僕は神と会って、神がどういう人物か見極めた。きっと、祝福がティアに移ったのは、面白そうだから、とかそういう理由なんだろう。" },
  { text: "神は｜俯瞰《ふかん》的に世界を見ている。そしてこの世界が面白い物語になるように手を引く。ティアが死ぬ物語は神にとって面白くない物語《ストーリー》だった、それだけの話なんだ。きっと。" },
  { fade: "white" },
  { hide: "all" },
  { bg: "arcadia_upper" },
  { comment: "現在: 上層への侵入と迷路探索" },
  { bgm: "tension" },
  { chara: [
    { slot: "left",   id: "nicholas", expr: "serious" },
    { slot: "right",  id: "tia",      expr: "normal" },
  ] },
  { fade: "in" },
  { name: "福音使徒", text: "……勇者様ですか、この先は上層ですが、一体何用で……" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "神の御告げがあったんだ、僕達は教皇と話をしなければならない" },
  { name: "福音使徒", text: "そうですか、ですが今エンド様は……" },
  { name: "ティア", who: "tia", expr: "sad", text: "聖教会は神に絶対の忠誠を誓ってる筈よ、どんな事情があるのか知らないけど……通してくれるわよね？" },
  { name: "福音使徒", text: "っ……分かりました、先に進んで下さい" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "助かるよ、ありがとう" },
  { text: "僕は福音使徒に小さくお辞儀をすると、施設の奥深く、上層へと繋がる転移魔法陣へと進む。こうして僕と勇者ティアは、上層へと辿り着いた。" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "教皇は何処だろう" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "｜魔術回路改竄《カスタマイズ》……｜略式詠唱展開《ファストキャスト》……――空間魔術 ｜空間精査《サーチ》" },
  { text: "僕がそう呟いたかと思えば、勇者ティアの持っている杖が喋りだす。杖の姿でも魔術を行使できるのか。と……感心しながら僕は｜魔杖《まじょう》の反応を待つ。" },
  { name: "ティア", who: "tia", expr: "normal", text: "あー！もう、私がやろうと思ったのに" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "我がやった方が早い、取り敢えず大凡人のいる位置は特定できた" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "案内してくれ" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "うむ、任せろ" },
  { text: "そして、僕達は上層を杖の指示に従って進む。上層、と一言で称したが、この巨大な建築物は迷路のように複雑な構造をしている。" },
  { text: "前回来た時は教皇の案内があって神の居る場所まで辿り着けたが、今度の目的は神の居る場所に向かうことではない。" },
  { text: "もし｜魔杖《まじょう》や勇者ティアのように魔術を使える人が居なければ、教皇の捜索は困難を極めていただろう。二人には感謝せねばならない。" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "前方の十字路を左だ、その先の部屋に人が固まっている" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "教皇はそこに？" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "恐らく……だがな、場合によってはエルも居ると考えられる" },
  { name: "ティア", who: "tia", expr: "normal", text: "今回の作戦は奪還じゃないんだったよね、まずは教皇に話を聞く事が先決……だっけ" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "うむ、今日は利口だな、勇者" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "まるで普段が馬鹿みたいな言い方じゃないか、酷いな" },
  { name: "ティア", who: "tia", expr: "laugh", text: "事実じゃないの？" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "なんだって！？僕は馬鹿だと思われていたのかい！？" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "声を荒げるな、神聖な場所に変わりはないのだぞ" },
  { name: "ニコラス", who: "nicholas", expr: "surprised", text: "ごめん、えっと……この扉の先であってるよね" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "うむ、そうだ" },
  { text: "無限に続くかと思われた迷路の終着点。僕は扉の前に立ち、躊躇う事無く押し開いた。中に足を踏み入れると、何人かの人影が固まっているのが目に入る。どうやら、何かを囲んで話し合っているようだ。此処からでは何を囲んでいるのかよく見えない。" },
  { name: "福音使徒", text: "何者だ！？" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "僕だ、勇者ニコラスだ" },
  { name: "ティア", who: "tia", expr: "laugh", text: "勇者ティアよ" },
  { name: "福音使徒", text: "あぁ……勇者様でしたか……どうして上層に？" },
  { text: "侵入者である僕達を咎める福音使徒に軽く返答をしながら、僕は部屋に居る人間に次々と視線を向けていく。探している人物は唯一人だ。これだけ人が集まっているのだから、必ずこの部屋に居る。" },
  { chara: [
    { slot: "left",   id: "nicholas", expr: "serious" },
    { slot: "center", id: "eve_end",  expr: "serious" },
    { slot: "right",  id: "tia",      expr: "angry" },
  ] },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "――私に用があって来たんだろう？" },
  { text: "必死に探す必要はなかった。教皇イヴ・エンドは福音使徒の中から現れ、僕達の前に立ちはだかる。僕達と教皇の間に緊張が走る。心做しか、教皇の語調が普段よりも強いようにも感じる。" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "あぁ、そうだよ、僕達は教皇と話をする為に此処に来た" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "聞きたいのは、エルという少女の事か" },
  { name: "ティア", who: "tia", expr: "angry", text: "そうよ！どうして聖教会はエルを拉致したの！？しっかり説明しなさい！" },
  { name: "イヴ・エンド", who: "eve_end", expr: "cold", text: "あの少女が、聖域に立ち入って、神と接触した疑いがあってね、勇者ティア、君には心当たりがあるんじゃないかい？" },
  { text: "一先ず、これで容疑は分かった。エルちゃんが神と接触した。それが事実か冤罪かは分からないが、聖教会が動く理由としては妥当な所だろう。他に聞くべき事は……" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "エルちゃんは無事なんだろうね、手荒な真似はしていないな？" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "あぁ、現時点での無事は保証しよう、此方としても手荒な真似はしたくないと思っている" },
  { name: "ティア", who: "tia", expr: "sad", text: "それで……本人は神と接触した事を認めているの？" },
  { name: "イヴ・エンド", who: "eve_end", expr: "surprised", text: "……いや、認めてない、この様子だと……君達が手引きをした訳では無さそうだね" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "何のことだい？" },
  { text: "教皇は、品定めをするように僕達を順番に見ていくと一歩だけ横に退く。そして教皇の立っていた場所の後ろには、\"破壊された状態\"の手枷が転がっていた。" },
  { chara: { slot: "left", id: "nicholas", expr: "surprised" } },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "どういう事だい……？エルちゃんは何処に……" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "私達聖教会は、この部屋に彼女を連れ込み、手枷で拘束していた" },
  { name: "ティア", who: "tia", expr: "surprised", text: "でも此処にエルは居ないわよね……まさか！？" },
  { chara: { slot: "center", id: "eve_end", expr: "cold" } },
  { name: "イヴ・エンド", who: "eve_end", expr: "surprised", text: "そのまさか、だろうね。彼女は此処に居ない" },
  { text: "教皇は呆れるように溜息を吐くと、重苦しい面持ちで、僕達に事実を告げた。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "――少女エルは逃亡した" },
  { fx: "shake" },

  // ---------------------------------------------------
  // Scene 3: search_underground — 地下施設の再会 (EP91〜92)
  // ---------------------------------------------------
  { label: "search_underground" },
  { pov: null },
  { hide: "all" },
  { bg: "bathhouse_base" },
  { comment: "EP91: 行方不明 — 捜索会議" },
  { chara: [
    { slot: "left",   id: "tia",     expr: "sad" },
    { slot: "center", id: "yamato",  expr: "surprised" },
    { slot: "right",  id: "crocell", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あ？エルが逃亡した？" },
  { text: "俺は帰ってきた勇者とティア、そしてクロセルの三人から、報告を受けていた。この場にはエルを除いた全員が揃っている。どうやら攫われたエルを助ける為に、Vや瀬野の奴も協力する姿勢らしい。何をするにも人手は多い方が良い。迷惑になる訳でも無いから、俺は容認している。肝心の報告だが……見事に想定外な事実を突き付けられ、俺は困惑の表情を浮かべる。" },
  { text: "まさかエルが自力で逃亡するとは、あいつにそんな度胸と力があるとは思えなかった。無論、エルは拠点に帰って来ていない。そもそもエルは上層から出る手段を持っていない筈だ、今も上層に居ると考えるのが妥当だろう。" },
  { name: "ニコラス", text: "僕は捜索に協力すると言ったんだけど、信用出来ないから帰ってくれと言われてしまって" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "おいおい、まさか持ち帰った情報がそれだけとは言わないよな？" },
  { name: "ティア", who: "tia", expr: "normal", text: "もちろんよ、まずエルが聖教会に拘束された理由だけど、それはエルが神様と接触したから、らしいわ" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "は？いつの話だよ……" },
  { name: "ニコラス", text: "僕達が魔王領へと出発する前らしい" },
  { text: "勇者にそう告げられると、俺は記憶の糸を辿る。確かに、あの日はエルが単独で行動していた時間があった。戸締りに時間が掛かった……ってのが嘘だとすれば、確かに上層に行って神に会うだけの時間はある。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あの時か……でもエル一人でどうやって神様に会いに行くんだよ" },
  { name: "ニコラス", text: "それは……僕の口から言うべきではないね" },
  { name: "ティア", who: "tia", expr: "normal", text: "……わたしが連れてったのよ" },
  { text: "ティアがぼそりと呟く。俺は一瞬、その言葉の意味を理解できず、思考停止して動きが止まる。そして、ようやく脳が再稼働を始めたかと思えば、俺は思わず叫んでいた。" },
  { chara: { slot: "center", id: "yamato", expr: "surprised" } },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "はぁ！？冗談だろ！？" },
  { name: "ティア", who: "tia", expr: "laugh", text: "本当よ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "いやいや……まぁ仮に本当だとするぞ、なんでそんな事したんだよ" },
  { name: "ティア", who: "tia", expr: "sad", text: "神の御告げがあったから" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "神の命令でエルを上層に連れてったってのか？" },
  { name: "ティア", who: "tia", expr: "sad", text: "そうよ" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "嘘だろ……神は何でそんな御告げを……" },
  { text: "俺は頭を抱えて、近くにあった椅子に座り込む。取り敢えず、ティアの言葉を信じるとすれば、あの時にエルが上層に行っていたのは事実らしい。信じられない話だが、ティアが嘘を吐くとは思えない。つまり事実という事になる。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "ふぅ……悪い、取り乱した" },
  { name: "アカツキ", text: "まさかそんな……私も正直信じられない話です" },
  { text: "冷静に話を聞いていたアカツキも、こればっかりは直ぐに鵜呑みに出来ないらしい。当然だ。理由が無い。エルが神に会う理由も、それを神が助ける理由も、少なくとも俺達が分かる範囲では存在しないのだ。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "ティア、お前はエルが神に会ったのを見たのか？" },
  { name: "ティア", who: "tia", expr: "normal", text: "いいえ、神の御告げはエルを上層に送り届けるという事だけだったから、上層に送り届けたらわたしは先に皆の元に戻ったわ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "なるほどな、それでエルは何か目的意識を持って動いていたのか？それともティアに従っただけか？" },
  { name: "ティア", who: "tia", expr: "laugh", text: "多分だけど……何か目的を持って動いてたんだと思う、それが神に会う事なのかは分からないけど" },
  { name: "ニコラス", text: "これは教皇に聞いた話なんだけど、あの日は警備が手薄で上層は勿論、聖域に侵入する事も可能だったらしい" },
  { text: "俺は二人の言葉を聞いて、心の内で自問自答をしながら小さく頷く。" },
  { text: "エルは警備が手薄な時を狙った。つまり確実に何らかの意図を持って上層へと向かった事になる。不可解な点は神は何故それを手伝ったのかという事。ただし、前述の点から、少なくともエルの目的は神にとって利のある行動だったと推測できる。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "さて……クロセル、どう思う" },
  { chara: { slot: "right", id: "crocell", expr: "serious" } },
  { name: "クロセル", who: "crocell", expr: "normal", text: "客観的な意見を述べるとすれば、聖教会の主張は正しく、エルが怪しいな" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "同感だ、アカツキの言っていた通り、エルは俺達に何かを隠している" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "我が改めて分析の才能を使えば、エルの秘密を露見させる事は恐らく可能だろう" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "その為には、エルを見付けないといけないな" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "うむ、これで当面の方針は決まったな" },
  { text: "俺はクロセルと顔を見合わせ、頷き合う。そして、俺は立ち上がると、仲間達に向けて声を掛ける。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "話は聞いてただろ、何をすれば良いかは分かるな？" },
  { name: "ニコラス", text: "エルちゃんは上層に居るんだろう？それなら僕達に打つ手は……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "クロセル、外に福音使徒は何人居る？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "五人だな" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "俺達の会話は聞こえるか？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "エルが拠点に戻る事を考えて張り込んでいるだけのようだ、中の会話までは聞こえていないだろう" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "よし、なら良い" },
  { name: "V", text: "いつの間に見張られていたんですね……気付きませんでした" },
  { text: "Vが驚いたように目を丸くする。他の顔ぶれも驚いたような反応を見せている。どうやら気付いていたのは俺とクロセルとアカツキの三人だけらしい。窓の外を見ると、そこにちらりと人影が見える。素人だ、こんなの誰でも気付く。" },
  { chara: { slot: "center", id: "yamato", expr: "smirk" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "さて、結論から話すとだな……エルは恐らく上層には居ない" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "まぁ、そう考えるのが妥当だな" },
  { name: "ニコラス", text: "ヤマト君もクロセルちゃんも……本気で言ってるのかい？" },
  { name: "アカツキ", text: "お二人の事ですから、そう結論付ける何か考えがあるんでしょう" },
  { name: "瀬野", text: "えっと……ヤマト、上層から降りるには中層行きの転移魔方陣を必ず通る必要があるんだよ、そこを見張る福音使徒が居ないとは思えないんだけど……" },
  { name: "ニコラス", text: "さっき僕達が上層に行った際も、見張りが居た、それも一人二人じゃない、厳重な警備が敷かれてたよ" },
  { text: "瀬野と勇者が口を挟む。彼らの主張は尤もだ。実際、聖教会もそう考えて上層でエルを探しているのだ。だが、事実は違う。俺は先程のティアの話を聞いて確信した。エルは上層に居ない。そして、俺は皆に向かってそう考える根拠を口にする。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "エルが神に会った日、ティアはエルを上層に送り届けた、間違いないな？" },
  { name: "ティア", who: "tia", expr: "sad", text: "えぇ、間違いないわよ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "その後、エルは俺達と共に魔王領へ向かった。これ、おかしいとは思わないか？" },
  { name: "アカツキ", text: "あっ……ティア様はエルさんを上層に送り届けて、その後に下層まで降りてきた。エルさんは上層に一人取り残された事になりますね" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "そうだ、そして取り残された筈のエルは単身で上層から下層まで降りてきた、この事から考えられる事実は……" },
  { name: "瀬野", text: "聖教会の転移魔方陣を使わずに、上層から下層に降りる何らかの手段がある？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "その通り、少なくともエルはその手段を使えると仮定できるな、それがエル自身の能力なのか、或いは上層に秘密の通路のような物があるのか、流石にそこまでは断定出来ないが、少なくともエルは下層に降りる手段を持っているはずだ" },
  { text: "俺は｜虚空《こくう》に向けてぴしっと指を差しながら、そう告げる。瀬野が俺を見ながら目を輝かせている。瀬野は俺が格好付ける時に毎回こんな反応を示す。" },
  { text: "自惚れるつもりはないが、瀬野にとって俺は憧れの存在って奴なんだろう。多分。因みに、他に面子の反応は何とも言えない物だ。頷いてる奴も居れば驚いてる奴も居る。呆れてる奴からは少し目を逸らしておこう。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "取り敢えず、これで分かったか？俺達が今何をすれば良いか" },
  { name: "アカツキ", text: "下層に居ると思われるエルさんを見付け、クロセルさんの元に連れて来る、ですね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そうだ、聖教会に比べればだいぶ見劣りするが、人手は十分にある、手分けして探せば見付けられる筈だ" },
  { name: "V", text: "あのー……もしエルさんが抵抗した場合はどうするんですか？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "その場合は諦める、仮に何らかの事情があったとしても、エルが俺達の敵である可能性は低いからな、仮に抵抗された場合はエルの自由意思を尊重する" },
  { text: "Vの質問に、俺はそう答えた。そして、暫くの静寂。俺の発言に対して否定の声は無い。つまりは肯定という事だ。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "さぁ、何をすれば良いかは分かったな？" },
  { name: "ティア", who: "tia", expr: "normal", text: "そんな回りくどい言い方せずに、普通に命令してくれれば良いのに" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "俺には指揮のディザビリティがあるからな……直接命令すると失敗に繋がる可能性があるんだ" },
  { name: "瀬野", text: "ディザビリティ……？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "才能指数0の才能の事だ、無能や無才とも称される" },
  { name: "瀬野", text: "えっ……でもヤマトは確か……" },
  { text: "俺は手を構えて瀬野の言葉を制止する。こうしてゆっくりと説明してる時間は無い。頭のキレる教皇の事だ、俺達と同じ事実に気付くのは時間の問題だと言える。故に、俺達は早急に動き出すべきだろう。誰も動かないなら俺が動く。俺は立ち上がって玄関へと歩き出した。" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ご主人の代わりに我が指示を出そう、捜索は日没をタイムリミットとする、日が暮れたら帰還すること、夜闇に紛れた人を探すのは難しいからな" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "クロセル、助かる" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "気にするな、それよりも……ご主人の意図が読める事が役立っただろう？" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あぁ……そうだな、確かに役立った、その調子で頼む" },
  { name: "ティア", who: "tia", expr: "laugh", text: "｜魔杖《まじょう》、質問よ、エルを見付けたらどうすれば良いの？拠点に連れ帰ったら福音使徒に見つかっちゃうわよ" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "うむ、聖都に来た当初に泊まっていた宿屋に連れて来る事にしよう、我はそこで待機する、Vと勇者とゼノは場所が分からないだろうから我に付いて来て場所を確認してから捜索に当たる事にしよう" },
  { name: "ニコラス", text: "うん、分かったよ" },
  { name: "ティア", who: "tia", expr: "sad", text: "場所が分かるわたし達は早速探しに行かないとね、行ってくるわ" },
  { name: "アカツキ", text: "ティア様が心配ですが祝福もありますし大丈夫だと信じましょうか、私も行ってきます" },
  { text: "こうして俺達は次々に拠点を後にする。クロセルは付いて来ない為、俺は単独行動となった。完全に一人で行動するのは久々だ。日没まではあと6時間ほど、それまでに見付かると良いが……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "片っ端から探すのは時間の無駄だ、エルが向かいそうな場所を考えて効率的に探すべきだろう" },
  { hide: "all" },
  { bg: "arcadia_lower" },
  { chara: { slot: "center", id: "yamato", expr: "serious" } },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "あの馬鹿……逃げるという事は罪を認めた事になるだろ……面倒掛けさせやがって……" },
  { text: "正直に言えば、エルの逃亡は想定外だった。汚職のあった下層中層はともかく、聖教会の上層部は信頼できる。身柄を拘束される事はあっても、手荒な真似はしないと思っていた。だから一時的にエルの身柄を預け、事情を精査してからエルを弁護して救出する、というプランだったのだが。" },
  { text: "ただ、エルの容疑は冤罪ではなく事実のようだから、弁護のしようがあるかと言われると疑問だ。同時に、神に接触しただけで罪に問われるのかという点も根本的に疑問ではある。彼女も魔王封印に尽力した功労者の一人だ。神に会った事ぐらい、目を瞑っても良いと思うのだが。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そう言えば教皇の奴……神の話をするのを露骨に嫌がってたな……あれはどういう事だ？" },
  { text: "神の意志の代行者である聖教会が、神に関する話題を避けるのは何か矛盾しているように思える。教皇が神に関する何かを隠しているのは確実だが、それが何か、分かるようで分からない。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "これも後でクロセルに知恵を借りるか……流石に情報量が少なすぎて分からん" },
  { text: "そう一人で呟きながら、俺は聖都を駆けていた。ともかく、今はエルの事だ。俺は記憶の糸を辿り、エルが行きそうな場所を考えてみる。" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "聖都に訪れた当初に泊まっていた宿屋……だとすればクロセルが見付けてくれるだろうから除外、下層の聖教会……論外、くそっ……エルは殆ど拠点に居たからあいつが知ってる場所で隠れられそうな場所なんか……" },
  { text: "待てよ？エルが知っている可能性があって、尚且つ隠れる事の出来る場所。候補が一つだけあるじゃないか。あの事件はエルも知っている。あの場所の記された地図は誰でも見れた筈だ。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "行ってみる価値は十分あるな……" },
  { text: "俺はニヤリと笑う、あの場所は拠点から距離があるし、本当に居る可能性は低いただの博打だ。足を止め、進行方向を変える。そして目指すは……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "違法奴隷売買地下施設跡……身を隠すにはぴったりな場所だ" },
  { hide: "all" },
  { bg: "underground_prison" },
  { comment: "EP92: 違法奴隷売買地下施設跡での再会" },
  { bgm: "heartwarm" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "ふぅ……着いたか" },
  { text: "目的地の前に立ち、｜徐《おもむろ》に振り返る。誰も居ない。尾行はされていないな。俺達がこうして動き出した事は教皇に報告されているだろう。そうなると、エルが下層に居る事が気付かれるのも時間の問題だ。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "まぁ、先に見付ければ無問題だから構わないが" },
  { text: "俺は奴隷売買に使われていた地下施設の扉を開く。そこまで昔の話という訳でも無いのだが、少しだけ懐かしい感覚だ。地下へ続く階段を降りていくと、左右に牢獄が設置された長い廊下に出る。当然だが、誰も残っていない。違法奴隷は既に保護された後だ。尤も、違法ではない奴隷制度自体も、犯罪者の更生という大義名分があれど、あまり良い気はしない。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "なんて考える程度には……俺も丸くなったな……" },
  { text: "この世界に来る前の俺であれば、違法だろうが合法だろうが奴隷売買の善悪になど興味すら示さなかっただろう。寧ろ、もし仮に日本でも奴隷売買が行われていたら、俺はそれを利用する側の立場だったかもしれない。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "そうだ、俺もアダンの奴も、性根は大して変わらない" },
  { text: "俺は本来裁かれるべき人間だ。その事実を、こんな時でありながらも再び痛感する。そんな風に奴隷売買について思考を巡らせている内に、地下施設の最深部までやってきた。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "相変わらず悪趣味な部屋だな……" },
  { text: "鎖や｜拷問《ごうもん》器具などはあの時のままだ。床の｜血痕《けっこん》もそのまま、敢えて違う点を挙げるとすれば、本棚に詰め込まれていた書類の類が全て無くなっているぐらいだろうか。そして、そんな部屋の中央、壁に背を預け、｜蹲《うずくま》るようにして座っている一人の少女。" },
  { chara: [
    { slot: "center", id: "yamato", expr: "normal" },
    { slot: "right",  id: "el",     expr: "sad" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "見つけたぞ、エル" },
  { name: "エル", who: "el", expr: "sad", text: "ヤマト……様？どうして此処が……" },
  { chara: { slot: "center", id: "yamato", expr: "smirk" } },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "仲間が隠れる場所ぐらい分かって当然だろ" },
  { text: "エルが驚いたような顔をして俺を見上げている。そして、暫く見つめ合ったかと思えば、エルは何処か嬉しそうにくすくすと笑い出す。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "何笑ってんだよ" },
  { chara: { slot: "right", id: "el", expr: "smile" } },
  { name: "エル", who: "el", expr: "smile", text: "あはは……ごめんなさい……私も仲間として認めて貰えてたんだなって" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "当たり前だろ、俺とお前はずっと前から仲間だ" },
  { name: "エル", who: "el", expr: "smile", text: "そっか、嬉しいな" },
  { text: "嬉しそうに笑う彼女を一瞥すると、俺は気恥ずかしくなって目を逸らす。大した事では無いと思うのだが、彼女としては本当に嬉しいのだろう。本当に可愛らしい笑顔だ。エルの息が整い、笑顔が消えると、そこに気まずい沈黙が訪れる。そうだ、俺は何をしに来たんだ。" },
  { text: "こんな風にエルと見つめ合う為に来た訳じゃない。俺は賢者のように冷め上がった思考で、エルに問い掛ける。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "ところでエル、上層に行ったのは本当なのか？" },
  { text: "エルはそんな問いに対し、少し困ったように小さく笑うと、辺りを軽く見渡し、ゆっくりと言葉を紡ぎ出す。" },
  { name: "エル", who: "el", expr: "sad", text: "うん、事実だよ" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "神に会ったってのも本当か？" },
  { name: "エル", who: "el", expr: "sad", text: "事実だよ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうか……なんでそんな事をしたんだ？" },
  { text: "早くも俺はこの問答における核心を突く。そんな俺の質問に対し、エルは申し訳なさそうに頭を垂らし、黙り込む。まずい、少し事を急ぎ過ぎたか。この質問は今のエルにはまだ早いだろう。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "いや、別にそれは答えなくて良い、質問を変えるぞ、どうして逃げたんだ？" },
  { chara: { slot: "right", id: "el", expr: "sad" } },
  { name: "エル", who: "el", expr: "normal", text: "教皇にこの肉体を破壊される可能性があったから" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "この肉体？エルの事だよな？" },
  { name: "エル", who: "el", expr: "smile", text: "そうだよ？" },
  { text: "自分の身体なのにまるで他人の身体のような言い方をしている。少し妙な言い回しだ。まぁ、そんな事は｜些事《さじ》である。今は問答に集中しよう。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "教皇と言えどそんな手荒な真似はしないだろ……いきなり拘束されて、怖かったのか？" },
  { name: "エル", who: "el", expr: "troubled", text: "違うよ、教皇は本気で私を破壊するつもりだった、彼にとって神は絶対、そんな存在である神に触れた私を生かしておくとは思えない" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "教皇の奴、そんな危険人物なのか……？俺は知らないが……" },
  { name: "エル", who: "el", expr: "sad", text: "普段の温厚で優しい｜翁《おきな》は世を忍ぶ仮の姿、彼の本質は神を絶対と崇め、罪には等しい罰を以て断罪する、そんな思想を持った、恐ろしい人間だよ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "なんでそんな事を知ってるんだ……？" },
  { chara: { slot: "right", id: "el", expr: "troubled" } },
  { name: "エル", who: "el", expr: "sad", text: "……" },
  { text: "これもダメらしい。まぁ別にそこまで重要そうではないから良いのだが。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "取り敢えず、教皇から逃げる為に拘束を解いて此処まで来たんだな" },
  { name: "エル", who: "el", expr: "normal", text: "うん、そうだよ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そうか……まぁお前が言うならそうなんだろう" },
  { text: "教皇、聖教会は今でもエルを追っている。そして容疑が事実だとすると、その罪を教皇は罰を以て裁くだろう。エルの言葉が確かなら、それは死罪。エルは殺される事になる。そんな事にしてはいけない。俺が、俺達でエルを守らねばならない。" },
  { text: "だが、それは聖教会を敵に回すという事になる。教国で生きていく上で、聖教会と敵対するという事は、この地での安らかな暮らしは失われるという事だ。エルか、平和な暮らし、そのどちらかを捨てなければならない。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "くっ……" },
  { name: "エル", who: "el", expr: "sad", text: "ヤマト様……？" },
  { text: "今直ぐは決められない。それに、これは俺一人の問題ではない。Vとファイ、勇者の三人は他人として生きる事で逃れる事も出来るだろうが、クロセルは勿論、アカツキやティア、瀬野までも危険に巻き込む事になる。これは皆で話し合って決めるべきだ。俺一人の独断で決めていい事ではない。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "エル、俺と一緒に来てくれるか？" },
  { name: "エル", who: "el", expr: "smile", text: "多分……拠点は聖教会に見張られてる" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "分かってる、だから合流地点は別の所だ、そこで今後について話し合う" },
  { chara: { slot: "right", id: "el", expr: "sad" } },
  { name: "エル", who: "el", expr: "sad", text: "もし、聖教会が私を襲ったら、今度こそ守ってくれる……？" },
  { text: "エルは、両手で己の身体を抱き締めながら、俺の顔を見上げ、首を傾げて尋ねる。エルがこんな弱気な姿を見せるのも珍しい。多分、本当に怖いのだろう。" },
  { chara: { slot: "center", id: "yamato", expr: "smile" } },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あぁ、任せろ" },
  { text: "俺はそう断言すると、エルの手を引いて立ち上がる。元より俺の心は決まっている。何を隠しているにしろ、どんな事情があれ、エルを助ける。仲間を助ける。それだけだ。帰り道で聖教会に見つかっては元も子もない。こういう状況に備えて、マントを持ってきていて助かった。" },
  { text: "俺はマントでエルの頭と顔を隠すと、そのまま手を引いて地下施設の出口へと歩いていく。エルも抵抗する事なく、黙って俺に付いて来た。そして、牢獄に挟まれた廊下を再び進み、階段を登って地上へと出る。そして外への扉に手を掛けて、ふと気が付く。" },
  { chara: { slot: "center", id: "yamato", expr: "serious" } },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……人の気配がする" },
  { name: "エル", who: "el", expr: "surprised", text: "えっ……？それってまさか……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "チッ……教皇の奴、やはり頭が回るようだな、エル、そこの木箱の裏に隠れてろ" },
  { text: "エルが近くの木箱の陰に隠れる。それを確認すると同時に、俺は扉を開いた。" },

  // ---------------------------------------------------
  // Scene 4: klaus_duel — ｜聖一位《せいいちい》クラウス戦 (EP92)
  // ---------------------------------------------------
  { label: "klaus_duel" },
  { hide: "all" },
  { bg: "arcadia_lower" },
  { bgm: "tension2" },
  { text: "案の定、そこには数名の福音使徒が待機しており、建物から出た俺は瞬く間に包囲される。" },
  { chara: [
    { slot: "center", id: "yamato", expr: "normal" },
    { slot: "right",  id: "klaus",  expr: "normal" },
  ] },
  { name: "福音使徒", text: "止まれ！聖教会の者だ！" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "おう、分かった。こんな｜辺鄙《へんぴ》な場所にどうしたんだ？" },
  { name: "クラウス", who: "klaus", expr: "normal", text: "あぁ、突然呼び止めてすまないね、繰り返すが見ての通り私達は聖教会の人間で、ある人物を探しているんだ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そうなのか、それはご苦労な事だな" },
  { text: "｜飄々《ひょうひょう》とした態度を取っている物の、内心は焦りに侵され、徐々に冷静な思考が失われていく。冷や汗が流れる。そして、そんな動揺を悟られないように、集中して表情を作る。" },
  { name: "クラウス", who: "klaus", expr: "cold", text: "聖教会の権限を以て質問しよう、君はこんな時間に、こんな場所で何をしていたんだい？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "こんな時間……って言ってもまだ明るいだろ、俺は此処で違法奴隷売買が行われていないか確認しに来たんだ" },
  { name: "クラウス", who: "klaus", expr: "cold", text: "違法奴隷売買、聖教会下層部の汚職の存在は公開されていない情報だ、君が何故それを知っている？" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "俺が違法奴隷売買を摘発した張本人だからだよ、ヤマトって名前に聞き覚えはないか？" },
  { name: "クラウス", who: "klaus", expr: "normal", text: "そうか、君がヤマト君か……なら、隠す必要も無いね、君は少女エルを匿っているな？" },
  { text: "まずい、ミスをした。エルと俺にラインがある以上、名前を出すべきでは無かった。どうする？俺の周りには聖教会の制服を着た福音使徒が四人。戦闘して無力化するのは厳しい。だからと言ってこのまま誤魔化す事も難しいだろう。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "何の事だ？" },
  { name: "クラウス", who: "klaus", expr: "cold", text: "しらばっくれても無駄だ、君は仲間である少女エルを私達より先に発見し、匿っている、いや……正確に言えば匿おうとしている、というべきか" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "どうしてこの場所が分かった" },
  { name: "クラウス", who: "klaus", expr: "cold", text: "教皇の命令だ、教皇は少女エルが此処に隠れている可能性が高いと仰った" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "教皇直々に命令される立場か、お前は何者だ？" },
  { name: "クラウス", who: "klaus", expr: "normal", text: "私は聖教会福音使徒｜聖一位《せいいちい》クラウス・シュルツヴェールだ" },
  { text: "俺と話す福音使徒達のリーダー格らしき人物、澄んだ青い髪の青年はそう名乗る。クラウス・シュルツヴェール。何処かで聞いた名前だ。気の所為だろうか。" },
  { name: "クラウス", who: "klaus", expr: "cold", text: "さぁ、少女エルを差し出して貰おうか" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "もし拒否すると言ったらどうする？" },
  { chara: { slot: "right", id: "klaus", expr: "cold" } },
  { name: "クラウス", who: "klaus", expr: "normal", text: "武力を行使する、私にはその権限がある" },
  { text: "クラウスはそう告げると同時に、腰に差した剣の柄に静かに手を掛ける。それと同時に、他の福音使徒も同じように武器に手を掛ける。相手の獲物は剣。それも全員だ。なら、どうするか。考えるまでもない事だ。俺は覚悟を決め、拳を握り締める。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……分かった、エルを引き渡す" },
  { name: "クラウス", who: "klaus", expr: "cold", text: "そうか、話が早くて助かる" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "連れて来るから少し待っててくれ" },
  { text: "俺はそう言い残すと、扉を閉め、エルの元へと戻る。エルは俺の言う通り物陰に身を隠し、蹲っていた。そんな彼女に向けて、俺は小声で言葉を紡ぐ。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "エル、入り口に四人福音使徒が居る、強行突破するぞ、いけるか？" },
  { name: "エル", text: "武器は上層で没収されたから私は戦えないけど……大丈夫？" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "お前は自分が捕まらない事を第一に考えて動けばいい、福音使徒の奴らは俺に任せろ" },
  { name: "エル", text: "分かった" },
  { text: "エルがしっかりと頷いたのを確認すると、俺は自分の武装を確認する。｜魔窟《まくつ》で使った拘束用の手錠が二つ。以上。戦闘は想定していなかった為、まともな武器は持って来ていない。まぁ、問題ないだろう。俺の本分は｜徒手格闘《としゅかくとう》だ。確かに武器があった方が有利ではあるが、無くても戦える。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "じゃあ扉を開けたら全力で逃げろ、俺も四人を同時に相手するのは厳しいからな、一人でも多く敵を引き付けてくれ" },
  { text: "エルが頷く。それに俺も頷き返すと、深呼吸をする。呼吸が深くなる。自律神経が働き、全身に酸素が巡る。戦闘の準備は整った。俺は扉を蹴り開けながら、外へと飛び出した。" },
  { name: "福音使徒", text: "なっ……！？何のつもりだ！" },
  { bgm: "battle" },
  { fx: "shake" },
  { chara: { slot: "center", id: "yamato", expr: "angry" } },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "あ？見て分からねぇのか？エルは渡さねぇって事だよ！" },
  { chara: { slot: "right", id: "klaus", expr: "angry" } },
  { name: "クラウス", who: "klaus", expr: "angry", text: "武力行使を許可する！反逆者を無力化せよ！" },
  { text: "三人の福音使徒が同時に剣を抜く。が、その隙を俺は見逃さない。最も近い福音使徒の懐へ潜り込み、腕を掴んで姿勢を崩させる。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "安心しな、｜無能《ディザビリティ》だ" },
  { text: "胸元を掴んで抱え上げ、近くの壁へ向けて投げ飛ばす。壁に叩き付けられる寸前、ばしんと弾かれる音が響く。ディザビリティによるクッションが発動した。相手は無傷だ。だが、これで包囲陣形は崩れた。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "今だ！行け！エル！" },
  { name: "エル", text: "っ……" },
  { text: "俺の掛け声を合図に、エルが扉から飛び出てくる。" },
  { name: "クラウス", who: "klaus", expr: "angry", text: "待て！クリスタ！" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "待つのはお前だクラウス！" },
  { text: "俺のキャパシティで留めておけるのは一人だけ。なら最も実力のあるであろうクラウスを留めておくのが今俺が取れる最善の策だ。" },
  { text: "エルが俺の背後を走り抜ける。その背を追って残りの二名の福音使徒とクラウスが走り出そうとするが、俺がそうはさせない。" },
  { name: "クラウス", who: "klaus", expr: "normal", text: "くっ……武器も無しに、私と戦うつもりかい？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "武器ならあるさ、この肉体がな！" },
  { name: "クラウス", who: "klaus", expr: "cold", text: "そうか、｜邪魔《じゃま》をするなら容赦はしない……よ！" },
  { text: "躊躇する様子など一切無く、瞬時にクラウスが踏み込み、その手に握られた長剣が振るわれる。｜袈裟懸け《けさがけ》に振るわれたその剣を、俺は本能的な危機感知能力で飛び退き、躱す。速い。流石は｜聖一位《せいいちい》、才能指数は5か6って所か。" },
  { name: "クラウス", who: "klaus", expr: "normal", text: "まさか私の剣を躱すとはね、私と同等、或いはそれ以上の格闘術の才能でもあるのかな" },
  { text: "お互いに称賛の言葉を贈ると同時に、一度の攻防から相手を分析する。この男は、確かに強い。だが皇帝や勇者に比べれば、見劣りするのも事実だ。これなら十分に勝機はある。\"あれ\"を仕掛けるなら不意を突ける瞬間。相手が勝利を確信した瞬間にこそ、逆転の芽はある。" },
  { name: "クラウス", who: "klaus", expr: "cold", text: "実力が互角なら、獲物が長い私の方が有利だ" },
  { text: "確実に勝つ為には、劣勢を演じなければならない。だが、少しでも力加減を誤れば俺は敗北する。リスクの高い戦法だ。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "くっ……攻撃する隙が無い……！" },
  { name: "クラウス", who: "klaus", expr: "normal", text: "さっきの威勢はどうしたんだい？防戦一方じゃないか" },
  { text: "次々と繰り出される｜剣戟《けんげき》を、ギリギリの所で回避していく。言葉にするのは簡単だが、実行するのはとても難しい。事実、俺も完璧ではない。敵の攻撃が時々身体を掠め、浅い傷が生まれていく。" },
  { text: "相手の剣に迷いはない。この男も大義名分があれば、容赦なく人を殺せる類の人間なのだろう。集中力を切らせば、待っているのは死だ。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "はぁ……はぁ……まずいな……追い詰められた" },
  { text: "俺は、攻撃を避ける為に少しずつ後退していた。そして、遂に背中が壁に着く。次の攻撃は避けられない、｜絶体絶命《ぜったいぜつめい》の状態だ。" },
  { chara: { slot: "right", id: "klaus", expr: "cold" } },
  { name: "クラウス", who: "klaus", expr: "cold", text: "此処までだ、ヤマト君、聖教会に｜楯突《たてつ》いた事を、地獄で後悔するが良い" },
  { text: "クラウスは剣を頭上に構えた姿勢で俺の眼前へと迫り、必殺の、全身全霊の一撃が振り下ろされる。――機は熟した。" },
  { chara: { slot: "center", id: "yamato", expr: "smirk" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "……後悔するのはお前の方だ" },
  { text: "俺は剣を素手で受け止めようとする。普通に考えれば無茶で無謀な行為だ。そんな事をしても、手を破壊され、そのまま刃は身体まで達するだろう。" },
  { text: "――だが、俺は普通ではない。" },
  { se: "flash" },
  { fx: "flash" },
  { name: "クラウス", who: "klaus", expr: "shock", text: "なっ……！？" },
  { text: "俺の手は、剣を受け止めた。否、正確に言えば、俺の手は剣に触れていない。剣の勢いは逆流し、ベクトルは反転する。そう、これこそが『剣術0』ディザビリティの力だ。剣は勢いよく弾け飛び、彼方へと飛んでいく。" },
  { chara: { slot: "right", id: "klaus", expr: "shock" } },
  { name: "クラウス", who: "klaus", expr: "angry", text: "くっ……馬鹿な……一体何が起きて……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "現実だ、受け入れろ" },
  { text: "今ので腕を痛めたのだろう。クラウスは片方の手で利き手を抑えながら、俺から離れようとする。が、そんな事を許す筈がない。クラウスが事を起こすより先に、俺はクラウスへと迫り、腕を握って背後へと回ると、そのまま手錠を嵌める。" },
  { text: "元の世界では警察ではない、寧ろ相反する組織の人間だった俺が、手錠の扱いに精通している理由は簡単だ。クロセルや勇者との特訓の成果である。" },
  { text: "俺は特訓により、相手を傷付ける事無く無力化する術を身に着けたのだ。武装を解除し、両手を拘束すれば、もう怖い事は無い。" },
  { text: "クラウスの背中を押して\"優しく\"地面に倒すと、そのまま\"優しく\"蹴り転がす。" },
  { name: "クラウス", who: "klaus", expr: "normal", text: "この程度の拘束で私を縛れるとでも……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "この世界の手枷に比べれば簡易的な物だが、『魔術9』の才能で作られた物だからな、そう簡単には壊せないぞ" },
  { name: "クラウス", who: "klaus", expr: "cold", text: "君は自分のした事が分かっているのか！？これは聖教会に対する反逆行為だぞ！？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、そうだな、これで俺も再び晴れて犯罪者って訳だ" },
  { name: "クラウス", who: "klaus", expr: "normal", text: "そうだ、君は犯罪者だ、そこまでして何故クリスタを……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "悪いが、今はお前と話している時間すら惜しいんだ、じゃあな" },
  { text: "吠えるクラウスをその場に放り置き、俺はエルの逃げた方向へと走り出す。福音使徒二名、エルも多少の戦闘能力はあると言えど、数の不利を覆せるほどに強いとも思えない。早急に合流せねば。" },
  { text: "ひたすらに地面を蹴って、俺は聖都を駆ける。あの地下施設が見つかったという事は、既に下層にも捜査網は張り巡らされてると考えて良いだろう。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "……見つけた！どうやら間に合ったようだな" },
  { text: "ひたすらに走っていると、二人の福音使徒とそれから逃げるエルの姿が目に入る。速度を上げる。単純な身体能力であれば、俺は福音使徒にもエルにも劣らない。軽々と福音使徒を追い抜き、瞬く間にエルの元へ追い付いた。" },
  { hide: "all" },
  { chara: [
    { slot: "center", id: "yamato", expr: "smirk" },
    { slot: "right",  id: "el",     expr: "surprised" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "エル、こいつらを無力化する、手錠は一人分しかない、もう片方はお前が殴ってくれ" },
  { name: "エル", who: "el", expr: "surprised", text: "えっ……殴るって、えっ？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "いくぞ！" },
  { se: "flash" },
  { fx: "flash" },
  { text: "困惑した様子のエルだが、一々説明している時間はない。俺は直ぐに行動に移った。振り返ると同時に跳び上がり、天を仰いだ片方の福音使徒の顔面を蹴る。" },
  { text: "蹴る際の威力を調整、反動を制御、俺の足と福音使徒の顔面の間で見えない力が均衡し、そのまま空中で静止する。視界が塞がれた福音使徒は、俺の脚を掴もうと手を伸ばす。" },
  { text: "伸ばしてきた両手に手錠を嵌め、剣を握って弾き飛ばす。福音使徒の視界は塞がれていた為、手錠を持って、俺の足に手を伸ばすのを待っていた姿は見えていなかったのだ。" },
  { text: "こうして酷くあっさりと一人の福音使徒の無力化に成功する。俺は福音使徒の顔面から飛び降りると、足払いで雑に地面に転がす。ディザビリティがある為、当然無傷だ。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "さて、次だけど……" },
  { text: "そう呟きながら俺は身を屈める。同時に、頭上を剣が掠めていった。全く殺気を隠せていない。あんな攻撃、見えていなくても避けられる。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "クラウスに比べればやっぱ雑魚だな……っと" },
  { text: "俺は振り返り、背後に居た福音使徒と相対する。仲間が一瞬でやられ、リーダーであるクラウスもやられた。残ったのが自分一人というプレッシャーからか、動揺しているようだ。" },
  { text: "そして、勢い任せに振り下ろしてきた剣を、俺は受け止め、弾き飛ばす。福音使徒の基本武装が剣である以上、俺に負ける要素は無い。魔術師相手だと分が悪いが、今回は運が良かった。" },
  { name: "福音使徒", text: "うっ……うわあああああ！" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "うるせぇな……いきなり叫ぶなよ……" },
  { text: "武器を失い、更に動揺した福音使徒は、感情的になり、殴りかかってくる。放たれた拳を片手で受け止めると、そのまま拳を掴み、頭上高くまで持ち上げたかと思えば、そのまま大きく振り下ろす。" },
  { text: "その勢いで、福音使徒は敢え無く地面に倒れ込んだ。俺は速やかに福音使徒の上に乗ると、手足を動かせないように固定する。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "エル、出番だ、意識が無くなるまで殴れ" },
  { name: "エル", who: "el", expr: "surprised", text: "えっ……私がやるの？" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "俺はディザビリティがあるからな、頼む" },
  { name: "エル", who: "el", expr: "sad", text: "分かった……" },
  { text: "こうしてエルは、倒れた福音使徒を意識が無くなるまで殴り続けた。余談だが、無防備な人間の意識を奪うなら一撃で十分だ。意識を奪うに足らない威力で、延々と殴られ続けるのは一種の拷問である。まぁ、つまるところ、この福音使徒には悪いことをした。心の内で謝っておく、ごめんな。" },
  { hide: "all" },
  { bgm: "heartwarm" },
  { text: "エルと合流し、日没の聖都を駆ける。人目を避けて身を隠しながら移動するというのは、想像以上に時間を消費する行為だ。" },
  { name: "エル", who: "el", expr: "normal", text: "ヤマト様、何処に向かってるの？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "大丈夫、後少しだ" },
  { text: "此処に来るまでに何回か福音使徒の姿を見掛けた。教皇にエルが下層に居る事がバレたのは間違いない。となると……集合場所も絶対安全とは言えないだろう。早急に話を付けねばならない。" },
  { text: "この問題の着地点としては、聖教会との全面戦争、聖都を離れる、エルの容疑の正当性を立証する、この三種類になるだろう。" },
  { text: "出来れば3つ目の着地点を目指したい所だが、そんな上手い話は中々無いだろう。となると……残された選択肢は、戦うか、逃げるか。" },
  { text: "どちらを選ぶにしろ、俺達の平穏無事な暮らしは失われる事になる。" },
  { text: "……或いは、エルを見捨てるという選択肢。無いな、それだけはあり得ない。例え俺以外の誰もがエルを見捨てても、俺だけはエルを見捨てない。もう俺は、二度と大切な仲間を失う訳にはいかないんだ。" },
  { chara: [
    { slot: "center", id: "yamato", expr: "smile" },
    { slot: "right",  id: "el",     expr: "sad" },
  ] },
  { name: "エル", who: "el", expr: "normal", text: "ヤマト様……？" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "大丈夫だ、お前の事は俺が絶対に守る" },
  { text: "無意識に、エルを抱き寄せ、その頭を抱き締める。二度と離さないとばかりに、強く、強く。" },

  // ---------------------------------------------------
  // Scene 5: v_truth — Vの真実 (EP93)
  // ---------------------------------------------------
  { label: "v_truth" },
  { hide: "all" },
  { bg: "arcadia_lower" },
  { comment: "EP93: 集合場所の宿での全員会議" },
  { bgm: "tension" },
  { text: "間も無くして俺達は集合場所である宿に辿り着く。" },
  { chara: [
    { slot: "left",   id: "crocell",  expr: "normal" },
    { slot: "center", id: "yamato",   expr: "normal" },
    { slot: "right",  id: "el",       expr: "sad" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "ただいま戻った、全員無事か？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "遅いぞ、ご主人、日没には戻ってこいと言っただろう" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "ヤマトさん、もしかしてその後ろの子って……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、エルを見付けてきた、これからについて皆と話し合いたい" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "見つからないと諦めかけていた所だ、流石はご主人だな" },
  { text: "アカツキに案内され、宴会場のような大部屋に入る。そこに、俺達を除く仲間達全員が集まっていた。" },
  { name: "ティア", text: "エルが見つかったのね！やるじゃないヤマト" },
  { name: "ニコラス", text: "くっ……エルちゃんの事は僕が見付けるつもりだったのに……" },
  { name: "V", text: "見付かったようで良かったです" },
  { name: "ファイ", text: "……" },
  { name: "瀬野", text: "おかえり、ヤマト、無事で何よりだよ" },
  { text: "ファイは相変わらず黙ったままだが、出て行けという目はしていないし大丈夫だろ。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "さて、無事にエルが戻ってきてお祝い……と行きたい所だが、事は急を要する、これから今後について話し合うぞ" },
  { text: "エルのマントを取ると、俺とエルも席に座る。まず口を開いたのはアカツキだ。" },
  { chara: [
    { slot: "left",   id: "akatsuki", expr: "serious" },
    { slot: "center", id: "yamato",   expr: "normal" },
    { slot: "right",  id: "el",       expr: "sad" },
  ] },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "まず現状についてですが、私の方で調べた結果、エルさんの容疑、神との接触行為は大罪に値するとされています" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "うむ、そしてその例外が勇者と教皇だな、このどちらかであれば、神と接触しても罪には問われない" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "確認になりますが、エルさんはそのどちらでもない、間違いないですね？" },
  { name: "エル", who: "el", expr: "sad", text: "……うん、私は勇者でもないし、教皇でもないよ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "分かりました、それで……\"大罪\"というのがどのような罪であり、どのような刑が執行されるかと言うと……ぶっちゃけ、死罪です、処刑が下されます" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "つまりエルは、このまま聖教会に捕まれば殺される事になると" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "そうなりますね" },
  { text: "エルの言っていた事は確かだった。教皇は……というより聖教会は、エルを殺すつもりである。その事実がこれで明確になった。" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "ただし、勇者や教皇でなくても、神との接触行為に正当性が認められれば例外的な措置として認められる可能性もあります、教皇、或いはその上位の権限、要するに教皇か神が認めれば、ですが" },
  { name: "V", text: "つまり……エルさんが神と接触した理由次第では、罪に問われない可能性があるって事ですね" },
  { text: "Vがそう呟く。彼の言う通り、エルが神に接触した理由が分かれば、その行為の正当性が認められる可能性もある。悪戯にあんな事をした訳ではないだろう。何か必ず、その行為に至った彼女なりの理由があった筈だ。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "エル、お前が何を目的として上層に侵入し、神と接触したのか、その理由を……聞かせてくれるか？" },
  { text: "エルは困ったような顔をしつつ、俺達の顔を順番に見渡す。そして、一つ小さな溜息を吐いて、ゆっくりと言葉を紡いだ。" },
  { name: "エル", who: "el", expr: "troubled", text: "ある物を……取り戻しに行った" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "ある物……？" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "本来エルさんの物であって、神が持っていた\"何か\"を、神の元に取り戻しに行った、そういう事ですか？" },
  { name: "エル", who: "el", expr: "sad", text: "うん、そうだよ" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "疑問は尽きないな、何でエルの持ち物を神が持っていたのか、ある物とは何なのか、神は何故それを渡したのか" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "クロセル、エルは嘘は言ってないんだよな？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "あぁ、我が常に分析しているが、嘘は言っていない、だが……どうも心までは読めないな、エルの思考は普通の人間の思考パターンとは異なっているようだ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "どういう事だ？思考パターン？" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "人が動物の考えを理解出来ないのと同じだ" },
  { name: "ニコラス", who: "nicholas", expr: "surprised", text: "エルちゃんが動物だなんて酷いじゃないか" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "今真面目な話してるんだ、勇者は黙っててくれ" },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "えっ……僕に発言権は無いの？" },
  { text: "勇者のせいで思考が掻き乱されたが、要するにクロセルの分析の才能ではエルの思考は読めない。それでも嘘を見破る事は出来るようだから、エルが能動的に喋ってくれるなら、思考など読めなくても問題ないだろう。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "その\"ある物\"ってのは一度神に奪われたのか？" },
  { name: "エル", who: "el", expr: "normal", text: "いや、正確には神の元に置き忘れた……って言うべきかな" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "なるほどな、一度神の元に置き忘れた忘れ物を、エルは取りに行った訳だ" },
  { text: "待てよ？という事はつまり、エルは今回の件以前にも一度以上、神と接触している？そもそも俺がエルと出会った時、エルは王国の宮廷に仕える使用人だった筈だ。教国の人間ではない。" },
  { text: "つまり、エルが俺と出会う前の話か。エルが王国で働き始める前に、教国で神と接触している。そういう事なのだろう。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "おいアカツキ、勇者と教皇以外に本当に例外はないのか？儀式とかで福音使徒、或いは一般人が神と接触する事もあるんじゃないのか" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "神と直接接触する儀式……ですか……そんなの神の継承ぐらいしか無いと思いますが……" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "だよなぁ……" },
  { text: "アカツキが知らない事を俺が知っている筈もなく。エルが一度目に神と接触した理由は依然として分からない。もしかしたら非公式の儀式とかが存在するのかもしれない。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "それでアカツキ、クロセル、この理由でエルの正当性を証明する事は出来そうか？" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "……正直、厳しいと思います" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "うむ、同感だな" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そうか……ならもし、これからエルを連れて聖教会に反逆すると言ったら、付いて来る者は居るか？" },
  { text: "こうして全員に集まって貰った理由は他でもない。この問いを投げ掛ける為だ。" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "我は勿論付いて行くぞ" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "私もお供します" },
  { name: "ティア", who: "tia", expr: "normal", text: "私はヤマトに付いて行くわ" },
  { name: "瀬野", who: "zeno", expr: "serious", text: "僕もヤマトに、うん、従うよ" },
  { text: "クロセル、アカツキ、ティア、瀬野。まぁ予想通りと言った所か。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "これは強制じゃない、無理に付いて来る必要はないし、付いて来なかったからと言って縁を切るつもりもない、命に関わる問題だ、正直に言ってくれ" },
  { chara: { slot: "right", id: "bolt", expr: "sad" } },
  { name: "V", who: "bolt", expr: "normal", text: "僕達は降りさせて貰います、ヤマトさん達には恩がありますが、ファイを危険に晒す事は出来ない、それに……僕が居ても足手まといになるだけだと思うので" },
  { text: "Vはそう言って俺に頭を下げる。まぁ妥当だろう。彼の選択は間違っていない。寧ろ彼の判断こそが最適解とも言えるかもしれない。" },
  { chara: { slot: "right", id: "nicholas", expr: "serious" } },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "僕は協力するよ、祝福の無い僕が役に立てるかは分からないけど……" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "勇者……本気か？お前……戦うのが怖いって……" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "確かに死ぬのは怖い、戦うのも怖いよ、でも……僕にとってもエルちゃんはもう仲間だ、見捨てる訳にはいかない" },
  { text: "勇者ニコラス。性格には難があるが、戦力としてこれほど心強い者も中々居ない。彼は典型的な正義の味方。犯罪者であるエルを庇うという事は、悪に加担する事に等しい。故に、彼までも協力してくれるというのは、些か想定外だった。" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "それに……前みたいに一人だけ仲間外れってのも嫌だからね" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "ロイトンでの事か……あれはまぁ……悪いと思ってる" },
  { text: "どうやらロイトンで一人置いていった事を根に持っているらしい。まぁ……あの時に比べれば勇者の印象もだいぶ変わった気がする。あの頃は単に正義厨の頭がおかしい奴だと思っていたが、今思えばあれも祝福の勇者という肩書に翻弄されていただけなのだろう。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "よし、じゃあ決まりだな、Vは今まで通りあの家を使って構わない" },
  { name: "V", who: "bolt", expr: "smile", text: "良いんですか？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "いや、言い方を変えよう、あの家の管理をお前にお願いしたい、要するに留守を任せる" },
  { name: "V", who: "bolt", expr: "normal", text: "あっはい、分かりました" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "公衆浴場の運営はクロセルとティアが居ないと出来ないから、俺達が帰るまでの生活費は自力でなんとかしてくれ" },
  { name: "V", who: "bolt", expr: "sad", text: "という事は、聖都から離れるのかい？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そうなるな、俺達の立場は教国でも王国と同じで指名手配のような物になると考えて良いだろう、皆は何処に逃げるべきだと考える？" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "有力な候補は帝国でしょうか、迷宮都市が多いので冒険者として暮らしていけると思います" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "それはダメだな、間も無く帝国は王国の統治下になる、文化の違いなどの大きな障壁も無い以上、クロム帝国は王国に吸収されると見て良いだろう" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "それは確かなのか？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "我の分析が確かならば、そうなるだろう" },
  { text: "帝国は歴史の浅い国だ。無政府状態となった今、より歴史もあり大国である王国に吸収合併されるというのも納得は出来る。王国、帝国、教国がダメだとすると……残るは公国と魔王領になる。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "魔王領はとても住めるような場所じゃない、公国は既に滅びた、チッ……逃げる場所など……もう何処にも……" },
  { text: "俺はそう呟いて、悔しげに歯を噛み締める。教国で聖教会と、或いは王国や帝国で王権と、徹底抗戦するという手もあるが……俺達にそんな戦力は無い。" },
  { text: "例えクロセルや勇者達が一騎当千の力を持っていると言っても、圧倒的な差である数の暴力には勝てない。それに……仲間には手を汚させたくはないという気持ちもある。" },
  { text: "俺は元｜咎人《とがびと》、クロセルは元魔王。今更そんな事を気にするのもおかしな話ではあるが。" },
  { chara: { slot: "right", id: "bolt", expr: "normal" } },
  { name: "V", who: "bolt", expr: "normal", text: "……公国は滅びていません" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あ？今の声は誰だ？" },
  { name: "V", who: "bolt", expr: "normal", text: "僕です、Vです" },
  { text: "Vが手を挙げる。Vが、公国は滅びていないと言ったのだ。聡明な彼の事だ、何か思う所があっての発言だろう、俺は黙って続きを話すように促す。" },
  { name: "V", who: "bolt", expr: "smile", text: "確かに……先日、公国の首都、公都は魔王の手によって陥落しました" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "あぁ、魔王による破壊行為、その粛清の犠牲になった、あまりにも有名な話だ" },
  { name: "V", who: "bolt", expr: "sad", text: "ですが、魔王軍の侵攻は公都を目指して直線状に行われました、つまり、魔王軍の侵攻ルート上に無かった一部の町村は生きていると推測できます" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "つまり、結論として何が言いたい" },
  { name: "V", who: "bolt", expr: "normal", text: "逃げるなら公国を目指すべきだと思います、もっと言ってしまえば、僕は被害を受けていない領土を治めるある貴族の存在を知っています、その貴族に協力を仰ぎ、匿ってもらうのはどうでしょう" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "……アカツキ、クロセル、どう思う" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "公国が粛清されたのは魔王が他国に自身の力を示すためだ、その為には首都を破壊し国としての機能を失わせれば十分、関係のない町村までを破壊し尽くす必要はない" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "公国は複数の貴族達によって統治されている国です、公都と｜公主《こうしゅ》を失った今でも、被害が皆無、或いは軽微な領土は機能している可能性が高いですね" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "そうか、二人がそう言うならそうなんだろう、問題はその貴族が俺達の事を受け入れてくれるかだが……" },
  { name: "V", who: "bolt", expr: "smile", text: "それなら安心して下さい、僕が紹介状を書きます" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "は？なんでお前が紹介状なんて書けるんだよ" },
  { text: "Vが貴族に紹介状を書けるような立場の人間であるようには思えない。いや、そうでもないかもしれない。" },
  { text: "Vは上流階級の人間が着るような衣服を纏い、一般人とは思えない過度な常識と教養を持ち合わせている。あとは、雰囲気だろうか。" },
  { text: "どことなくカリスマを感じる。まさかとは思うが……本当にVは貴族なのか？" },
  { name: "V", who: "bolt", expr: "sad", text: "……それは、僕が公国出身の貴族だからです" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "Vさん、言ってしまって良いんですか？" },
  { name: "V", who: "bolt", expr: "normal", text: "構いません、もう隠す理由は無いですから" },
  { text: "Vはアカツキと短く言葉を交わす。どうやらアカツキは前からこの事を知っていたらしい。隠し事をされていた事に、少し不満を覚えるが、アカツキの事だから、Vの事を考えて黙っていたのだろう。俺が咎めるような事ではない。" },
  { name: "V", who: "bolt", expr: "normal", text: "公国の一流貴族、ドラゴファースト家の次男、それが僕、ボルト・ドラゴファーストです" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "ドラゴファースト……？何処かで聞き覚えがあるな？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ご主人、知らないのか？あのアステカス公国を治めていた｜公主《こうしゅ》こそアイシィ・ドラゴファーストだぞ" },
  { chara: { slot: "center", id: "yamato", expr: "surprised" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "つまり……お前は｜公主《こうしゅ》の弟！？" },
  { name: "V", who: "bolt", expr: "smile", text: "そうなりますね" },
  { text: "V……いやボルトが、貴族であったという事は納得できる。だが、まさか｜公主《こうしゅ》の弟だったとは思わなかった。衝撃の事実だ。しかし、これで俺がボルトに抱いていた疑問は大方解消された。" },
  { text: "彼は公都が陥落する際に、教国に逃げてきたのだろう。その途中でファイが攫われ、救出する為に聖都を訪れた。｜辻褄《つじつま》は合う。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "ボルトが｜公主《こうしゅ》の弟なら、諸侯の貴族に紹介状を書けるような立場ってのも納得できるな" },
  { name: "V", who: "bolt", expr: "sad", text: "ではアカツキさん、紙と筆記具をお借りできますか？" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "分かりました、宜しくお願いします" },
  { text: "アカツキが紙とペンを取り出し、ボルトに渡す。流石は元国王秘書、あの手の道具は常に持ち歩いているらしい。ボルトはそれを受け取ると、直ぐに机に向かい、ペンを走らせていく。潜伏先の問題は、彼に任せれば問題ないだろう。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "じゃあ公国に逃げるという事で決まりだな、反対意見のある奴は居ないか？" },
  { text: "誰も手を挙げない。それを確認すると、俺は大きく頷き、続きの言葉を紡ごうとする。だが、その瞬間、俺は隣に座っていたクロセルに口元を抑えられ、発話を制止される。" },
  { chara: [
    { slot: "center", id: "yamato",  expr: "surprised" },
    { slot: "right",  id: "crocell", expr: "angry" },
  ] },
  { name: "クロセル", who: "crocell", expr: "angry", text: "待て、ご主人……まずいぞ" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "……まさか、この場所が？" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "うむ、宿は完全に囲まれているな……すまない、もっと早く気付くべきだった" },
  { text: "どうやらこの場所が聖教会に見付かったらしい。クラウス達と交戦した時点で、エルが下層に居る事はバレていた。となると見付かるのは時間の問題だと思っていたが、あまりにも早すぎる。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "チッ……ボルト、紹介状は書けたか？" },
  { name: "V", who: "bolt", expr: "normal", text: "出来ました、これを持って公国の都市、アリエルツフィルを目指して下さい、そこを治める貴族、セン公にこれを渡せば話は通るはずです" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "助かる、取り敢えず皆で此処を離れるぞ、クロセル、転移魔術で……" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "駄目だな、結界が張られている、空間魔術では逃げられない" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "なんだと……結界は破壊出来るか？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "許容量を超えるダメージを与えれば穴は開けられる" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "穴が空けば空間魔術で飛べるか？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "そうだな、少しでも結界に穴を開けられれば可能だ" },
  { text: "クロセルが俺の問いにしっかりと頷く。一先ずこれで突破口は見えた。まだ俺達は詰んでいない。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "よし、クロセル、俺の思考を読んで皆に指示を出してくれ" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "……作戦を一言で言えば強行突破、此処を包囲している福音使徒と交戦しつつ結界を破壊、転移魔術で一度拠点に戻り、馬車で聖都を出る、結界の破壊は宿屋の内部から魔術で行う、故に我とティアが担当、エルとボルトとファイを除く他の皆は時間稼ぎの担当だ" },
  { name: "エル", who: "el", expr: "sad", text: "遂に聖教会と戦うんだね……" },
  { text: "クロセルの指示に対して、エルがそう呟く。その顔色には憂いの色が見えた。不安な気持ちは分かる。飽くまでも数を力と換算した上での話ではあるが、戦力差は圧倒的。国を支配する大規模組織と敵対するというのは、中々に勇気の要ることだ。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "まぁ……俺としては既に王国と敵対してるからな、そこまで新鮮って訳でもない、だから安心しろ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "そうですね、それじゃあ増援が来る前に片付けてしまいましょう" },
  { text: "アカツキのその言葉を期にして、俺達はほぼ同時に動き出す。クロセルとティアは窓の外を見ながら詠唱を開始。一方、俺と勇者は宿の出口へと向かう。" },
  { text: "そして、その後ろを付いて行くようにしてアカツキと瀬野。これから聖教会と敵対する。その事実に、否応にも緊張感が走る。だが、覚悟は揺らがない。それは皆も同じなようだ。そして、俺は宿屋の出入り口、その扉を開けた。" },
  { fx: "shake" },

  // ---------------------------------------------------
  // Scene 6: crista_showdown — クリスタ (EP94)
  // ---------------------------------------------------
  { label: "crista_showdown" },
  { hide: "all" },
  { bg: "arcadia_lower" },
  { text: "扉を開いて、その先に広がっていた光景を目撃する。そこには、数十名の福音使徒と教皇イヴ・エンドの姿があった。正確に言えば他にも、宿屋の主人、そしてクラウスの姿も見える。今は教皇が宿屋の主人に状況を説明している所のようだ。" },
  { name: "宿屋の主人", text: "これは一体何の騒ぎですか？" },
  { chara: [
    { slot: "left",   id: "klaus",   expr: "normal" },
    { slot: "center", id: "eve_end", expr: "normal" },
    { slot: "right",  id: "yamato",  expr: "angry" },
  ] },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "突然押しかけて申し訳ありません、実はこの宿にある人物が潜伏している疑いがありましてね、中を捜索させて頂きたいのですが……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "その必要はないぞ、教皇" },
  { text: "俺は教皇に向かってそう言い放つ。すると、教皇は此方へと視線を移し、やれやれとばかりに目を閉じて、小さく頷く。隣には勇者が立ち、その腰に携えた刀に手を掛けた姿勢で扉を守るように立つ。" },
  { name: "クラウス", who: "klaus", expr: "cold", text: "エンド様、彼です、彼が私を拘束し、逃亡を手助けしたヤマトという男です" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "えぇ、分かっています" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "教皇、愚問かもしれないが一応問おう、お前は何の為に此処に来た？" },
  { text: "俺はちらりと一瞬、宿屋を囲むように貼られた半透明の膜、結界に目を向ける。シャボン玉のようなそれは脆そうに見えるが、物理的な通行に加え、空間魔術での通行すらも阻止する効果を持つ。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "cold", text: "言わずもがな、貴方が匿っている少女を捕らえるためですよ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "エルの事か？" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "えぇまぁ、そうですね、少女エルの事です" },
  { text: "何とも当たり障りの無い会話だ。こんな無意味な問答にすら耳を傾ける。教皇が律儀な男で助かった。あわよくば、対話だけで時間を稼げれば万々歳だ。" },
  { text: "クロセルとティアは今、宿の内部から結界の破壊に注力している。俺達の仕事は時間稼ぎだ。故に、まずは交戦するのではなく問答から入る。" },
  { name: "クラウス", who: "klaus", expr: "normal", text: "クリス……少女エルを出せ、そうすればお前達は罪に問わないとエンド様は仰っている" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あ？お前……クラウスだったか？前に会った時からふと思ってたんだが、クリスタって誰だ" },
  { text: "数時間前まで、記憶の糸を辿る。確か、クラウスと戦った時、逃げるエルに対してそう叫んでいた気がする。という事は、クリスタというのはエルを指す言葉なのか？" },
  { name: "クラウス", who: "klaus", expr: "cold", text: "エンド様……" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "構いませんよ、どうやらこの様子だと、彼らも知らないようですし" },
  { text: "教皇は探るような視線を俺達に送る。そして、また一人納得したように頷くと、クラウスに続きを話すように促す。" },
  { chara: { slot: "left", id: "klaus", expr: "cold" } },
  { name: "クラウス", who: "klaus", expr: "normal", text: "分かりました、クリスタは……私の妹だ" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "だから何だよ……" },
  { name: "クラウス", who: "klaus", expr: "cold", text: "少女エルの本名はクリスタ・シュルツヴェール、エルは偽名だ" },
  { fx: "shake" },
  { chara: { slot: "right", id: "yamato", expr: "surprised" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "どういう事だ？つまり……エルはお前の妹だと言いたいのか？" },
  { name: "クラウス", who: "klaus", expr: "cold", text: "そうだ" },
  { text: "エルが偽名。そしてクラウスの妹である。驚きの事実に、俺は言葉を失う。だが、此処で黙っていては時間は稼げない。俺は苦し紛れに言葉を絞り出す。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "……人違いじゃないのか？よく似た別人の可能性もあるだろ" },
  { name: "クラウス", who: "klaus", expr: "normal", text: "この世界で、容姿のよく似た人間が居たとして、そこから個人を特定する方法がある、何か分かるかい？" },
  { text: "DNA……なんて概念はこの世界にはまだ無いだろう。容姿がダメなら……性格、いや……それも偽ろうと思えば偽ることが出来る。個人を特定する物とは、偽ることの出来ない物だ。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……才能、か？" },
  { name: "クラウス", who: "klaus", expr: "normal", text: "そうだよ、この世界には無数の才能がある、才能指数も含めて、全く同じ才能を持っている人間は1兆人に1人とも言われている、だから才能で個人を特定する事が出来るんだ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "お前の妹であるクリスタって奴と、エルの才能が一致した……そう言いたい訳か？" },
  { name: "クラウス", who: "klaus", expr: "cold", text: "そうなるね" },
  { text: "俺は頭を抱える。この男が嘘をつく理由はない。それはつまり事実という事だ。エルは俺達を騙していたのか？いや、そうじゃない。例え名前が偽名だとしても、その素性を偽っていたとしても、俺達の仲間である事には変わりはない。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "仮にお前の言ってる事が事実だとして……クラウス、お前は妹の命より組織を優先するのか？" },
  { text: "俺はそう問い掛ける。心做しか、声が震えている気がする。これは怒りの感情か？困惑の感情か？分からない。だがそんな事はどうでもいい事だ。そんな俺の問いに対し、クラウスが口を開くより先に、教皇が答える。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "ヤマト君、君はどうやら何か勘違いをしているようだね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "どういう事だ？" },
  { name: "イヴ・エンド", who: "eve_end", expr: "cold", text: "私達は少女エルを\"保護\"したいと考えている" },
  { text: "教皇が紡いだ言葉は、俄には信じられない物であった。罪人として捕縛するのではなく、保護する？一体どういう事なのだろう。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "cold", text: "繰り返す、少女エルを聖教会に引き渡してくれ、私達は彼女を処刑するつもりはない、悪いようにはしないよ" },
  { chara: { slot: "right", id: "yamato", expr: "angry" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そんな事……信じられる訳ないだろ！" },
  { text: "俺は目を見開き、怒鳴りつける。教皇の奴……有ろう事かエルを捕らえるために嘘をついている。俺が言える事では無いが、まさか奴がそんな人間だとは思わなかった。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "勘違いしないで欲しい、私達は少女エルさえ無事ならそれで良いんだ、つまり……それを｜邪魔《じゃま》する君達に対しては、武力行使の措置を取っても良いんだよ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "何故お前が罪人であるエルを保護する！？お前が言ってる事は滅茶苦茶だ！ちゃんと理由を説明しろ！" },
  { chara: { slot: "center", id: "eve_end", expr: "cold" } },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "それは出来ない、これは極秘事項だからね" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "あぁそうか、なら良いぜ……やってみろよ、力ずくで俺達からエルを奪ってみろ！" },
  { text: "どうやらこれ以上の問答は無駄らしい。嘘をついて相手を騙し、目的を達成する。正義の聖教会のやる事とは思えない、何とも｜卑怯《ひきょう》な手だ。つまり、聖教会は悪だ、大義名分も出来た。もう躊躇う理由はない。" },
  { bgm: "battle" },
  { fx: "red" },
  { name: "イヴ・エンド", who: "eve_end", expr: "cold", text: "仕方ないですね……武力行使を認めます、何としてでも少女エルを確保しなさい" },
  { chara: { slot: "lcenter", id: "nicholas", expr: "serious" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "勇者、やるぞ" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "エルちゃんの為だ……任せてくれ！" },
  { text: "教皇の命令と同時に、福音使徒達が武器を抜いて此方に迫ってくる。結界の方を見るが、まだ破れてはいない。もう暫く時間を稼がねばならない。" },
  { name: "クラウス", who: "klaus", expr: "normal", text: "エンド様が魔術を使えば二人ぐらい簡単に倒せるのでは？" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "先程から私の結界に攻撃を受けていましてね、維持をするので精一杯なのですよ、ですので任せましたよ" },
  { text: "クラウスの問いに、教皇がそう答える。やはり結界は教皇の物か、だとすれば一筋縄ではいかなそうだ。" },
  { name: "ニコラス", who: "nicholas", expr: "surprised", text: "聖剣！抜刀！鎌矛尾羽針ビーム！！！" },
  { se: "flash" },
  { fx: "flash" },
  { text: "勇者の聖剣が迫り来る福音使徒を一撃で斬り伏せていく。一瞬で屍……正確に言えば死体ではないが、人の山ができ、それがバリケードとなって、敵の攻め入る足場が失われる。これで近接武器を持った福音使徒は無力化したも同然だ。" },
  { chara: { slot: "center", id: "eve_end", expr: "serious" } },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "流石は人斬り｜抜刀斎《ばっとうさい》と自称するだけはあるな" },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "僕の超絶格好良い大活躍を見てくれるのがヤマト君だけなのが残念だよ" },
  { name: "アカツキ", text: "私が見てますよ" },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "アカツキちゃん！？居たのか" },
  { name: "瀬野", text: "あはは……僕もアカツキさんも最初から居たんだけどね" },
  { text: "後衛である二人も、ずっと後ろで話を聞いていたはずだ。特にアカツキは、エルの真実に対して、どんな感情を抱いているのだろうか。" },
  { name: "瀬野", text: "それにしてもヤマトはやっぱり力を隠すんだね、本当はニコラスさんより強いのに" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "うるせぇなぁ……つか瀬野ってそのこと知ってたか？" },
  { name: "瀬野", text: "知ってる……というか僕以外には秘密って話だったんじゃ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "あ？そんな話したか？" },
  { name: "アカツキ", text: "ヤマトさん！後ろ！" },
  { se: "flash" },
  { fx: "red" },
  { text: "アカツキの警告。咄嗟に回避機動を取ろうとするが、間に合わない。背に腹は代えられない、片腕でガードする。火属性の魔術が左腕を焼く。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "うぐっ……あっつっ！？くっ……油断した" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "ヤマト君も中へ！僕が盾になる！" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "勇者……お前もう祝福無いんだぞ？" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "それでも魔術による攻撃は僕には効かないから" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そう言えばその悪趣味な金色の鎧、そんな効果もあったな……" },
  { fx: "clear-red" },
  { text: "勇者の鎧やラオンの黒衣には、魔術による攻撃を無効化する効果がある。一種のチートアイテムな気がするが、気にしたら負けだろう。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "ダメだな……勇者の大活躍に対して俺、何の役にも立ってねぇ……" },
  { name: "アカツキ", text: "いつもの事ですから気にしないで下さい" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "えっ、いや……肯定されると結構ショックなんだが……" },
  { text: "知ってた。俺が今までやってこれたのは俺が強いからじゃない。俺の仲間が強いからだ。分かりきっていた事実だが、こうして改めて突き付けられると中々にくるものがある。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "君達のしている事は無駄だ！本来、私達と君達は分かり合える筈なんだ！無為に血を流す必要はない！" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "今更何言ってんだあいつ……" },
  { text: "教皇が叫ぶ。その声色には、明らかに焦りの色が見えた。つまり……教皇も消耗しているという事。結界の破壊は間近だと思って良いだろう。" },
  { chara: { slot: "right", id: "yamato", expr: "angry" } },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "お前が俺達を信じないのと同じで、俺達もお前達の事は信じねぇよ！分かり合おうとしていないのはお前達の方だ！" },
  { text: "俺がそう叫び返す。そうだ、聖教会は俺達に多くの事を隠している。そんな奴らを信じられる訳がない。" },
  { text: "もし、教皇がこれほどまでに愚かでなければ、また違った結末があったのかもしれない。だが、そんな想像を、俺は頭を振って掻き消す。現実にIFなどないのだ。確定した結果は揺るがぬ結果であり未来だ。結果から目を背けて、もしもを考える事自体、ナンセンスだと言える。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "っ……君達は後悔することになるだろう" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "知ったことか" },
  { fx: "clear-red" },
  { text: "パリン、とガラスの割れるような音が辺り一面に響いた。結界に穴が空いたのだ。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "よし、結界に穴が空いたな、勇者！退くぞ！" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "分かった！" },
  { text: "結局、勇者一人で時間を稼いでしまった。本当にこいつには驚かされる。そんな風に思いながら、俺達はクロセルの元に戻る。" },
  { hide: "all" },
  { chara: { slot: "center", id: "crocell", expr: "laugh" } },
  { name: "ヤマト", text: "結界は破壊できたか？" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "うむ、今なら空間魔術で飛べるぞ" },
  { name: "ヤマト", text: "よし、よくやった、流石はクロセルだ" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ご主人も良く時間を稼いでくれた、流石はご主人だな" },
  { name: "ヤマト", text: "あぁ……まぁ……そうだな……" },
  { text: "これほど期待に満ちた目で見つめられると、今更訂正する気にもなれなかった。そういう事にしておこう。悪いな、勇者。" },
  { name: "ヤマト", text: "じゃあ全員集まれ、飛ぶぞ" },
  { text: "クロセルの元に、全員が集まる。宿の入り口から福音使徒達が雪崩込んでくるが、もう遅い。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "後悔するのはお前の方だよ、イヴ・エンド" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "｜魔術回路改竄《カスタマイズ》……｜略式詠唱展開《ファストキャスト》……空間魔術……｜空間接続《ゲート》！" },
  { se: "magic" },
  { fx: "flash" },
  { text: "クロセルの詠唱と共に、俺達は光に包まれ、その場から消え失せた。" },

  // ---------------------------------------------------
  // Scene 7: border_breakout — 国境を抜けて (EP95)
  // ---------------------------------------------------
  { label: "border_breakout" },
  { hide: "all" },
  { bg: "country_road" },
  { comment: "EP95: 馬車での逃避行" },
  { bgm: "comedy" },
  { name: "ヤマト", text: "うぐぐ……狭いな……" },
  { name: "アカツキ", text: "私を除いても六人ですから、少し狭いのは我慢して下さい" },
  { name: "ヤマト", text: "よし、やっぱ勇者降りろ" },
  { name: "ニコラス", text: "なんで！？" },
  { name: "ヤマト", text: "悪いな、この馬車は五人乗りなんだ" },
  { name: "ニコラス", text: "それなら僕を降ろすんじゃなくてクロセルちゃんを杖の姿にすれば良いじゃないか……" },
  { name: "ヤマト", text: "あ？俺のクロセルに杖になれだと？殺すぞ？" },
  { name: "ニコラス", text: "冗談だって！ヤマト君なんで僕に対してこんな殺意高いの！？" },
  { text: "俺達は一度拠点に戻り、速やかに旅支度を整えると、そのまま馬車で聖都を後にした。聖教会による追跡、或いは待ち伏せを想定していたが、それも｜杞憂《きゆう》で終わった。魔剣グレモリーとラプラスも盗難防止の名目で同行している。" },
  { text: "そして、今は馬車の中。いつものように馬鹿騒ぎ出来る程度には、心に余裕は出来た。" },
  { name: "アカツキ", text: "ヤマトさんはニコラスさんばかり活躍しているから嫉妬してるんですよ" },
  { name: "ヤマト", text: "あ！？なんだとアカツキ！" },
  { name: "アカツキ", text: "否定できますか？" },
  { text: "図星であった。" },
  { chara: [
    { slot: "left",   id: "laplace",  expr: "laugh" },
    { slot: "center", id: "yamato",   expr: "surprised" },
    { slot: "right",  id: "akatsuki", expr: "jito" },
  ] },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "いやーボクも旅に同行させて貰えるとは、舞台の演出を頑張ったかいがありますな！" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "何でこいつ連れてきたんだ……" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "拠点に置いていって、悪い人間の手に渡ったりしたら大変なので……" },
  { text: "アカツキの計らいで魔剣グレモリーと魔剣ラプラスも持って来た。何かに使う目的ではなく、飽くまでも盗難を防ぐ為だ。" },
  { name: "グレモリー", text: "我は平穏を望む者……やたら騒がしい旅に同行するのは不本意だ" },
  { name: "ラプラス", who: "laplace", expr: "blank", text: "えー趣味が合いませんねぇ……先々代の魔王様とは" },
  { text: "愉快だとばかりに楽しそうなラプラスに対して、グレモリーは不満そうだ。まぁ、平穏を望んで自分を封印するような魔王だ。こうなる事は分かっていた。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "グレモリーには悪い事をしたな" },
  { name: "クロセル", text: "いや、そうでもないかもしれんぞ" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "なんでだ？" },
  { name: "クロセル", text: "我が思うに、魔剣グレモリーは人と話すのが好きな性格をしている。もっと言ってしまえば……人間の事が好きな性格だ、平穏を望むのは人を傷付けたくないからであって、彼女は本質的に平穏を望んでいる訳ではない" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "なるほどな、ならこうやって人と話す機会を与えてやるのも悪くはないか" },
  { text: "本気で不干渉を貫き、平穏を望むのなら、話し掛けられても無視すれば良い話だ。声を掛けられたら嫌そうな口ぶりをしつつも律儀に答える辺り、そういう事なのだろう。" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "聖都を出ました、一先ず第一関門は突破ですね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "検問を張られては居なかったか、初動が早かったのが功を奏したな" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "問題は国境越えですね、あの万里の長城は馬車じゃ超えられませんし……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "戦闘して制圧、強行突破になるか" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "そうなりますね、ただ……そこまで難しくはないかと" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "なんでだ？" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "国境警備はぶっちゃけザル警備です、聖都の中層、上層の防衛ラインの方がよっぽど強力な警備をしています" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "つまり俺達の戦力をもってすれば取るに足らないと言いたいわけか？" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "そうですね、此処に居る人であれば一人だけでも難なく突破できると思います、ヤマトさん以外は" },
  { chara: { slot: "center", id: "yamato", expr: "surprised" } },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "待て……アカツキ、もしかしなくてもこの中で俺が一番弱いと思ってるのか？" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "……嘘はつけませんね、そうです、私の分析ではヤマトさんが一番弱いと判断します" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "なん……だと……" },
  { text: "どうやら俺は自分を強いと思い込んでいたらしい。いや、実際弱くはないと思うのだ。傷害のディザビリティさえ無ければ……クロセルや勇者レベルとは行かずとも、エル程度の戦闘能力はあるんじゃないかと思う。" },
  { text: "それに、\"あれ\"を使えば俺はこの場の誰よりも強くなれる筈だ。一時的にだが。" },
  { name: "瀬野", text: "何を言ってるんですか、ヤマトは最強ですよ、能ある鷹は爪を隠すって言うじゃないですか" },
  { name: "クロセル", text: "うむ、ご主人は強いぞ" },
  { text: "瀬野とクロセルからフォローが飛んでくる。お世辞でも感謝しておこう。" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "そうですね、そういう事にしておきましょう" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "アカツキは毒舌だな……俺はショックを受けたぞ……" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "純粋な戦闘能力だけで人の価値は測れない。ヤマトさんにはヤマトさんなりの長所があるのは認めていますから、そう落ち込まないでください" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "皆に指示を出すって役割も……指揮のディザビリティのせいで出来なくなった、俺に出来る事は本当にあるのか……？" },
  { name: "エル", text: "それは、あれだよ、ムードメーカーとか……リーダーとか……" },
  { text: "エルが俺を励まそうと言葉を掛けてくれるが、正直逆効果な気がする。何も言うまい。" },
  { name: "瀬野", text: "ディザビリティ……？って何ですか？" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "うるさい！" },
  { name: "瀬野", text: "あっごめんヤマト……" },
  { name: "クロセル", text: "ご主人、苛立つのも分かるが、ゼノに当たっちゃダメだぞ" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "そうだな……ごめん瀬野" },
  { text: "そうだ、俺は苛立っている。一旦落ち着こう。深呼吸だ。息を大きく吐いて、吸い込む。それを数度繰り返すと、少しだけ心が落ち着いた。" },
  { text: "その後、俺達は暫く駄弁った後に、座ったまま仮眠を取った。出発した時間は深夜だ。睡眠が不要な魔剣達は良いとして、生身の人間である俺達は休息が必要だ。" },
  { text: "だが、こうして俺達が仮眠を取っている間も、アカツキは馬車を走らせ続けている。いつも思うが、彼女は働き過ぎだ、いつ倒れるか気が気でない。そんな憂いを抱きながら、俺はクロセルに身を寄せ、眠った。" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "いやーやっと息が出来ます、あの加護って奴ウザすぎでしょう、ボクのような、ザ！魔族！って感じの存在からすれば、いやー苦しくって堪りません" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "おいこいつ大丈夫なのか？実は余力を残してたとかで、加護が無くなった今、実体化して暴れたりしないか？" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "あーそれは無理ですよ、勇者ニコラスに肉体を破壊されたあの時点でボクの魔力すっからかんでしたから、勇者ティアを斬れたのが奇跡！って位にボロボロだったんですよ、まぁこれもあのジジイが異空間にボクを閉じ込めたのが全部悪いんですけど" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "クロセル、こいつは嘘を言ってないか？" },
  { name: "クロセル", text: "うむ、嘘は吐いてないな" },
  { name: "ラプラス", who: "laplace", expr: "mad", text: "あっ……失敗しましたねぇ……ボク悪魔ですから、嘘とか虚飾とかもっとやってかないと、これは怒られちゃいますなぁ……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "誰に怒られるんだよ……" },
  { name: "ラプラス", who: "laplace", expr: "blank", text: "ボクを作った存在ですかね？" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "誰だよ……" },
  { name: "ラプラス", who: "laplace", expr: "mad", text: "秘密☆って言ったら怒ります？" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "お前を破壊する" },
  { text: "それにしてもよく喋る剣だ。剣なのに悪魔を自称している。元悪魔の剣なのか剣が悪魔と自称しているのか、その辺りの詳しい所は良く分からないが、明らかに危険な代物だというのは分かる。同じ魔剣でもクロセルやグレモリーのようにまともな思考をしている訳ではない。魔王の破壊衝動とか抜きで、素があれだけ狂っているのだ、もはや救いようもない。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "やっぱあいつ破壊しないか……？" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "ヤマトさんがそうしたいなら良いですけど……利用価値はありそうですよ？" },
  { name: "クロセル", text: "あぁ、それは分かる、貴重な未来視の才能持ちで、それを契約者にも使わせる事が出来る、上手く使えば強力な武器になり得るのは事実だ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "まぁ……どんな物好きがあんな剣と好きで契約するのかって疑問はありますけどね……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "それこそ皇帝のような狂った奴だけだろうな……" },
  { text: "俺は溜息を吐く。あのラプラスって魔剣と話しているとこっちまで気が狂いそうになる。それも少女の声なのが質が悪い。魔剣に性別の概念とかは無いんだろうが、それでも少女の声や容姿をしているとどうもやりにくいのだ。男の姿形をしていればどうとでも出来るのだが。" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "えーっと何でしたっけ……ゼノとかいう魔族、ボクと契約しませんか？" },
  { name: "瀬野", text: "えっ僕？" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "そうです君です、力が欲しくはありませんか？ヤマト様の役に立てるような……力が" },
  { name: "瀬野", text: "僕が……ヤマトの役に……" },
  { text: "瀬野が息を呑む。その様子に、俺はまずいと判断して口を挟む。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "おい、悪魔の誘惑に乗るんじゃないぞ" },
  { name: "ラプラス", who: "laplace", expr: "sulk", text: "えーヤマト様ー｜邪魔《じゃま》しないで下さいよー" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "瀬野、こいつと契約したらろくなことにならないからな、絶対契約するなよ？絶対だからな！" },
  { name: "ラプラス", who: "laplace", expr: "surprised", text: "あっ！フリですか？" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "ちげぇよ！" },
  { name: "クロセル", text: "ご主人……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "憐れむような目で俺を見るな！くそっ！" },
  { name: "ラプラス", who: "laplace", expr: "blank", text: "あぁー流石は天下のヤマト様、毒を吐かれると……なんか……ボク……ゾクゾクしちゃいます……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "マゾかよ……" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "えぇそうですよ、ボクはマゾな悪魔なんです、ですから暴言とか足蹴にされるのとか大好物で、だからほら～もっとボクを虐めてくれても良いんですよ？" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "相手するだけ無駄な気がしてきた……" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ご主人、完全に遊ばれてるな" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "うるせぇ" },
  { name: "エル", text: "あはは……なんだかんだ言って仲が良いように見えるけど……" },
  { text: "エルが俺とラプラスを見て、くすくすと笑っている。見てる側からすれば面白いのかもしれないが、俺としては不愉快だ。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "あぁもういい……俺は黙るぞ" },
  { name: "ラプラス", who: "laplace", expr: "sulk", text: "えーつまんないじゃないですかーもっと構って下さいよーヤマト様ぁ……" },
  { text: "俺はラプラスの言葉を無視して黙り込む。その後も、なんだかんだあって馬車の中は賑やかだった。ラプラスの存在も大きいが、単純に人が増えたのも理由ではあるだろう。俺が黙っていても、仲間同士で会話は弾んでいた。一人だけ仲間外れにされているようで少しだけ癪だが、まぁ良い。" },
  { hide: "all" },
  { bg: "desert_border_dawn" },
  { comment: "明け方の国境長城突破" },
  { bgm: "tension" },
  { text: "そして、幾度目かの夜明けを迎える。明け方の空に照らし出された一つの物体。そしてそこから身を乗り出す人影を、国境警備の兵士は目撃する。だが、今更気付いてももう遅い。その物体、アカツキの操る馬車は、舗装された道をハイスピードで駆け抜け、｜躊躇《ちゅうちょ》なく切り込んでいく。" },
  { chara: { slot: "right", id: "crocell", expr: "laugh" } },
  { name: "クロセル", who: "crocell", expr: "serious", text: "――属性魔術……｜水弾《ウォーターボール》・｜雨《マシンガン》！" },
  { se: "magic" },
  { text: "身を乗り出していたのはクロセル。その掌から、無数の水の弾丸が放たれる。水で出来ているからと侮ってはいけない。その威力は拳銃から放たれる9mmパラベラム弾と同等。そんな攻撃が、無数に放たれる。もしあんな物が身体に直撃したならば、たちまち蜂の巣になる事は間違いない。無謀にも水弾の射線に立ち塞がった国境警備の教国兵は、水弾の雨を受け、一人……二人と倒れていく。" },
  { text: "ただ幸運だったのは、水弾が放たれた位置からだいぶ距離があった事だろう。この魔術は長距離で使う物ではない。長距離では威力が減衰し、ライオットガンのゴム弾程度に留まる。それでも人体を無力化する程度の威力はある。" },
  { name: "教国兵", text: "生身で射線に出るな！盾を持って防げ！" },
  { text: "しかし、教国兵とて馬鹿ではない。大盾を持った人の壁が生まれる。こうなると馬車では突破できない。同時に、唯一の出入り口である門が、ゆっくりと閉じていく。" },
  { name: "アカツキ", text: "門が閉じます！ヤマトさん！" },
  { chara: [
    { slot: "left",  id: "tia",     expr: "normal" },
    { slot: "right", id: "crocell", expr: "laugh" },
  ] },
  { name: "ヤマト", text: "構わない、想定内だ……ティア、クロセル！いけるか！？" },
  { name: "ティア", who: "tia", expr: "angry", text: "わたしに任せなさい！｜魔術回路構築《クリエイト》……詠唱……ル・トゥーム・アルガス・ティル――" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ふはははは！魔術の真髄を見せてやろう！｜術式干渉《ハイジャック》……｜魔力増幅《アクセラレーター》――" },
  { text: "ティアの詠唱に被せるようにして、クロセルも詠唱する。魔術とは万能な物で、複数人で力を合わせて一つの魔術を行使する事も出来るらしい。何故今の今まで使わなかったのか、その理由は極めて単純。力を合わせるまでもなく、別々で使った方が効率が良かったからだ。" },
  { se: "magic" },
  { fx: "flash" },
  { name: "二人", text: "「「――空間魔術……｜接続《コネクション》！！！」」" },
  { text: "馬車の前方に、馬車を丸々呑み込めるような巨大な空間の穴が生まれる。この世界で一番と二番の魔術師の合わせ技だ。物理的な障壁など、もはや無意味である。" },
  { fx: "flash" },
  { name: "アカツキ", text: "空間の穴！抜けました！" },
  { text: "馬車はトップスピードを維持したまま、空間の穴を通過する。さっきまで俺達の前方にあったあの国境の長城は、今や遥か後方に見える。これで無事に国境を超えれたと見て良いだろう。" },
  { name: "ヤマト", text: "教国を西に抜けた先、つまり此処はもう……" },
  { name: "ヤマト", text: "公国領だ！よし、逃げ切ったな！" },
  { text: "まだ辺り一面は砂の大地であり、教国を出たという実感は沸かないが、それでも確かに俺達は教国を出る事に成功したのだ。一先ずこれで俺達の無事は保証された。聖教会も、外国に逃げた俺達を捕まえるのには苦戦する筈だ。" },
  { name: "ヤマト", text: "Vの事が心配だな……尋問とかされてなければ良いが……" },
  { name: "アカツキ", text: "そうですね、無事を祈るしかありません" },
  { text: "Vが俺達の潜伏先を吐いた場合、聖教会が追ってくる可能性はある。だが、今はVの事を信じるしか無いだろう。もし見付かったらその時はその時だ。" },
  { name: "ヤマト", text: "最悪、海外に逃げるって手もあるよな……" },
  { name: "アカツキ", text: "ここの他に、人の住める大陸があるかは疑問ですね、もし存在するなら、既に公になっていてもおかしくは無い筈ですし" },
  { text: "アカツキの言う通りだろう。飛行艇や｜機甲兵《きこうへい》のような技術の確立されたこの世界で、まだ誰にも見付かっていない未知の大陸が存在すると考えるのは難しい。という事は、この世界に存在する大陸は此処だけだと考えるのが無難だろう。" },
  { name: "ヤマト", text: "次の潜伏先も使えなくなったら……本格的にやばいな" },
  { name: "アカツキ", text: "この世界での居場所が無くなったら、元の世界……とまではいかずとも別の世界に渡ったり出来れば良いんですけどね" },
  { name: "ヤマト", text: "空間魔術でなんとか出来ないのか？" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "無理だ、異空間を生み出したり、そこに出入りする事は出来るが、別の世界を生み出したり出入りする事は不可能だ" },
  { text: "クロセルがそう説明する。クロセルはこの世界で最強の魔術師だ。そんな彼女が断言するからには、魔術では不可能なのだろう。" },
  { name: "ヤマト", text: "さて……何処を目指してるんだったか" },
  { name: "アカツキ", text: "公国の都市アリエルツフィルです、地図で場所は確認しましたが、具体的にどういう場所かは不明です" },
  { name: "ヤマト", text: "そこを統治するセン公って奴に匿って貰うんだよな" },
  { name: "アカツキ", text: "そうですね、そのセン公って人物がどういう方なのかも不明です、少なくともアリエルツフィルの領主である事は確かですが" },
  { name: "ヤマト", text: "距離はどれくらいなんだ？何日ぐらい掛かりそうだ？" },
  { name: "アカツキ", text: "それなら安心して下さい、国境からだと3日も掛かりません、食料も足りる筈です" },
  { name: "ヤマト", text: "そうか、それなら良かった" },
  { text: "突然の旅で荷物も簡易的な物だったが、備蓄の面で心配する必要は無さそうだ。" },

  // ---------------------------------------------------
  // Scene 8: arielzfil — アリエルツフィル (EP96)
  // ---------------------------------------------------
  { label: "arielzfil" },
  { hide: "all" },
  { bg: "ariel_town" },
  { bgm: "town" },
  { name: "クロセル", text: "ご主人、目を覚ませ" },
  { name: "ヤマト", text: "……あ？もう朝か……ずっと馬車の中に居ると時間間隔が狂ってくるな……" },
  { text: "クロセルに起こされ、俺は軽く身体を起こす。ふと違和感に気が付く。どうも周りが静かだ。まだみんな寝ているのだろうか。" },
  { text: "辺りを見渡すと、そこに座っていた筈の仲間達が居ない。ついでに馬車も揺れていない……つまり停車中という事になる。" },
  { name: "ヤマト", text: "っておい……みんな何処行ったんだ？" },
  { name: "クロセル", text: "皆は既に馬車を降りてるぞ" },
  { name: "ヤマト", text: "ってことはまさか？" },
  { name: "クロセル", text: "うむ、着いたぞ、アリエルツフィルにな" },
  { text: "降り立った場所は森に囲まれた一つの街、アリエルツフィル。その入口付近に馬車を止めている。砂漠の砂塵の匂いに対して、森の緑の香りが心地良い。" },
  { chara: [
    { slot: "left",   id: "yamato",  expr: "normal" },
    { slot: "right",  id: "akatsuki", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "ふぅ……空気が美味いな" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "砂漠の砂塵の匂いに対して森の緑の香りは良いですよね、私も好きです" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "それじゃあ皆さん揃ったようですし、行きましょうか" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "ん……何処に行くんだよ" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "ヤマトさん……ボルトさんの話聞いてました？" },
  { name: "クロセル", text: "仕方ないな、ご主人。アリエルツフィルを治める貴族、セン公に会いに行くんだぞ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ、そう言えばそうだったな……そいつに匿って貰うんだった……" },
  { text: "欠けていた情報が脳に供給されると同時に、思考が整理される。そして、目覚まし代わりに頬をパチンと一叩き……しようとしてディザビリティにより弾かれる。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "よし、目が覚めた" },
  { name: "瀬野", text: "なんか弾かれてるけど……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "気にするな" },
  { text: "瀬野の冷静なツッコミを軽く受け流しながら、俺は街の入口の方へと歩き出す。街の中を軽く見渡してみる。家屋が立ち並び、人の往来もある。基本的には王国の建築様式と同じだろう。最初の村、タルフに近い感じだ。強いて言えば、あれよりも街の規模としては大きいか。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……セン公の住んでる場所って何処だ？" },
  { name: "瀬野", text: "えっ……自信満々に歩き出したから知ってるのかと思ったよ" },
  { name: "ニコラス", text: "よし、じゃあまずは聞き込みからだね、僕に任せてくれ" },
  { text: "何故か勇者が張り切りだす。交渉事はアカツキの担当って相場が決まっているのだが……まぁ良いか。勇者は辺りをきょろきょろと見渡すと、適当に人を見繕い、その場に走っていく。そして暫く街の人と話していたかと思えば、嬉しそうな顔をして戻ってきた。" },
  { name: "ニコラス", text: "セン公爵の屋敷の場所を聞いてきたよ！" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "おう、ご苦労だったな" },
  { name: "クロセル", text: "では勇者よ、案内を任せるぞ" },
  { name: "ニコラス", text: "うん、任せてくれ" },
  { text: "クロセルにそう命令されると、勇者は先導して道案内を始める。なんか生意気でウザいな。一発ぶん殴っときたい所だが、ディザビリティがあるからやっても虚しくなるだけだ。我慢しよう。" },
  { text: "街を歩いていると、街の人から奇異の視線を向けられる。余所から来た謎の集団が街の中を堂々と｜闊歩《かっぽ》しているのだ、不審がられるのは当然だろう。" },
  { name: "ニコラス", text: "という訳で、此処がセン公爵の屋敷だよ" },
  { bg: "sen_mansion" },
  { text: "暫く歩き、俺達は巨大な屋敷の前に立つ。俺は王城やヴァルハラ砦、上層と……各国の最上級の建築物を見ているから、それに比べれば小さいと思わずにいられないが、それでも立派な屋敷だ。" },
  { text: "一端の貴族の住まいにしては、大きすぎると言っても良いだろう。ボルトの紹介状を頼りに、俺は門を通って敷地内へと入ろうとする。だが、門の陰に隠れていた門番らしき男に肩を掴まれる。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "おい何すんだよ" },
  { name: "門番", text: "不審人物を屋敷の敷地内へ入れる訳にはいかない" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "あ？何だと？" },
  { text: "俺は無作法な男を睨み付ける。声を掛けるならまだしも、掴みかかってくるというのは明らかな敵対行為だ。喧嘩に発展する事を覚悟してやったに違いない。腰に携えた鉄棒を抜こうとした時、何者かに背中を引っ掴まれ、屋敷の敷地外へと引き戻される。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "おいアカツキ、何しやがる、こいつが先に手を出してきたんだぞ" },
  { name: "クロセル", text: "全く……無作法なのはご主人の方だぞ" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "そうですよ、私達は余所者なんです、アポイントも取ってないんですから無断で屋敷の敷地内に侵入したら不法侵入です" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "だからこいつがやった事は正当な行為だと言いたいのか？" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "そうです、違いますか？" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "違わねぇよ……くそっ……" },
  { text: "アカツキは門番の男の元へ歩いていき、話を始めた。" },
  { name: "クロセル", text: "喧嘩っ早いのはご主人の悪い所だな" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "クロセル、お前は人の事言えねぇだろ" },
  { name: "クロセル", text: "ふむ？そうか？我は比較的穏健派だと思うが" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "魔王の名を使って人を脅したり巨大な竜呼び出して人を脅したりしてた癖に何言ってんだ" },
  { name: "クロセル", text: "あ……あれは久々に世界を見たから少し興奮していたのだ、我は長らく封印されていたからな" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "そうか、じゃあそういう事にしといてやるよ" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "紹介状を見せたのか？" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "はい、ボルト・ドラゴファースト直筆のサインもありましたから、偽物だとは疑われませんでした、幸いですね" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "いや……本当に偉い奴なんだな、ボルトの奴" },
  { text: "アイシィ・ドラゴファーストが没した今、ボルトこそが正当な公国の後継者だ。そんな人物の紹介状ともなれば、公国に属する貴族である以上、無視できる物では無いのだろう。" },
  { name: "クロセル", text: "ん……誰か来たぞ" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "屋敷の使用人のようですね" },
  { text: "此方に一人の使用人らしき少女が歩いてくる。その身に纏うメイド服は、エルの物とは少し違っている。エルの物がヴィクトリアン式メイド服なのに対し、これは俗に言うフレンチ式メイド服という奴だろう。" },
  { text: "過多なフリルなどの装飾に、短い丈のスカート、ガーターベルトとニーソックス。厚底の靴を履いている辺り、身長を気にした上でこの格好をしている事は間違いない。フレンチ式メイド服は比較的露出が多く、男性の劣情を煽る事を語源とする服飾だ。それでも惹かれる物があるのは事実だ。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……良いな、エルにも着せたい" },
  { name: "クロセル", text: "ご主人、何を見惚れている" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "あ？見惚れてないが？" },
  { text: "クロセルが冷たい視線を送ってくる。煩悩を振り払い、改めて使用人の少女と対峙する。とても小さい子だ。ティアと同じくらいか、それよりも若いかもしれない。特筆すべきは薄桃色の長い髪の毛。クロセルのような純白では無い。白を基調とした色合いに、仄かに紅色を帯びている。" },
  { chara: { slot: "center", id: "esk", expr: "normal" } },
  { name: "？？？", who: "esk", expr: "normal", text: "ご案内にあがりました、ヤマト様" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "……あ？なんで俺なんだ？" },
  { name: "？？？", who: "esk", expr: "normal", text: "申し訳ありません……紹介状に名前があったのがヤマト様だけでしたので、そのお仲間の方も含めて、ご主人様がお待ちしています" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "あぁ……なるほどな" },
  { text: "あの短時間で要件だけを書くとすれば、全員の名前など書いていられないだろう。代表者である俺の名前だけを書いたのも納得できる話だ。" },
  { name: "クロセル", text: "ご主人はああいう服が好みなのか……だが我の服も似たような物だろう……何が違うというのだ……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "あ？クロセル……お前は分かっていない" },
  { name: "クロセル", text: "な……何をだ？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "ゴシック・アンド・ロリータとフレンチ式メイド服は別物だ、どちらもファッションとして明確な違いがあり、歴史があり、そしてそのどちらにも良さがある" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "似ているからと言って一括りにするのは断じてありえない、ナンセンスだ" },
  { name: "クロセル", text: "そ……そうか……良く分からないが……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "要するに、お前の服装は今のままでも十分に魅力的って事だよ" },
  { text: "少し熱くなってやや強い口調になってしまった。クロセルが目を逸らす。" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "ヤマトさん……何熱くなってるんですか、というか何で女性のファッションに｜造詣《ぞうけい》が深いんですか……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "熱くなってねぇし詳しくなんてねぇよ……無知な俺だが、違いは分かる、それだけの話だ" },
  { name: "？？？", who: "esk", expr: "normal", text: "あの……ご案内をしても宜しいでしょうか？" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "あぁ、そうだった、悪いな、案内してくれ" },
  { text: "少女は一つ頷いて、そのまま先導するようにして屋敷へ入っていく。俺達はその背に付いて行くようにして、セン公爵の屋敷に足を踏み入れた。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "それにしても広いな……玄関から応接室まで五分も歩くとか広すぎるだろ" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "そうなんですかね……私は王城で生活していたので感覚が麻痺しているのかもしれません" },
  { name: "クロセル", text: "我も魔王城で生活していたから狭く感じるな" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "いやこの屋敷の人間の前で狭いとか言うなよ……" },
  { text: "速やかかつ丁寧に俺達に茶を入れる仕草は、何とも洗練された動きだ。メイドとしての力量はエルよりも高いように思える。応接室には、一人の男性が肘掛け椅子に座っていた。" },
  { text: "肩まで伸びた長い金髪に、すらりとした長身の男性。18世紀のフランス貴族が着ていたような俗に言うロココ様式の服飾を纏っている。" },
  { text: "アビ・ア・ラ・フランセーズと言えば聞き覚えがあるだろうか。赤いアビのようなジャケットを基調とし、ウエストコートには細部に｜薔薇《ばら》のような花の｜刺繍《ししゅう》が施されている。" },
  { hide: "all" },
  { chara: [
    { slot: "left",   id: "yamato", expr: "normal" },
    { slot: "center", id: "sen",    expr: "smug" },
  ] },
  { name: "セン公爵", who: "sen", expr: "normal", text: "君がドラゴファーストの紹介した……ヤマト君で間違いないね？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ、その通りだ、お前がセン公爵で間違いないな？" },
  { name: "セン公爵", who: "sen", expr: "serious", text: "ほう、私を前にしてそんな口が利けるとは、教育が行き届いていないのか、まぁいい、私は寛大だからね" },
  { name: "セン公爵", who: "sen", expr: "serious", text: "私がアリエルツフィル領主、フラッシュ・バトゥシップ・セン公爵だ、公国の三大公爵家の一角と言えば無知な君達でも私の立場が分かるだろうか" },
  { chara: { slot: "left", id: "yamato", expr: "angry" } },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "アカツキ、三大公爵家ってのは？" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "私も言われて今思い出しました……ヤマトさん、貴族には爵位があるのはご存知ですよね" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "あぁ……伯爵とか男爵とか……そういう奴だろ？" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "はい、そして公爵は一番上の位に値します" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "要するに、こいつは｜公主《こうしゅ》と同レベルに偉いと？" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "三大公爵家とはこの公国を治める三つの公爵家です、ドラゴファースト家、シェル家、そしてセン家です" },
  { name: "セン公爵", who: "sen", expr: "serious", text: "これぐらいは基礎知識だが、どうやら君の従者は君に比べて中々に聡明なようだ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "くっ……俺が無知なのは認めるが、アカツキは俺の従者じゃない、仲間だ" },
  { name: "セン公爵", who: "sen", expr: "smug", text: "ふむ、そうか……彼女達は君の従者ではなく仲間だと" },
  { name: "クロセル", text: "我はご主人の従者だ、他は仲間だな" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、そうだ" },
  { name: "セン公爵", who: "sen", expr: "normal", text: "まぁ良い、些末な事だ、取り敢えず座りたまえ、あぁ……立ったまま話すのが好きだというのなら構わないがね" },
  { text: "一々嫌味な男だ。俺達は促されるまま、ソファに腰掛ける。それと同時に、先程の使用人の少女が現れ、机の上にティーセットを広げていく。" },
  { name: "エル", text: "ヤマト様……そんなにあの子が気になるの？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "ちげぇよ……目のやり場が無いから見てただけだ" },
  { text: "エルの指摘に、突っ撥ねるように言い返しながら、茶を口に含む。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "緑茶……？" },
  { name: "瀬野", text: "……に良く似たお茶ですね、少しだけ懐かしいです" },
  { text: "後味は少しだけ違うが、口に含んだ時の感覚は緑茶その物だ。まさか異世界で緑茶が飲めるなどとは思わなかった。" },
  { name: "セン公爵", who: "sen", expr: "serious", text: "お気に召したようで何よりだ、それで……本題に移ろうか" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "あぁ、そうだな、ボルトの話ではお前が俺達を匿ってくれるとの事だが……" },
  { name: "セン公爵", who: "sen", expr: "serious", text: "ドラゴファースト家には色々と借りがあるからね、ドラゴファーストの次男の頼みとあれば、断る訳にはいかないだろう。あぁ、快く了承したい所だが、一つだけ条件……いや、頼みがある" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "なんだ？" },
  { name: "セン公爵", who: "sen", expr: "smug", text: "公都襲撃の傷跡として、公国には今現在、多くの魔物が蔓延っている。君達を私の屋敷で匿う代わりに、アリエルツフィル周辺の魔物退治をして貰いたい" },
  { chara: { slot: "left", id: "yamato", expr: "smirk" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "それぐらいなら構わない、俺達の力があれば簡単な事だ" },
  { text: "魔王を打ち倒した俺達にとって、ただの魔物など雑魚同然だ。それで衣食住と安全が確保されるなら、これほど美味しい話はない。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "皆もそれで構わないな？" },
  { name: "クロセル", text: "我は問題ないぞ" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "私も問題ありません" },
  { name: "ティア", text: "問題ないわ！" },
  { name: "エル", text: "問題ないよ" },
  { name: "ニコラス", text: "僕の聖剣が疼いてる……" },
  { name: "瀬野", text: "ヤマトに従うよ" },
  { text: "一人だけ変な奴が居た気がするが、気にしたら負けだ。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "という訳だ" },
  { name: "セン公爵", who: "sen", expr: "normal", text: "そうか、引き受けてくれて感謝するよ、何しろこの街には冒険者が居ないからね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "冒険者が居ないのか？" },
  { name: "セン公爵", who: "sen", expr: "serious", text: "そうだよ、その理由は至って単純だ、冒険者ギルドがこの都市には無い、冒険者が依頼を受ける仲介所が無い以上、冒険者が此処で食べていくのは難しいのだろう" },
  { name: "セン公爵", who: "sen", expr: "serious", text: "魔物討伐の仕事は明日からで構わない、今日は屋敷でゆっくりすると良い、君達も旅で疲れているだろうからね。エスク、客人を部屋まで案内しなさい" },
  { name: "エスク", who: "esk", expr: "smile", text: "分かりました" },
  { text: "どうやらこの少女はエスクというらしい。覚えておこう。嫌味を言いつつも気遣ってくれる辺り、思いの外……良い奴なのかもしれない。" },
  { name: "エスク", who: "esk", expr: "normal", text: "それでは部屋までご案内します" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "おう、頼むぞ" },
  { text: "無論、いつも通り俺とクロセルは同室にして貰った。その事を後日セン公爵に報告兼許可を取りに行ったのだが、「主人が従者と同じ部屋で眠るのは当然だろう？」と返された。どうやら俺の価値観は間違ってなかったらしい。安心した。" },
  { text: "そして、俺達がアリエルツフィルに訪れた翌日から、セン公爵に依頼された魔物退治が始まった。" },

  // ---------------------------------------------------
  // Scene 9: esk_sniper — テラスの狙撃手 (EP97)
  // ---------------------------------------------------
  { label: "esk_sniper" },
  { hide: "all" },
  { bg: "ariel_town" },
  { comment: "EP97: 変異種の襲撃と謎の狙撃" },
  { bgm: "tension" },
  { name: "ニコラス", text: "聖剣……納刀……またつまらない物を斬ってしまったよ" },
  { name: "ヤマト", text: "片付いたか、クロセル、残存している敵は何体だ" },
  { name: "クロセル", text: "今探知魔法を使った所だ、これで周囲5km圏内の魔物の反応は一つ残らず消失した" },
  { name: "ヤマト", text: "なら今日の所は任務完了だな" },
  { text: "勇者が聖剣を納刀すると同時に、彼を取り囲んでいた狼のような魔物が一斉に血を吹き出して倒れる。俺達はアリエルツフィル南の郊外に来ていた。魔物を毎日少しずつ掃討して、今日で約一週間。セン公爵の依頼は八割程度完遂できたと言って良いだろう。" },
  { chara: [
    { slot: "left",   id: "nicholas", expr: "laugh" },
    { slot: "center", id: "yamato",   expr: "normal" },
    { slot: "right",  id: "crocell",  expr: "normal" },
  ] },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "ヤマト君、魔物の死体はどうする？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "肉は毒を含んでるから捨てていい、狼の魔物か……一応、毛皮だけ剥いどけ" },
  { text: "俺は皮剥ぎナイフを取り出し、勇者に向けて投げ付ける。勇者の顔面に命中。ディザビリティにより弾かれて、バウンドする。" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "よっ……と、刃物を投げたら危ないじゃないか" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "どうせ当たんないんだから別に良いだろ" },
  { text: "今この場にいるのは勇者と俺とクロセルの三人だけ。大人数で動くのは何かと目立つ上に、戦力過多だ。セン公爵の依頼をこなすのに最低限のメンバーだけ連れてきた形になる。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "まぁクロセルや勇者レベルになると、一人だけでも戦力過多なんだけどな……" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "うむ、そうだな。我も探知魔法で魔物を探すだけ、戦闘は勇者一人で事足りてしまう" },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "祝福が無くても僕は強い！いやーやっぱり僕って最強なのかなぁ……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "ウザい、一回殺しとくか？" },
  { name: "ニコラス", who: "nicholas", expr: "surprised", text: "ごめんやっぱ冗談！祝福無いから！普通に死ぬから！ね！？" },
  { text: "俺が軽く手を挙げると、勇者は首をぶんぶんと振りながらホールドアップする。そんな勇者に対して呆れたように溜息を吐きながら、俺は勇者の剥いだ魔物の毛皮を回収する。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "冗談だよ、さっさと帰るぞ" },
  { name: "ニコラス", who: "nicholas", expr: "surprised", text: "そっか……ふぅ……良かった……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "俺がディザビリティ持ちだって事分かってる癖に何動揺してるんだよ" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "いや……ヤマト君なら傷害のディザビリティを持ってても何らかの抜け穴を利用して殺してくる可能性も十分考えられるし……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "まぁ……出来そうな話ではあるよな、直接的な傷害行為が禁じられているだけで、間接的な傷害行為は通る事が証明されている" },
  { text: "確かに、勇者の言う通り。少し頭を使えば何とかなりそうな物だ。まぁ、本気で勇者を殺すつもりは無いから、不要な心配だが。少なくとも今は。そういう訳で、俺達三人はセン公爵の屋敷へ帰る為に、アリエルツフィルの街中を歩いていた。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "あれだけ魔物が居るならアリエルツフィルに被害が出ててもおかしくない気がするが、俺達が来る前はどうしてたんだ？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "あぁ、ご主人には分からないか。アリエルツフィルには全域に結界魔術が掛けられている、魔術の才能を持つ者で無ければ気付け無い程度に微弱な物だがな" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "結界魔術か……それなら確かに魔物が侵攻してこないのも納得だが……人間や魔族には影響は無いのか？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "認識阻害の結界魔術だからな、知性を持つ者には殆ど効かないが、知性を持たない魔物相手ならば、アリエルツフィルが人の住む都市である事を隠蔽する事が可能だ" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "なるほど、良く分からないが凄いな、アリエルツフィル全域って言うと結構な大規模魔術じゃないか？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "規模は大きいが結界自体は微弱な物だからな、消費魔力は才能指数5以上の魔術師であれば事足りる程度の物だ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "つまりその結界魔術を貼ってる奴は才能指数5以上の魔術師って事か、誰なんだろうな" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "そんなの決まってるだろう、セン公爵だぞ" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "えっ……あいつ？魔術師なのか？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "セン公爵は才能指数6の結界魔術師だ。公国の広域が滅ぼされたにも関わらず、アリエルツフィルが未だ無事な理由も納得出来るな。恐らく、公国が魔王軍の襲撃を受けた時も、認識阻害の結界でこの街を守っていたのだろう" },
  { text: "それを知っていたからこそ、ボルトもアリエルツフィルが健在だと考え、セン公爵を頼ろうと考えたのだろう。そんな風に話している間に、俺達はセン公爵の屋敷へと帰ってくる。" },
  { bg: "sen_mansion" },
  { chara: { slot: "right", id: "esk", expr: "normal" } },
  { name: "エスク", who: "esk", expr: "smile", text: "おかえりなさいませ、ヤマト様、クロセル様、ニコラス様" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "ただいま、エスク" },
  { text: "この一週間、屋敷で生活してきたが、使用人らしき人物は彼女しか見ない。掃除も炊事も洗濯も彼女一人がこなしている。" },
  { text: "セン公爵の家族らしき人物も居ない。門番の男を含め、この屋敷には本来三人の人間しか住んでいないと推測できる。" },
  { chara: { slot: "left", id: "el", expr: "smile" } },
  { name: "エル", who: "el", expr: "smile", text: "おかえりなさい、ヤマト様" },
  { text: "屋敷の廊下からもう一人のメイドさん。エルが現れる。彼女は俺達を待っていたのではなく、偶然通りかかっただけのようだ。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "あ……エルか。エル、屋敷の家事も人が増えて大変だろうからエスクを手伝ってやったらどうだ？" },
  { name: "エル", who: "el", expr: "troubled", text: "あはは……私もそう思って手伝うって言ったんだけどね……断られちゃった" },
  { name: "エスク", who: "esk", expr: "serious", text: "お気持ちは感謝致します、ですが屋敷の事は私一人で十分ですので" },
  { text: "エスクは一礼すると、そのまま何処かへと消えていく。" },
  { hide: "esk" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "幽霊みたいな子だよな" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "同感だよ、あの子、気配を殺すのが上手いね、暗殺者としてもやっていけそうだよ" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "彼女、隠蔽の才能持ちだな、我の分析の才能で才能と才能指数が測れない" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "なるほどな……道理で｜神出鬼没《しんしゅつきぼつ》だと思った" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ただ、戦闘系の才能は持っていないと思うぞ" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "なんでそう思うんだ？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "筋肉の付き方だ、彼女は戦闘をする人間の筋肉の付き方はしていない、故に戦闘経験は皆無だろう。本来はこういう測り方が正しい分析の才能の使い方なのだがな" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "じゃあエル、これをアカツキに持っていってくれ" },
  { name: "エル", who: "el", expr: "troubled", text: "うん、分かった" },
  { text: "魔物から手に入れた戦利品の売却はアカツキに頼んでいる。毛皮の山を運んでいくエルを見送ると、俺は自分の部屋の方へと歩いていく。" },
  { hide: "el" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "じゃあ僕はこれで" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "おう、ご苦労だったな" },
  { text: "廊下の分かれ道で勇者と別れる。こうして俺とクロセルは二人っきりになった。部屋の方へと歩いていく途中、俺は違和感に気が付く。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "……なんか聞こえないか？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "うむ、我にも聞こえるぞ、これは……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "悲鳴だ！チッ……面倒事に首を突っ込みたくはないが、この街を守るとあの貴族男に約束しちまったからな……行くぞ、クロセル！" },
  { bg: "ariel_town" },
  { bgm: "battle" },
  { text: "玄関を飛び出て、騒ぎの起きている北西の方向へ走る。200mほど走った辺りで、俺達は騒ぎの原因と思われる物を発見した。" },
  { chara: { slot: "center", id: "yamato", expr: "surprised" } },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "あれか……どうして魔物が街の中に……" },
  { chara: { slot: "right", id: "crocell", expr: "angry" } },
  { name: "クロセル", who: "crocell", expr: "angry", text: "ご主人、あれは変異種だ。殺人の才能を持った魔物、人を殺す為だけに存在する魔物。だから認識阻害の結界を無視して街に入ってきたのだろう" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "セン公爵の結界も万能じゃないって訳か。これ以上被害が出る前に殺すぞ、クロセル、やれるか" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "我に任せておけ" },
  { text: "視界の先に居たのは、翼の生えた中型の竜。プテラノドンが近いだろうか。その魔物は、地面に転がった人の死体らしき血肉の塊を貪り食っている。既に犠牲者が出てしまっている。クロセルが片手を翳し、無数の水の弾丸を放つ。……筈だったのだが。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "おいクロセル、効いてないぞ！？" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "殺人の才能に加え、対魔力の才能だと……くっ、想定外だった" },
  { text: "クロセルの放った水の弾丸は、変異種の身体に触れると同時に跡形も無く消失する。魔術による直接的な攻撃が効かない。魔術師であるクロセルにとっては致命的な問題だ。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "どうする？今からでも勇者を呼んでくるか？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "案ずるな……魔術で作り出した物質で物理攻撃をするのなら攻撃が通る" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、いつもの氷の剣と肉体強化の魔術だな、確かにあれなら……" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "｜魔術回路改竄《カスタマイズ》……｜略式詠唱展開《ファストキャスト》……" },
  { fx: "shake" },
  { se: "roar" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "おい！飛んだぞクロセル" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "そうか……翼竜だから飛行するのは当然だな、少し待て……風魔術で空を飛べば……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "詠唱間に合うのか！？来るぞ！？" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "うるさい黙っておれ！集中出来んだろう！" },
  { text: "変異種は上空へと飛び上がり、真っ直ぐと滑空を始める。目標は当然、俺達。氷の剣に加えて強化魔術、飛行魔術と二種類の魔術が必要だ。恐らくだが……間に合わない。" },
  { chara: { slot: "center", id: "yamato", expr: "angry" } },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "くっ……こうなったら｜解除《アンロック》を使うしか……" },
  { text: "そう覚悟した時の事だった。何かが風を切る音。物体の飛翔音。それが第三者による攻撃であると認識すると同時に、その飛翔物体は着弾する。" },
  { se: "gunshot" },
  { fx: "flash" },
  { text: "変異種の頭部から血が吹き出たかと思えば、そのままぐらりと姿勢を崩し、地面へと墜ちた。" },
  { bgm: "mystery2" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "今のは……誰だ？" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "ご主人がやったのではないのか？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "俺じゃない、って事はお前でも無いんだな？" },
  { text: "今のは確実に第三者による射撃だ。それも魔法ではない。この街に冒険者は居ないし、俺達の仲間にも魔術を使わずに遠距離攻撃が出来る者は居ない。瀬野が拳銃を持っていたが、その射程距離の中に瀬野の姿は無い。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "一体誰だ……？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "分からんな、今のは我の探知能力の外部から放たれた攻撃だ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "って事は狙撃？しかも動きながら飛んでいる物体に対してあんな正確に……" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "まぁ助かったから良しとしよう" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ……そうだな" },
  { text: "変異種が倒れたのを確認すると、辺りから｜野次馬《やじうま》と警察組織が集まってくる。血溜まりに転がっている人であった物は既に死んでいる。他に怪我人も居ないようだ。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "さて、俺達はさっさと退散するか、今回は何もしてないしな" },
  { text: "人混みを避けるようにして、俺達は現場から姿を消した。" },
  { hide: "all" },
  { bg: "sen_mansion" },
  { comment: "視点転換: セン公爵邸三階テラス" },
  { pov: "esk" },
  { bgm: "romance" },
  { text: "――セン公爵の屋敷。三階に位置するテラス。" },
  { chara: [
    { slot: "left",  id: "sen", expr: "normal" },
    { slot: "right", id: "esk", expr: "serious" },
  ] },
  { text: "そこには、白い椅子に座りながら、優雅に茶を飲むフラッシュ・バトゥシップ・センの姿があった。そして、テラスの塀に身を乗り出す、もう一人の人間。手に装飾過多な長銃を持ち、遥か彼方を見据えている。" },
  { name: "エスク", who: "esk", expr: "smile", text: "3、2、1……発射……命中しました" },
  { text: "そんな彼女の手には、可憐な容姿には似合わない長銃が握られており、その銃口からは僅かに煙が立ち上っていた。" },
  { name: "セン公爵", who: "sen", expr: "serious", text: "ご苦労様、結界内に侵入した外敵は以上だよ" },
  { name: "エスク", who: "esk", expr: "normal", text: "そのようですね、では任務完了です" },
  { name: "セン公爵", who: "sen", expr: "serious", text: "相変わらず\"千里眼\"の才能は恐ろしいね、エスク" },
  { name: "エスク", who: "esk", expr: "serious", text: "お褒めの言葉、｜恐悦至極《きょうえつしごく》に存じます" },
  { text: "彼女の瞳は赤く光っていた。文字通り、その瞳で人間の視力では到底視ることの出来ない長距離を見渡せる能力。それが彼女の持つ千里眼の才能だ。" },
  { name: "エスク", who: "esk", expr: "smile", text: "これも全て、ご主人様の下さったこの聖銃と結界魔術のお陰です" },
  { name: "セン公爵", who: "sen", expr: "smug", text: "聖銃ファイナルノート、弾が要らず、無限の射程を持つ狙撃銃であり、セン家に代々伝わる秘宝だ。だが今までのセン家にはそれを扱える人間が居なかった、そう……君を除いてね" },
  { chara: { slot: "right", id: "esk", expr: "smile" } },
  { name: "エスク", who: "esk", expr: "normal", text: "ご主人様に巡り会えた事、それが私の人生において最も幸福な出来事です" },
  { text: "エスクは銃を机の上に置くと、主人の座る椅子に近付く。セン公爵は、そんなエスクを抱き寄せると、そのまま顔を近付け、｜口吻《こうふん》を交わした。" },
  { name: "エスク", who: "esk", expr: "serious", text: "っゅ……ご主人様……" },
  { name: "セン公爵", who: "sen", expr: "smug", text: "優秀な従者には褒美をやらねばなるまい" },
  { name: "エスク", who: "esk", expr: "smile", text: "ぁっ……んっ……ありがたき幸せ……" },
  { text: "アリエルツフィルが無事だった理由。それは結界魔術師センと狙撃手エスクの二人の尽力が全てだ。だが、それを知る者は居ない。街の人にも、誰にも感謝される事無く、ただ役目を果たし続ける。それがこの地を治めるセン家に与えられた役割であるから。だが理由は、それだけではない。" },
  { text: "セン公爵は、この地を愛しているのだ。心の底から。それを守るのは、決して義務感から来るものではない。守りたい物だから、大切な物だから、その身を削ってでも守るのだ。" },
  { chara: { slot: "left", id: "sen", expr: "serious" } },
  { name: "セン公爵", who: "sen", expr: "normal", text: "今私が守りたい物は……それだけではないがね" },
  { name: "エスク", who: "esk", expr: "normal", text: "……？ご主人様？" },
  { name: "セン公爵", who: "sen", expr: "normal", text: "いや、何でも無いよ" },
  { name: "セン公爵", who: "sen", expr: "serious", text: "アイシィ、お前の守りたかった物、全てではないが……私が守っている、だから安心して眠ると良い" },
  { text: "そよ風が吹いて、優しく辺りの木々を揺らした。" },
  { name: "セン公爵", who: "sen", expr: "serious", text: "さて、では仕事に戻るとしようか" },
  { name: "エスク", who: "esk", expr: "smile", text: "承知しました、片付けはお任せ下さい" },
  { text: "セン公爵はティーカップに注がれた液体を飲み干すと、そのまま立ち上がり、テラスから去っていった。こうして、またセン公爵の屋敷には、変わりのない日常が訪れた。" },

  // ---------------------------------------------------
  // Scene 10: yamato_origin — ヤマトの過去 (EP98)
  // ---------------------------------------------------
  { label: "yamato_origin" },
  { pov: null },
  { hide: "all" },
  { bg: "sen_mansion" },
  { comment: "EP98: 転生組の本名開示と｜孤児《こじ》の過去" },
  { bgm: "daily" },
  { chara: [
    { slot: "left",   id: "yamato",   expr: "normal" },
    { slot: "center", id: "sen",      expr: "smug" },
    { slot: "right",  id: "akatsuki", expr: "normal" },
  ] },
  { text: "俺はアカツキと二人で、セン公爵の部屋へ魔物退治の進捗の報告に来ていた。部屋について特筆すべき点は無い。敢えて似ている部屋を挙げるとすれば、アカツキの執務室だろうか。ただ、見慣れない｜骨董《こっとう》らしき調度品や観葉植物、絵画など、機能性よりデザインを重視した部屋である所がアカツキの執務室と違う所だ。逆に、そういう所だからこそセン公爵の性格が出ているとも言えるが。" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "以上が報告です、アリエルツフィル近郊の魔物は一掃出来たと考えられます" },
  { name: "セン公爵", who: "sen", expr: "serious", text: "そうか、ご苦労だったね、ただのタダ飯食らいと思っていたが、思いの外使えるようだ" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "なんだとてめぇ" },
  { name: "セン公爵", who: "sen", expr: "smug", text: "おや、褒めたつもりだったのだが" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "いえ、魔物の脅威がゼロになったとは言えないですし……今後も出来る限りは続けるつもりですが……" },
  { name: "セン公爵", who: "sen", expr: "normal", text: "いや、もう良い、君達は十分に働いてくれた、依頼は完遂という事で構わないよ" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "せっかく続けてやるって言ってるのに、何故断るんだ" },
  { name: "セン公爵", who: "sen", expr: "serious", text: "必要無いからだ、私は無駄な事はしない主義でね、全く効果の無い依頼を続けるというのも無駄な事だと言える、だからもう良いと言っているんだ" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "あ？俺達の仕事が無駄だと言いたいのか！？" },
  { name: "セン公爵", who: "sen", expr: "serious", text: "そうだが、何か問題があるかい？" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "な ん だ と？" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "ヤマトさん……気持ちは分かりますが抑えて下さい……" },
  { text: "今にも殴りかかろうとしていた俺を、｜既《すんで》の所でアカツキが抑える。仮に手を出したとしても、ディザビリティがある故に、大事には発展しないが、それでも喧嘩沙汰になるのは問題だ。こいつに嫌われると匿って貰えなくなる可能性がある。だから機嫌を伺わないといけない立場ではあるのだが……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "あぁくそっ……腹が立つ……" },
  { name: "セン公爵", who: "sen", expr: "smug", text: "怒らせてしまったのなら謝罪しよう、再三言うが君達には感謝しているんだ、その言葉に偽りはない" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "あぁそうかよ……で、魔物退治はもう良いんだな" },
  { name: "セン公爵", who: "sen", expr: "smug", text: "そうだ、辞めて貰って構わない、今日までご苦労だった" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そうかよ……アカツキ、行くぞ" },
  { name: "セン公爵", who: "sen", expr: "serious", text: "やれやれ……アカツキ君、ヤマト君には少し言葉には気を付けるように言ってくれるかな" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "分かりました、私から言っておきます" },
  { name: "セン公爵", who: "sen", expr: "normal", text: "助かるよ、君は優秀で、聡明だ。もしその気があるならば……私の従者になる気は無いかな？" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "アカツキがお前の従者になんてなる訳無いだろ！" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "考えておきます" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "断れよ！" },
  { text: "尤も、アカツキも本気で考えるつもりは無いらしい。俗に言う社交辞令という奴だ。" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "ああいう奴が一番嫌いなんだよ……皇帝と同じ物を感じる" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "あぁ……まぁ分からなくも無いですが" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "大体名前からしてふざけてるだろ……フラッシュとかバトルシップとか、閃光なのか戦艦なのかはっきりしろよ" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "閃光なんじゃないですかね……セン公爵ですし……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "……" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "なんで黙るんですか！" },
  { hide: "all" },
  { text: "セン公爵の部屋を出た後、俺達は割り振られた部屋の一つで、雑談に興じていた。メンバーは俺とクロセル、アカツキ、瀬野。エルとティアは少し離れた所でトランプをしていた。" },
  { chara: [
    { slot: "left",   id: "akatsuki", expr: "normal" },
    { slot: "center", id: "yamato",   expr: "normal" },
    { slot: "right",  id: "zeno",     expr: "smile" },
  ] },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "名前と言えば、瀬野さんの瀬野って名字ですよね、名前はなんて言うんですか？" },
  { name: "瀬野", who: "zeno", expr: "smile", text: "僕は｜瀬野《ぜの》｜充《あたる》だよ、アカツキさんは？" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "私は｜水若《みなも》｜暁《あかつき》です" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "え……アカツキって名字じゃなかったのかよ" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "そうですよ、だからヤマトさん私の事ずっと呼び捨てにしてきたんですからね" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "……いや他の奴も呼び捨てだし別に良いだろ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "それもそうですけど……じゃあヤマトさんのフルネームは何なんですか" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "俺？ヤマトだけど" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "名字ですよ、まさかヤマトが名字だとは言いませんよね？" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "えっいや……だからヤマトだって" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "そんなに言いたくないんですか……？" },
  { name: "クロセル", text: "いや、アカツキ、ご主人は嘘を言っていないぞ、ご主人は本当に\"ヤマト\"なのだ" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "どういう事です？" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "だから……俺には姓が無いんだよ、名前が無いから自分で付けた、｜孤児《こじ》だからな" },
  { chara: { slot: "left", id: "akatsuki", expr: "surprised" } },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "ごめんなさい、嫌な事を聞いてしまって……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あっいや別に良いんだぞ？親なんて顔も名前も知らないし、｜孤児《こじ》である事を指摘されてショックを受けるようなガキでもねぇし" },
  { name: "クロセル", text: "ふむ、我は少し気になるな、ご主人の昔話" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "瀬野は知ってるだろうし、アカツキには前に言っただろ" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "それより前の話ですよ、嫌なら話さなくても良いですけど" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "聞いても面白くないと思うがな" },
  { name: "クロセル", text: "ご主人の話なら何でも面白いから早く話してみるが良い" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "プレッシャーになるから期待に満ちた視線を送るのはやめろ！" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "分かった……俺が｜孤児《こじ》ってのは言ったな" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "そうですね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "身寄りの無い俺は、他の｜孤児《こじ》と同じように施設に入れられた、決して快適とは言えなかったが、生きていく上で不自由はしなかったよ" },
  { text: "あの頃は、最低限の衣食住は確保されていた。あれも、一種の幸せの形だったのかもしれない。もしあのまま施設で暮らしていたら、どんな未来が待っていたのだろう。いや、考えても無駄な事だ。人生にIFは無いのだ。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "13歳の時、俺はある傷害事件を起こした、そして施設から追い出されたんだ" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "傷害事件……ですか" },
  { name: "クロセル", text: "要するにご主人がいつものように｜無辜《むこ》の人間に喧嘩を売ったのだろう？それで追い出された訳か" },
  { chara: { slot: "right", id: "zeno", expr: "serious" } },
  { name: "瀬野", who: "zeno", expr: "serious", text: "いや、それは違います。ヤマトは僕を守ってくれたんです、高校生の不良達に絡まれて、殺されかけていた僕を……守る為に拳を振り上げた" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "あぁ、まぁそうとも言える、それが俺と瀬野の出会いだ" },
  { name: "クロセル", text: "そうか、流石はご主人だな！我はそうだと思っていたぞ！" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "掌返しやがって……" },
  { name: "瀬野", who: "zeno", expr: "serious", text: "その時のヤマトは本当に格好良かったんですよ！自分より背の高い男達を一人でボコボコにやっつけて、返り討ちにしたんですから" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "違う、あれはお前が弱すぎただけだ、あんな雑魚に虐められるとか、弱すぎだろ" },
  { name: "瀬野", who: "zeno", expr: "sad", text: "そんな事無いよ……僕だってちゃんと鍛えてたし……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "あれで鍛えてたと言うなら全人類が鍛えてる事になるぞ……" },
  { text: "小さな頃から大人しい子とは言えなかった。喧嘩っ早いし、暴力で物事を解決する事はしょっちゅうあった。それは決して英雄の所業ではなく、酷く利己的な物。" },
  { text: "瀬野を助けたのも、瀬野を虐めていた奴らに腹が立ったから。それだけの理由だ。だから俺は、瀬野が憧れるような良く出来た人間ではない。根っからの悪人なのだ。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "その後、施設を追い出された俺は13歳にして｜路頭《ろとう》に迷う事になった。その先は悪の道だ、生きる為の物も、金も、人から奪った。あの頃はただ生きるのに必死だったからな、次第に俺は力をつけ、仲間を従えるまでになった。気が付けば俺は霧雨組の頭になっていた" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "それは……大変でしたね……" },
  { name: "クロセル", text: "生きる為に奪う、それは至極当然の事だろう？世界は｜弱肉強食《じゃくにくきょうしょく》、強い者が弱い者から奪うことは自然の｜摂理《せつり》とも言える" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "だとしても俺の悪事が正当化される訳じゃない、どんな理由であれ、人を殺していい事にはならないだろ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "ヤマトさんは人を殺した事が……？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "ある、幻滅したか？" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "いえ……それでも私は、ヤマトさんの行為が純粋な悪だとは断言できません、仕方がなかった……と思います" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "そうか、そう思うのは勝手だが……" },
  { text: "瀬野もアカツキも、何故俺なんかの事を庇うのだろう。悪人の仲間という肩書を恐れて、俺の事を正当化しているに過ぎない。利己的な理由だ。本当の意味で俺を庇う奴など……居る筈がない。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "その後は知っての通りだ、ヘマをして瀬野と一緒に異世界転生、クロセルを拾って奪われて、アカツキに助けられて……" },
  { chara: { slot: "right", id: "zeno", expr: "normal" } },
  { name: "瀬野", who: "zeno", expr: "normal", text: "えっ……僕との旅は？前から思ってたんだけど……ヤマト、もしかして僕との旅の事……もごっ" },
  { text: "瀬野が何か言おうとした瞬間、後ろから手が伸びてきて、その口が塞がれる。エルだ。" },
  { chara: { slot: "right", id: "el", expr: "smile" } },
  { name: "エル", who: "el", expr: "smile", text: "瀬野さん借りてもいいかな？" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "何に使うのか知らないけど……良いぞ" },
  { name: "瀬野", who: "zeno", expr: "sad", text: "もごもごっ……" },
  { name: "エル", who: "el", expr: "smile", text: "ありがとう、じゃあ私は失礼するね" },
  { text: "エルはそのまま瀬野を引き摺って何処かへと消えていく。なんだろう、突然現れて突然去っていった。そう言えばティアは良いのか？" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "瀬野さん何か言おうとしてませんでした？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あいつの事だから大した事じゃないだろ" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "そんな雑な扱いで良いんですかね……" },
  { text: "――この時の俺は、まだ知らなかった。この瞬間を、どれほど悔やむ事になるのかを。" },
  { chara: { slot: "right", id: "crocell", expr: "sad" } },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "良いんだよ、さて……俺に過去を話させたんだからお前も話してくれるよなぁ……クロセル" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "なんで我なのだ！？その流れだとアカツキではないのか！？" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "いや、アカツキの過去とか興味ないし……" },
  { name: "アカツキ", who: "akatsuki", expr: "angry", text: "少しくらい興味持ってください！" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "なんでキレられてんの？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "だが我の話も……前にご主人にしたと思うが……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "魔族だった頃の話だろ、魔王になった以降の話は聞いてない" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "うぐっ……確かにそうだな……" },
  { text: "今まで何度も話す機会はあった筈だ。なのにクロセルは、この話題を意図的に避けていた。つまり……多分黒歴史なのだろう。" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "我の魔王時代か……聞いてもあまり面白くないと思うが" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "さっき俺が同じ事を言った時にお前はなんて返した？" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "……ご主人の話なら何でも面白い……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "その言葉、そっくりそのまま返してやるよ" },
  { text: "俺はニヤリと口角を上げる。困った様子のクロセルが可愛らしくてつい意地悪をしたくなる。クロセルは大きく溜息を吐くと、俺とアカツキ以外に人が聞いてないのを確認しながら、ゆっくりと話し始めた。" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "――我の魔王時代は……" },

  // ---------------------------------------------------
  // Scene 11: crocell_maou_past — 回想『Crocell V』 (EP99)
  // ---------------------------------------------------
  { label: "crocell_maou_past" },
  { fade: "out" },
  { hide: "all" },
  { bg: "maou_wasteland" },
  { fade: "in" },
  { comment: "EP99: クロセル(ルツ)の魔王時代の回想" },
  { bgm: "sad" },
  { pov: "lutz" },
  { text: "――700年前。" },
  { chara: { slot: "center", id: "lutz", expr: "sad" } },
  { name: "ルツ", who: "lutz", expr: "sad", text: "此処は……何処だ……？私は……" },
  { text: "私は見渡す限りに続く広い荒野の中央で、地面に倒れ伏していた。全身にどす黒い力が巡っているのを感じる。そうだ……私は魔王の力を継承して……それで……" },
  { text: "魔王の力を継承した場合、力の元の持ち主は死亡する。つまり……そうだ、私の主人は、勇者に殺されて死んだ。いや……違う、そうじゃない。" },
  { name: "ルツ", who: "lutz", expr: "sad", text: "あの方を殺したのは私だ。私なんかが居なければ、あの方は勇者を倒して生き永らえていただろう……っうっ……ああっ……" },
  { text: "悲しみと寂しさと自己嫌悪で、涙が溢れる。一人残される事がこんなにも辛いだなんて。幾ら泣いても、誰も助けてはくれない。それも当然だ、あの方こそ、私のたった一人の理解者だったのだから。" },
  { name: "ルツ", who: "lutz", expr: "sad", text: "人間に私の存在を悟られてはいけない……何処かに身を隠さないと……" },
  { text: "あの方は私が生きる事を望んだ。今、人間の前に姿を現したりしたら……私は殺されるだろう。だから可能な限り身を隠さねばならない。独り孤独に生きる。それが私の罪に対する罰なのかもしれない。" },
  { name: "先代魔王の声", text: "相変わらず泣き虫だな、ルツ" },
  { name: "ルツ", who: "lutz", expr: "surprised", text: "っ！？この声は……？いや……そんな筈は……幻聴？" },
  { name: "先代魔王の声", text: "悪いけれど、多くは語れない、これから過酷な運命を向き合う事になる君を激励する為に、僕は最後の力を使った" },
  { text: "私の頭の中に声が響く。これは間違いなく私の主人、魔王様の声だ。私が魔王になってから既に一夜以上が経過している。という事は、彼は既に死んでいる筈。これは彼の魂、或いは残留思念のような物なのだろうか。ああ、そんな事はどうでも良い。なんでも良い。私にとって一番大切な人の声を聞けた。それだけで私は勇気付けられる。" },
  { name: "先代魔王の声", text: "だから――、泣くな" },
  { name: "ルツ", who: "lutz", expr: "sad", text: "分かり……ました……" },
  { name: "先代魔王の声", text: "僕はきっと君の側に居る、目に見えなくても、声は届かなくても、僕の意志は不滅だ" },
  { text: "そうだ……私は一人じゃない。きっと魔王様が側に居てくれる。だから私は……大丈夫だ。空腹感は感じない、息を止めても苦しくない。寒さも暑さも感じない。流石は魔王の身体、どんな劣悪な環境でも生きていける。" },
  { text: "だが、数ヶ月の時を経て、彼女の身体には異変が起きる。魔王の本能、破壊衝動。何でも良いから壊したい、殺したい、そんな考えが脳裏に過る。" },
  { name: "ルツ", who: "lutz", expr: "sad", text: "嫌だ……私は誰も何も傷付けたくない！っああっ……うあああああああああ！" },
  { fx: "shake" },
  { text: "本能に反する意志を抱く度に、反作用のように苦痛の濁流が押し寄せてくる。魔王様は、私の主人は、こんな苦痛を意志の力だけで抑え込んでいたというのか。" },
  { name: "ルツ", who: "lutz", expr: "sad", text: "やっぱり魔王様は凄い……私なんか到底及ばない。望まずして魔王になったのは私だけじゃない……あの方も、歴代の魔王達も、同じ苦しみを抱いていたのかもしれない" },
  { name: "ルツ", who: "lutz", expr: "sad", text: "あぁ……誰か……私を……それがダメなら……私自身で私を……" },
  { text: "その先の言葉を紡ごうとして、私は思い留まる。あの方は私に生きて欲しいと願ったのだ。自ら命を断つ結末など、あの方は望まない。" },
  { name: "ルツ", who: "lutz", expr: "sad", text: "楽になりたい……何でも良い、この衝動を抑えられる物……何か……" },
  { text: "私は眼の前の巨大な熊の魔物に拳を叩き込む。魔物は人類の敵……だから殺しても問題ない……よね。次の獲物は兎の魔物、一撃で仕留める。暴力行為によって、心が満たされるのを感じる。" },
  { text: "魔物は魔王や魔族に友好的な存在。故に反撃も存在しない。無抵抗の生き物を、ただ狩るだけだ。彼女は、魔物を狩る事でのみ、破壊衝動を発散して生き延びた。" },
  { name: "ルツ", who: "lutz", expr: "smile", text: "あはっ……あはははは、楽しい、魔物を狩るのがこんなにも楽しいなんて" },
  { hide: "all" },
  { text: "それから数年。アドラツェスト王国の辺境の街にて、大量の魔物による襲撃が起きていた。冒険者も自警団も全滅した。金髪の魔族ヴァルフが魔物を従え、人々を絶望させていた。" },
  { chara: { slot: "center", id: "crocell", expr: "laugh" } },
  { name: "クロセル", who: "crocell", expr: "serious", text: "魔術全書第七十八章四十五節、｜召異魔術《しょういまじゅつ》　｜魔術回路改竄《カスタマイズ》……｜略式詠唱展開《ファストキャスト》――｜召異魔術《しょういまじゅつ》……｜神竜召喚《バハムート》" },
  { se: "roar" },
  { fx: "flash" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "薙ぎ払え、｜神竜《バハムート》" },
  { text: "街の人々の頭上に現れたのは、巨大な黒い翼竜。最大にして最強の竜のブレスが、全ての魔物を跡形も無く消し去った。" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ふぅ……やはり｜殺戮《さつりく》とは心踊る物だ、我は今……随分と気分が良い" },
  { name: "魔族ヴァルフ", text: "い……今のをやったのはお前か！" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "あぁそうだとも、我の仕業だ" },
  { name: "魔族ヴァルフ", text: "お前……一体何者なんだよ……勇者か！？それとも有名な冒険者か！？" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "違うな、我は勇者ではない、冒険者でもない、今は魔族でもないな" },
  { name: "魔族ヴァルフ", text: "なら何なんだよ！折角俺が集めた魔物を全部……一瞬で……殺しやがって……" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "これから殺す相手に名乗る必要があるかは疑問だが、まぁ良い、冥土の土産だ。我が名は魔王クロセル！この世界最強の存在だ！" },
  { name: "魔族ヴァルフ", text: "なっ……魔王だと！？" },
  { text: "人々は息を呑んだ。彼らは知らずとして魔王を街に泊めていた事になるのだから。" },
  { name: "街の人々", text: "魔王がどうして人間の味方をするんだよ！" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "勘違いをするな、我は人間の味方ではない、貴様の行動に腹が立ったから、粛清してやったまでだ、それに｜殺戮《さつりく》は暫く御無沙汰だったしな" },
  { name: "魔族ヴァルフ", text: "なっ……わ……分かった、魔王様、俺は魔族です、忠実な貴方の部下です、どんな命令でも聞きますから、助けて下さい" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "では命令だ……我の為に、死ね" },
  { se: "slash" },
  { text: "魔王クロセルは片手でヴァルフの頭を握り潰す。辺りで悲鳴が上がる。だが――人々は彼女を英雄視する事が出来なかった。その圧倒的な力に対して、恐怖する事しか出来なかったのだ。" },
  { chara: { slot: "center", id: "crocell", expr: "sad" } },
  { name: "クロセル", who: "crocell", expr: "angry", text: "……何故だ？我は貴様らを……" },
  { name: "街の人々", text: "この人殺し！悪魔！" },
  { text: "彼女がこんな行動に至った理由。それは破壊衝動を発散する事も一つではある。だが、彼女の行動理念の根本は、人を助ける為という物に起因する。彼女は人類の味方ではないが、敵でも無いのだ。" },
  { text: "勇敢な一人の男が、クロセルの胸にナイフを刺す。こんな攻撃、致命傷どころか痛みすら感じない。筈なのに……何故か、クロセルの胸は強い痛みに襲われていた。クロセルは胸元を押さえながら、地面に膝をつく。" },
  { name: "街の人々", text: "やっ……やったぞ！魔王が苦しんでいる！良いぞ！魔王を殺せ！そして俺達が英雄になるんだ！" },
  { text: "街の人々はクロセルに向けて、石を投げ付けた。鈍器で頭を殴り付けた。刃物で身体を傷付けた。その度に、クロセルはただ強く胸を押さえ、俯きながら肩を震わせていた。" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "うぐっ……何故だ……我はただ……" },
  { text: "俯く彼女のその瞳に、涙が浮かんでいた事など、誰も知らない。" },
  { text: "やがて日が暮れる。魔王がこんな事で死ぬ筈が無い。聖なる武器以外で、魔王の身体に有効打を刻む事は出来ない。だから、私は殺されずに四肢を拘束され、街の中央で晒し者にされていた。" },
  { chara: { slot: "center", id: "lutz", expr: "sad" } },
  { name: "ルツ", who: "lutz", expr: "sad", text: "どうして……こんなにも胸が苦しいんだろう" },
  { text: "人里に来たのは、人を助ける為だ。魔王が居なくても魔族は魔物を従え、人々を傷付ける。私はそれを止める為に、人里に来ていたのだ。事実、私のお陰で、この街は救われたのだ。なのに人々は私を恐れた。英雄として称えるのではなく、悪魔として蔑んだ。" },
  { text: "悲しい。悔しい。苦しい。私は何の為に、今まで人を傷付けまいとしてきたのだろう。私が悪い事をしたのだろうか。何かが間違っていたのだろうか。" },
  { name: "ルツ", who: "lutz", expr: "sad", text: "そうだよ……私が救ったんだ……なのに……あんな人達……私が苦しんでまで救う価値のある存在なのかな" },
  { text: "何か、心の奥底でぷっつりと糸が切れる感覚がした。――人類など、滅んでしまえば良いんだ。" },
  { name: "ルツ", who: "lutz", expr: "smile", text: "私の理解者は一人だけ、一人だけでいい……それ以外の存在など必要ない" },
  { bgm: "dark2" },
  { fx: "red" },
  { text: "街は一夜にして消失した。残ったのは、まっさらになった土地と彼女だけ。子供も女も例外なく殺した。家屋も墓も｜躊躇《ためら》う事なく消し去った。" },
  { name: "ルツ", who: "lutz", expr: "sad", text: "もう……苦しくない" },
  { fx: "clear-red" },
  { hide: "all" },
  { bg: "maou_castle" },
  { text: "そして、彼女は幾つもの街を消し去っていった。気が付けば、魔王クロセルの名は世界中で知られるようになっていた。やがて魔王城に、黄金の鎧に聖剣を持った白髪の老人――祝福の勇者キュリオスと、先代魔王の息子スカルフが現れる。" },
  { chara: { slot: "center", id: "crocell", expr: "angry" } },
  { name: "勇者キュリオス", text: "悪逆非道な魔王め！俺が貴様を成敗してやる！" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "貴様は……祝福の勇者キュリオス、と……" },
  { name: "魔族スカルフ", text: "やぁルツ、久々ですね" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "スカルフ……貴様は魔族なのに我に逆らうのか？" },
  { name: "魔族スカルフ", text: "勘違いしないでください、僕は勇者を此処まで連れてきただけです、戦いには加わらない、それに僕に命令して戦わせたとしても、大した戦力にはならないですよ" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "そうだな、お前は使えない、それにしても勇者、随分と皺が増えたな、それに仲間はどうしたんだ？" },
  { name: "勇者キュリオス", text: "あんな奴らはどうでも良い、それに見た目は老いたかもしれないが、俺は祝福の勇者だ……舐めるなよ！" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "いずれは祝福に対抗する手段を講じねばな……" },
  { name: "魔族スカルフ", text: "そんな事をしても無駄だよ、祝福は才能、才能を無効化する手段など存在しない" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "それはどうだろう、研究次第では何らかの手段が見付かるかもしれないぞ" },
  { name: "勇者キュリオス", text: "無駄だと言ってるんだ！何せお前は此処で死ぬのだからな！" },
  { name: "勇者キュリオス", text: "ふはははは！この広い空間だと君のお得意の召喚魔術は使えないだろう？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "我は召喚魔術師では無いのだがな" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "まぁ確かに、あの魔術が気に入ってるのは事実だがな、｜魔術回路改竄《カスタマイズ》……｜略式詠唱展開《ファストキャスト》……――属性魔術 ｜氷剣《アイシクルソード》……｜連続詠唱《コネクト》……――属性魔術 ｜海王覇気《インペリアルオーラ》！" },
  { se: "magic" },
  { text: "私は氷の剣を生み出し、強化魔術で身体能力を底上げする。これは魔術9の才能に加え魔王の権能である水魔術の複合、ダイヤモンド並みの硬度を持つ氷の刃だ。強化魔術を使っている間は、青い光を纏う。" },
  { name: "勇者キュリオス", text: "くっ……召喚魔術以外の魔術も使うのか！？魔術師の癖に剣を使うなど！" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "魔術は隙が大きい。それに遠距離攻撃は当てるのが難しい。その点近接攻撃は優秀だ、間合いに入れば確実に当てる事が出来る" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "だが……一撃が重い……まるで老人の攻撃とは思えないな" },
  { name: "勇者キュリオス", text: "俺は老人じゃない！まだ78歳だ！" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "人間で言えば既に寿命だろう、祝福で生き永らえているのか、憐れだな" },
  { name: "勇者キュリオス", text: "うるさい！俺は選ばれし大英雄！不滅の祝福の勇者だ！" },
  { text: "魔王が魔族最強ならば、祝福の勇者は人類最強の存在。9を超えた才能指数は+で表記される。才能指数の差は絶対だが、+で表記される数字の差は覆る可能性のある僅かな差だ。私も勇者も才能指数は9+、故に実力差は僅か。だが、それが確実に勝敗を分ける。私は、勇者の攻撃を氷の剣で防ぐ事しか出来なかった。" },
  { text: "氷剣は不可視の刃である。だがそれが有利に働くのは、攻勢時のみ。劣勢の今は、そのアドバンテージも殆ど働いていない。" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "――属性魔術 ｜水元素集約《ハイドロフォーカス》・｜爆破《エクスプロージョン》！" },
  { se: "explosion" },
  { fx: "red" },
  { text: "勇者の背後で複合魔術の爆発を起こす。自分も巻き込まれるが、この魔王の肉体は爆発程度ではびくともしない。祝福があると言えど、勇者も人間の身体である以上、無事ではいられない……筈だった。" },
  { fx: "clear-red" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "なっ……嘘……" },
  { text: "勇者は無傷で立っていた。そして、爆発の勢いを物ともせず、私の元へと踏み込み、聖剣を振りかぶる。" },
  { name: "勇者キュリオス", text: "唸れ聖剣……エックストラカリバー！！！" },
  { se: "slash" },
  { fx: "flash" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "っうああああああっ！" },
  { text: "聖剣による傷は……聖なる力は、魔王の身体を侵食していく。肉体の修復が行われない。致命傷だ。私は……勇者に負けた、殺されたのだ。" },
  { name: "魔族スカルフ", text: "無様ですね、ルツ。見て分かりませんか？魔王の力があるべき場所に帰る、それだけですよ" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "スカルフ……貴様……何を……" },
  { name: "魔族スカルフ", text: "本来、父上の力を継承するのは僕である筈だった、その力はルツ、貴方の物ではない" },
  { chara: { slot: "center", id: "lutz", expr: "sad" } },
  { name: "ルツ", who: "lutz", expr: "sad", text: "うん……その通り……この力は私の物じゃない、私は魔王の器ではなかった……" },
  { name: "魔族スカルフ", text: "まぁ安心して下さい、貴女の事は精々有効活用させて貰いますよ" },
  { text: "スカルフが、倒れた彼女の血を飲み干し、魔王の力は次の魔王へと継承された。冷たくなっていく身体。死の直前、｜刹那《せつな》の時で、彼女は再び心を取り戻す。" },
  { bgm: "sad" },
  { chara: { slot: "center", id: "lutz", expr: "sad" } },
  { name: "ルツ", who: "lutz", expr: "sad", text: "あぁ……私はなんであんな事を……魔王様……ごめん……なさい……" },
  { text: "今まで自分がしてきた事を思い出して、後悔する。私は人殺しであり、極悪人だ。貴方の守りたかった、人間を、傷付けてしまった。" },
  { text: "暴走していた私の事を、勇者キュリオスが止めてくれたのだ。あの男は私の主人を殺した男ではない。あの方を殺したのは私だ。そしてそんな悪人である私を裁いてくれた。あれこそが英雄だ、真の大英雄だ。" },
  { text: "でも……私のような悪人でも……まだ懲りずにこんな事を思ってしまう。" },
  { name: "ルツ", who: "lutz", expr: "sad", text: "皆に嫌われる人生より……私も……勇者みたいな英雄に……誰かに愛される人生を……送りたかった……な……" },
  { text: "彼女の瞳から一粒の涙が溢れ、同時にその肉体は消失した。そこで、死を迎えた彼女の意識は、ぷっつりと途切れた。" },
  { text: "その先の記憶は曖昧だ。本来、水晶球になった魔王は意識を保てるらしいが、我は例外で、殺された直後から記憶が朧げだった。" },
  { text: "魔王の死体は水晶球になる。私が死んだ後、その死体はスカルフ――後の魔王フォーカスによって回収され、聖杖ガンバルミンを｜依り代《よりしろ》に、｜魔杖《まじょう》クロセルとして生まれ変わった。" },
  { text: "魔杖クロセルは魔王フォーカスの武器としてその力を発揮したが、後にアランの民と呼ばれる一族により奪われる。その事を怒った魔王フォーカスはアランの民の殲滅を決意するが、結果として彼らは滅びなかった。" },
  { text: "アランの民は魔杖クロセルを聖域と呼ばれる迷宮に封印した。……ヤマトとの出会いに繋がる、全てが今、明かされた。" },
  { fade: "out" },
  { hide: "all" },
  { pov: null },
  { bg: "sen_mansion" },
  { fade: "in" },
  { comment: "回想明け — 現在" },
  { bgm: "heartwarm" },
  { chara: [
    { slot: "left",   id: "akatsuki", expr: "blush" },
    { slot: "center", id: "crocell",  expr: "normal" },
    { slot: "right",  id: "yamato",   expr: "normal" },
  ] },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "というのが、我が魔王になってからの話だ。我の意識がはっきりとしたのは、聖域に封印された後からだった。もしご主人が現れなければ、我は永久に封印されたままだったかもしれない" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ、なんか……色々と納得した" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "クロセルさんも……今まで大変だったんですね……" },
  { text: "何故か涙を流しながら、アカツキがクロセルの事を抱き締めていた。嫌ではないが……複雑だ。出来る事ならば、ヤマトに抱き締めて欲しいのだが。……いや、そもそもヤマトが私にそんな事をする筈がないか。" },
  { text: "大罪人である私でも、主人の為に力を発揮する事が出来る事が、役に立てる事が、ただひたすらに……嬉しかったんだ。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "俺の事は抱き締めてくれないのか？" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "ヤマトさんの過去も確かに壮絶でしたけど……っていや、私に抱き締めて欲しいんですか？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "冗談だ、自分で言った通り、そこまで気にしてる訳でもないからな、慰めなど不要だ" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ふっ、強がりおって……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "あ？なんだとクロセル" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "本当は我に慰めて欲しい癖に" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "な訳ねぇだろ！それと心を読むなと……" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "おや？我は心を読んだ訳ではないのだが……図星なのか？" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "なっ……てめぇ！" },
  { text: "ヤマトが私の頭に｜拳骨《げんこつ》を飛ばし、弾かれる。まぁ、これで良いのだ。私とヤマトの距離感は、これで良い。これ以上近付く必要も、遠ざかる必要もない。言葉にしなくても、行動で示さなくとも、私とヤマトは分かりあえている。そう信じているからだ。" },
  { text: "石を投げられ、心を折られ、｜災厄《さいやく》となって果てた七百年前の私。あの哀れな少女が、今はこうして、誰かに頭を小突かれて笑っている。" },
  { wait: 600 },
  { text: "私の守りたい物。大切にする価値のある物は。――間違いなく、此処にある。" },

  // ---------------------------------------------------
  // Scene 12: zeno_death — メイドに気を付けて (EP100)
  // ---------------------------------------------------
  { label: "zeno_death" },
  { fade: "out" },
  { hide: "all" },
  { bg: "imperial_capital" },
  { fade: "in" },
  { comment: "EP100: 奇妙な夢 — 万能のヤマト" },
  { bgm: "mystery2" },
  { text: "俺は夢を見ていた。場所は、何処だろう。見たことのない景色だ。そして、俺が俺の前に立っている。眠っているせいで思考が纏まらない。当たり前の事実を認識する事しか出来ない。" },
  { name: "夢の中の瀬野", text: "ヤマト、やり過ぎだよ……" },
  { name: "夢の中の俺", text: "あれ……俺また何かやっちゃったか？" },
  { text: "瀬野が俺に何かを言って、俺が何かを呟く。辺りには人混みが出来ている。何かを指差している。そこには、肉塊があった。" },
  { name: "街の人", text: "あの｜上級悪魔《デーモン》を一瞬で……なんて強さだ……あの冒険者、なんて言うんだ？" },
  { text: "どうやら俺は噂されているらしい。当の本人である俺は、バツが悪そうに頭を掻きながら、周囲の人達に片手を翳し、何かを呟く。" },
  { name: "夢の中の俺", text: "記憶操作" },
  { text: "すると、周囲の人々は突然ヤマトから視線を反らし、その場に居た何の変哲もない一人の男を指差して告げる。" },
  { name: "街の人", text: "お前が上級悪魔を倒した冒険者か！凄いじゃないか！" },
  { name: "男", text: "僕が……上級悪魔を倒しました" },
  { name: "街の人", text: "うおおおお！英雄だ！こんな冒険者が街に居たなんて知らなかった！" },
  { text: "さっきよりも盛大に騒いでいる。何の変哲もない男を指差しながらだ。明らかにおかしな光景だ。何がおかしいのかは分からない。" },
  { name: "夢の中の瀬野", text: "やっぱりヤマトは凄いね！考えつく限りのどんな事でも出来てしまうなんて" },
  { name: "夢の中の俺", text: "あぁ、そうだな、帝国は強い奴が多いと聞いて来たが……この様子だと｜魔窟《まくつ》って迷宮も大した事は無さそうだな" },
  { name: "夢の中の瀬野", text: "なら次は何処を目指すの？" },
  { name: "夢の中の俺", text: "この世界で一番強い奴が居る所だ、と言っても魔王は居ないらしいからな、その次に強い奴だ" },
  { name: "夢の中の瀬野", text: "となると、祝福の勇者とか皇帝かなぁ……" },
  { name: "夢の中の俺", text: "そんな雑魚には興味ない、この空虚な感覚を満たせる強者……そうだな……例えば……" },
  { text: "俺がそう呟いた所で、夢は途切れる。" },
  { text: "夢が途切れても、意識がある。おかしな話だ、まるで起きているかのよう。" },
  { fade: "out" },
  { bg: "sen_mansion_night" },
  { fade: "in" },
  { text: "「……トントン」" },
  { chara: [
    { slot: "center", id: "yamato",  expr: "normal" },
    { slot: "right",  id: "crocell", expr: "normal" },
  ] },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ん……ご主人、起きたのか" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、ノックの音が聞こえてな。こんな時間に誰だ？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "寝ていても聞こえるとは耳が良いのだな" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "いや、丁度偶然目が覚めたんだ。まぁ良い、俺が出る" },
  { text: "なんだろう、嫌な予感がする。さっき見た不思議な夢と関係があるのだろうか。俺はベッドから降りると、部屋の扉へと近付き、開く。" },
  { se: "heartbeat" },
  { bgm: null },
  { fx: "red" },
  { text: "扉を開いた先、そこには――倒れ伏した瀬野の姿と、血溜まりがあった。" },
  { chara: { slot: "left", id: "zeno", expr: "scared" } },
  { chara: { slot: "center", id: "yamato", expr: "surprised" } },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "お前は……瀬野！？" },
  { name: "瀬野", who: "zeno", expr: "sad", text: "ごほっ……ヤマト……僕の話を……聞いて……くれ……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "クロセル！回復魔術を！" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "どうしたご主人、何事だ！？" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "瀬野が怪我をしている、酷い出血だ……" },
  { name: "瀬野", who: "zeno", expr: "serious", text: "ヤマト……聞いて……くれ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "喋るな！傷が広がるだろ！" },
  { chara: { slot: "right", id: "crocell", expr: "sad" } },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ご主人……傷が塞がらない、この傷は……聖なる武器による物だ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "なら包帯を作れ！それで止血する" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "無駄だ、魔族に対する聖なる傷は、自然治癒を防ぐ、止血をしても、傷は塞がらない……それにゼノはもう……" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "なんだよクロセル……なんでそんな悲しそうな顔をするんだよ……" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "ご主人、ゼノの話を聞け、手遅れになる前に！" },
  { chara: { slot: "center", id: "yamato", expr: "sad" } },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "嘘……だろ……？" },
  { text: "瀬野が、助からない？瀬野が、死ぬ？折角魔王の元から救い出したのに、折角こうして再会したのに。こんなにも早い別れなんて、そんな馬鹿な話があるか？" },
  { name: "瀬野", who: "zeno", expr: "sad", text: "ャマト……君は……記憶を失って……いる……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "おい瀬野！こんな時に何言ってんだよ！" },
  { name: "瀬野", who: "zeno", expr: "sad", text: "メイ……ドに……気を……付け……て……ごほっ……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "どういう事だ？お前はメイドにやられたのか！？" },
  { name: "瀬野", who: "zeno", expr: "sad", text: "ごめん……ャマト……僕……また失敗……しちゃっ……た……" },
  { text: "瀬野は困ったように小さく笑うと、そのまま目を閉じる。" },
  { fx: "shake" },
  { wait: 800 },
  { hide: "left" },
  { bgm: "sad" },
  { text: "嘘だ。嘘だ嘘だ嘘だ。瀬野が死ぬ筈がない。だって昼まで、あんなに元気だったじゃないか。" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "どうやら時間操作で自分の肉体の時間を止め、空間操作で此処まで来たようだな……血痕は辿れない" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "クロセル！何とかしろ！お前は最強の｜魔杖《まじょう》なんだろ！" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "死者を蘇らせる事は出来ない！それより今は瀬野の言葉だ" },
  { chara: { slot: "center", id: "yamato", expr: "sad" } },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "取り敢えず手遅れにならない内に……瀬野を……" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "駄目だ！今ご主人が\"あの力\"を使えば、無防備な隙を突かれる可能性がある、我もご主人を守りきれるとは限らない！" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そうか……なら先に敵をなんとかするぞ" },
  { text: "俺は瀬野を抱き上げると、ベッドに運び、横に寝かせる。既に息はしていない。瀬野は死んだ。その事実が俺の心を強く揺さぶる。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "落ち着け……俺、取り敢えずクロセル、犯人を探すぞ" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ご主人、動揺するのも分かるが、こんな時だからこそ冷静さを欠かしてはいけない" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、その通りだ……俺はもう大丈夫、行くぞ" },
  { fx: "clear-red" },
  { chara: { slot: "right", id: "crocell", expr: "normal" } },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ご主人、ゼノの言葉だ。ご主人は記憶を失っている、メイドに気を付けろ、そう言っていただろう？" },
  { text: "メイド……この屋敷でメイドと言えばセン公爵の従者、エスクだ。寝ている瀬野を襲う事なら非力なエスクにも可能だ。だが瀬野が俺に『メイドに気を付けて』と言った理由があるとすれば、犯人は俺の命も狙っていると考えられる。まずは全員を起こして回るぞ。" },
  { text: "瀬野が死に際に警告を残せたという事は、即死ではなかったという事だ。犯人にとっては失敗だが、お陰で手掛かりが残った。" },
  { bgm: "tension" },
  { hide: "all" },
  { chara: [
    { slot: "left",   id: "akatsuki", expr: "surprised" },
    { slot: "right",  id: "crocell",  expr: "normal" },
  ] },
  { name: "ヤマト", text: "アカツキ！開けるぞ！無事か！" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "ん……ふあぁ……何事ですか……ヤマトさん……クロセルさんまで……" },
  { name: "ヤマト", text: "悪い、今は話す時間も惜しい、付いてきてくれ" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "……緊急事態ですね、分かりました" },
  { text: "流石は直感の才能だ。こういう時の勘の良さは助かる。" },
  { text: "そして、俺達はアカツキを連れ、ティアの部屋に足を踏み入れる。が……" },
  { name: "ヤマト", text: "ティア……？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "くっ、手遅れだったか" },
  { name: "ヤマト", text: "いやクロセル……冗談だろ？まさかティアまで？" },
  { text: "ベッドにティアの姿は無かった。だが、争った様子や血痕も無い。ただ部屋に居ないだけ、と見るのが妥当な気がする。勿論、連れ去られた可能性もある。" },
  { text: "だが、祝福がある以上、殺される事は無いだろう。それだけが唯一の救いだ。俺達は次にエルの部屋、勇者の部屋を順に訪れる。だが、どちらももぬけの殻であった。" },
  { name: "ヤマト", text: "どういう事だ？俺達は間に合わなかったのか？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "分からん……" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "私とヤマトさん、クロセルさんの三人以外、ティア様、エルさん、ニコラスさんの三人が行方不明と……そう言えば瀬野さんの部屋には行かないんですか？" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "あいつは殺された" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "殺され……えっ……？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "詳しく説明してる時間は無い、今は事実だけを受け入れてくれ" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "わ……分かりました、次はどうするんですか？三人を探すんですか？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "いや、セン公爵の所に行く、そこに瀬野を殺した奴が居るかもしれない" },
  { text: "それに、彼女の主人であるセン公爵は、何かを知っているかもしれない。或いは……セン公爵が首謀者、という可能性もある。何にしろ、行かなければ何も分からない。セン公爵は深夜にも関わらず起きていた。これほど怪しい事は無い。" },
  { name: "セン公爵", text: "おや……ノックも無しに部屋に入ってくるとは……礼儀知らずにも程があると思うが" },
  { name: "ヤマト", text: "悪いが今は緊急事態だ、お前……エスクが何をしたか知っているか？" },
  { name: "セン公爵", text: "緊急事態、そうか……まぁ良い、私は寛大だからね、さて……エスクか、何の事だい？私の従者が何か粗々をしたかな？" },
  { name: "ヤマト", text: "クロセル、どうだ？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "嘘は言っていないな" },
  { name: "ヤマト", text: "そうか、なら貴族男、説明するぞ、お前の従者には俺の仲間を殺し、攫った疑いがある、居場所に心当たりはあるか？" },
  { name: "セン公爵", text: "ふむ、エスクがそんな事をするとは思えないが……勿論、疑うのは自由だ、だが残念ながら私は協力出来ないな、私は彼女の居場所を知らない、分かる事と言えば……彼女は夜伽の命令が無い限り、昼夜問わず働いているという事ぐらいだろうか" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "嘘は言っていない" },
  { name: "ヤマト", text: "そうか、悪かったな、貴族男、お前も従者に殺されないよう気を付けろよ" },
  { name: "セン公爵", text: "必要ないよ、私がエスクに殺される事など、万が一にもありえないからね" },
  { text: "どうやら今回の一件はエスクが独断で決行した事のようだ。セン公爵は関係無い。それが分かれば長居する理由も無い。" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "夜分遅くに失礼しました、それに恩人にこんな無礼を働いてしまって" },
  { name: "セン公爵", text: "構わないよ、緊急事態なのだろう？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "クロセル、屋敷全体に空間探知魔術を掛けて、俺達以外の人間の反応を探せるか" },
  { chara: { slot: "right", id: "crocell", expr: "serious" } },
  { name: "クロセル", who: "crocell", expr: "serious", text: "その手があったか、任せろ。魔術回路改竄《カスタマイズ》……" },
  { text: "クロセルが空中に手を突き出して詠唱する。そして僅かの時が経ったかと思えば、クロセルは大きく目を見開き、叫んだ。" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "見付けた！三階のテラスに生命反応だ！" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "数は？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "二人だ、恐らくエスクと誰かだろう" },
  { text: "という事は、逆に言えばこの屋敷の中に残りの二人は居ないという事。既に殺された為に生命反応が無いのか、単純に屋敷の中に居ないだけか……分からないが、一人だけでも無事な事が分かっただけ収穫だ。" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "急ぎましょう、手遅れになる前に" },
  { name: "ヤマト", text: "あぁ、そうだな" },
  { fade: "out" },
  { hide: "all" },
  { bg: "sen_terrace_night" },
  { fade: "in" },
  { text: "階段を駆け上がり、街を一望出来るテラスへと向かう。窓を見ると、確かにテラスに、二人の人影が見える。俺は誰よりも先にテラスへと近付き、両手でドアを開け放つ。涼しい夜風が全身を包む。" },
  { text: "白いカーテンが揺らめき、月明かりがテラスを映し出す。そして、俺は、そこで行われていた光景を目撃した。" },
  { chara: { slot: "left", id: "esk", expr: "serious" } },
  { text: "一人は、見たことのない長銃を構えるエスク。" },
  { text: "そして、その銃口の先には……" },
  { bgm: null },
  { wait: 800 },
  { chara: { slot: "right", id: "el", expr: "blank" } },
  { fx: "shake" },
  { text: "――エルが立っていた。" },
  { chara: { slot: "center", id: "yamato", expr: "angry" } },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "エスク……てめぇ……" },

  /* =====================================================
     ============ パート2: EP101〜113 (後半) ==============
     ===================================================== */

  // ---------------------------------------------------
  // Scene 13: el_betrayal — 決別 (EP101) ◆B08
  // ---------------------------------------------------
  { label: "el_betrayal" },
  { comment: "EP101: 月夜のテラス — エルの裏切り" },
  { chara: { slot: "center", id: "yamato", expr: "angry" } },
  { name: "クロセル", text: "ご主人、どうした、何があったのだ" },
  { name: "アカツキ", text: "エスクさん、それに……エルさんですか" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "エスク……今直ぐその銃を下ろせ。エルの事を撃ったら、俺はお前を殺すぞ" },
  { name: "エスク", who: "esk", expr: "serious", text: "それは出来ません……？何故ですか？私が何か粗々を致しましたでしょうか？" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "お前は俺の仲間を傷付けた" },
  { name: "エスク", who: "esk", expr: "smile", text: "どういう事ですか？" },
  { text: "エスクは俺の言っている事が理解出来ないとばかりに、疑問符を浮かべる。怒りが全身を支配する。" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ご主人……違うぞ。エルの手元を見るのだ" },
  { text: "言われた通り、視線をエスクからエルへと移す。そして……その手には。" },
  { fx: "flash" },
  { text: "――聖剣フルティンが握られていた。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "なっ、それは……" },
  { text: "聖剣フルティンの切っ先からは、血が滴っている。つまり、あの剣は誰かを斬る事に使われたという事。エスクに外傷はない。つまり……" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "信じられない話だが、恐らく……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "そんな……嘘だろ……？" },
  { chara: { slot: "center", id: "yamato", expr: "surprised" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "エル、お前が瀬野を殺したのか？" },
  { name: "エル", who: "el", expr: "sad", text: "っ……" },
  { name: "エスク", who: "esk", expr: "normal", text: "理解して頂けたようで何よりです、私はこの屋敷に仕える者として、大切な客人を殺した人間を放置する訳にはいきません" },
  { text: "そうだ、確かに瀬野は『メイドに気を付けて』と言ったのだ。メイドはエスクだけではない、エルも該当する。" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "答えろエル！お前が瀬野を殺したのか！？" },
  { chara: { slot: "right", id: "el", expr: "smile" } },
  { bgm: "dark" },
  { name: "エル", who: "el", expr: "troubled", text: "ふぅ……はぁ……あの男、死ぬ間際に余計な事をしたんだね、油断した。此処まで予定が狂うとは思わなかったよ" },
  { text: "その発言は、殺人を肯定した事に他ならなかった。" },
  { name: "エスク", who: "esk", expr: "serious", text: "この殺人鬼を射殺します、構いませんね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "待て、殺す前に話をしたい" },
  { name: "エスク", who: "esk", expr: "smile", text: "……分かりました、ですが下手な動きをすれば即射殺します" },
  { text: "エルが瀬野を殺した。どうやらそれは事実らしい。だが、分からない事が多すぎる。何故エルは瀬野を殺したのか。勇者二人は何処に行ったのか。あまりの状況に理解が追いつかない。" },
  { chara: { slot: "center", id: "yamato", expr: "surprised" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "エル、お前は何故瀬野を殺したんだ？" },
  { name: "エル", who: "el", expr: "sad", text: "｜邪魔《じゃま》だったからだよ、ヤマト様に余計な事を話そうとしたから殺した" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "つまり……口封じか" },
  { name: "エル", who: "el", expr: "normal", text: "そうなるかな、でもヤマト様、もう知っちゃったんでしょ？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "俺が記憶を失ってる、って話か、その話が、何故お前に都合が悪い" },
  { name: "エル", who: "el", expr: "smile", text: "ヤマト様に記憶を取り戻されると困るんだ、もし取り戻してしまえば、私の旅が終わってしまうから。でも……そんな努力もこれで水の泡だよ、苦労してあの男を殺したのに、もう全部滅茶苦茶だ" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "意味分かんねぇよ！俺が記憶を失ってるって話も！お前が瀬野を殺したって話も！お前の言ってる事も！何一つ理解できねぇ！エル……俺達とお前は……仲間だったんじゃないのかよ！" },
  { fx: "shake" },
  { chara: { slot: "right", id: "el", expr: "smile" } },
  { name: "エル", who: "el", expr: "smile", text: "私は愉快な物語が好きなんだ、そしてそれを自分の身で体験する事も好き、ヤマト様との旅は、かけがえのない時間だった、まるで私も物語の登場人物になれたみたいで、楽しかったんだ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "ならどうして！" },
  { chara: { slot: "right", id: "el", expr: "normal" } },
  { name: "エル", who: "el", expr: "cold_smile", text: "言ったでしょ？ヤマト様が記憶を取り戻せば、この楽しい旅は終わってしまう、だから私はそれを阻止しようとして、失敗した、それだけの話だよ" },
  { text: "自分の保身の為に、瀬野を殺した。とんでもなく利己的な理由だ。到底正当化出来るような物ではない。" },
  { name: "エル", who: "el", expr: "cold_smile", text: "でも、この旅ももう終わりだ、だから私は、在るべき場所に戻る事にするよ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "どういう事だよ……" },
  { text: "エルは月を見上げ、聖剣フルティンを天高く放り投げる。そして、テラスの塀へと一歩踏み出す。無論、エスクがそれを黙って見ている筈は無い。エスクは銃口をエルに向けたまま、容赦なく引き金を引いた。" },
  { name: "エスク", who: "esk", expr: "serious", text: "……発射" },
  { name: "エル", who: "el", expr: "cold_smile", text: "ラプラス" },
  { text: "発砲と同時に、エルがそう呟く。瞬間、暗闇の中から一人の少女が飛び出してきたかと思えば、少女は宙を舞う聖剣フルティンを掴み、そのまま流れるような動作でエスクの放った弾丸を斬り落とす。" },
  { fx: "flash" },
  { chara: { slot: "left", id: "laplace", expr: "laugh" } },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "チッ……エルてめぇ、魔剣と契約したのか" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "あはははは！お久しぶりですねヤマト様！どうですか？大切な仲間に裏切られる感覚は、ゾクゾクするでしょう？気持ち良いでしょう！？" },
  { name: "エル", who: "el", expr: "cold_smile", text: "この｜肉体《ボディー》に魔術の才能があって良かったよ、お陰で魔剣に燃料を供給出来る" },
  { name: "ラプラス", who: "laplace", expr: "blank", text: "あー言っときますけどボク、かなり燃費悪いですから、ご主人様程度の魔力じゃすぐに枯渇しますよ？" },
  { name: "エル", who: "el", expr: "sad", text: "その時は寿命を持っていけばいい、どうせ使い捨ての身体なんだから" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "あはっ、それもそうですね" },
  { chara: { slot: "right", id: "el", expr: "cold_smile" } },
  { name: "エル", who: "el", expr: "cold_smile", text: "じゃあヤマト様、さようなら" },
  { text: "エルはいつもと同じ、｜屈託《くったく》のない笑顔を浮かべると、そのまま塀を乗り越え、テラスから飛び降りた。" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "クロセル、エルを追いかけるぞ、受け止めろ" },
  { hide: "all" },
  { bg: "ariel_town_night" },
  { comment: "夜の街での追跡戦" },
  { bgm: "battle" },
  { text: "続いて悪魔も、ニヤニヤと笑いながら、塀に腰掛け、背中から飛び降りる。" },
  { name: "エスク", text: "くっ……仕留め損ないましたか、私は此処から追撃します、追うのならば急ぐ事を推奨します" },
  { text: "テラスから夜の空へと躍り出る。空など飛べない。俺の身体は重力に従い、自由落下する。" },
  { name: "ヤマト", text: "ごぼっ……" },
  { text: "クロセルの水のクッションが俺の身体を受け止める。俺が水から出ると同時に、隣にクロセルが降り立つ。" },
  { name: "ヤマト", text: "お前はあの高さから落ちても平気なのか" },
  { name: "クロセル", text: "うむ、我の身体は人間より丈夫だからな" },
  { name: "アカツキ", text: "ごほっごほっ……水で受け止めるならそう言って下さいよ、驚いて水を飲みました……おえっ……" },
  { name: "ヤマト", text: "エルは何処だ" },
  { name: "クロセル", text: "居るぞ！あっちだ！" },
  { name: "ヤマト", text: "クロセル、強化魔術だ" },
  { text: "クロセルが俺とアカツキに強化魔術を掛ける。実は強化魔術を受けるのは初体験だ。身体が青く発光している。" },
  { name: "ヤマト", text: "なんだこれ……動かす感覚はいつも通りなのにこんな速く動けるのかよ……気持ち悪い" },
  { text: "少し早歩きをしたつもりが全力疾走レベル。試しに全力で走ると、気が付けば家屋の外壁に激突していた。" },
  { name: "ヤマト", text: "いってぇ……強化魔術で戦ってる奴はどういう頭をしてるんだ……理解できねぇ……" },
  { name: "クロセル", text: "こればっかりは慣れだな、急ぐぞ" },
  { text: "力の出力を五割程度に抑えてやっと制御できる。こうして、俺達は身体強化に物を言わせて、あっという間にエルに追い付く。" },
  { name: "エル", text: "やはりこの肉体の身体能力では逃げ切れないか……ラプラス、少し時間を稼いでくれるかな" },
  { name: "ラプラス", text: "やれやれ、悪魔使いが荒いですね、分かりましたよ、ご主人様" },
  { chara: [
    { slot: "left",   id: "laplace", expr: "laugh" },
    { slot: "center", id: "yamato",  expr: "serious" },
    { slot: "right",  id: "crocell", expr: "serious" },
  ] },
  { text: "悪魔は聖剣を構え、エルの前に出て、俺達の進路を塞ぐ。悪魔が剣を振る度、床に弾丸の残骸が落ちる。これはエスクによる狙撃か、だが未来を視る力を持つ悪魔を撃ち抜くには至っていないようだ。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そう言えば……あの時の変異種を撃ち抜いたのは……エスクだったのか？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "恐らくそうだろうな、隠蔽の才能のせいで分からないが、恐らく遠くを見る才能と射撃術の才能を持っているのだろう" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "だとしたらあいつには感謝しないとな……疑った事も謝らないと……" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "此処は我に任せろ、ご主人は武器を持ってきていないだろう" },
  { text: "クロセルは詠唱し、その手に氷の剣を持つ。そして、一瞬にして悪魔に肉薄し、攻撃を開始する。" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "あー無駄ですよー｜魔杖《まじょう》クロセル、貴女は前に一度、未来視の才能に負けたのを忘れたんですか？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "どれだけ未来が見えていようと、肉体の限界は超えられない" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "まぁ確かにそうなんですけど、ボク結構強いんで、狙撃と貴女の攻撃を受け止める事くらい簡単なんですよねー" },
  { text: "事実、悪魔はクロセルと剣を交えながら、飛んでくる銃の弾丸を的確に斬り落としている。その表情には、余裕すら見えるようであった。" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "才能指数9+か……剣術、魔術、未来視の三つの才能が同時に発揮されている……" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "お、良く分かりますねぇ……流石は｜魔杖《まじょう》クロセル" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ご主人、前言撤回だ、少し我を手伝え。｜魔術回路改竄《カスタマイズ》……｜略式詠唱展開《ファストキャスト》……――属性魔術 ｜氷槍《アイシクルランス》" },
  { text: "クロセルが氷の槍を生み出し、俺の方に放り投げる。俺の習得しているCQCは、棒状の物であれば何でも武器にする事が出来る。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "冷たっ！？" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "氷なのだから当然だろう" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "いや別の素材にしろよ！こんな物使えるか！" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "うるさいぞ……男なのだからそれぐらい我慢するのだ" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "アカツキは……" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "身体強化しても私は近接戦闘の経験が無いですから……恐らく足手まといかと" },
  { text: "乱戦になるとアカツキの魔術も誤射をする可能性がある。此処は俺とクロセル、そしてエスクの三人でどうにかするしか無いだろう。" },
  { name: "ラプラス", who: "laplace", expr: "mad", text: "三対一とは｜卑怯《ひきょう》ですねぇ……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "悪魔のお前がそれを言うか" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ご主人、いけるか？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、選手交代だ" },
  { text: "少し氷の槍を握っていると、手の感覚が消えた。クロセルが飛び退き、それと入れ替わる形で俺が前に出る。ディザビリティがある為、攻撃は加えられないが、ラプラスの剣を妨害する事は出来る。" },
  { text: "俺の加勢で、悪魔は確実にキャパシティオーバーを起こしている。幾ら悪魔に最善の未来が視えるとしても、現実的な身体能力の限界は超えられない。エスクの狙撃が、エルに届くのも時間の問題だ。" },
  { name: "ラプラス", who: "laplace", expr: "mad", text: "まずい、ご主人様！回避して下さい" },
  { text: "エルが咄嗟に身を屈めると、その頭上を一発の弾丸が通り過ぎていく。悪魔の視た未来では、弾丸が撃ち落とせなかった未来が視えたのだろう。逆に言えば、それが悪魔に取れる最善の行動だったという事だ。既に悪魔は追い詰めた。そう……勝利を確信した時の事だった。" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "っ、ご主人！下がれ！" },
  { se: "flash" },
  { fx: "flash" },
  { text: "たった今まで俺が立っていた場所を、風魔術の｜鎌鼬《かまいたち》が掠めていった。そして……" },
  { chara: [
    { slot: "left",   id: "nicholas", expr: "serious" },
    { slot: "center", id: "yamato",   expr: "surprised" },
    { slot: "right",  id: "tia",      expr: "sad" },
  ] },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "聖剣……抜刀……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "は！？はああああああ！？" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "――ヒーローアタック" },
  { fx: "shake" },
  { text: "勇者の｜剣戟《けんげき》を、咄嗟に氷の槍で受け止める。が、剣圧が強すぎて受け止めきれない。俺は遥か後方へと吹き飛ばされた。" },
  { chara: { slot: "center", id: "yamato", expr: "angry" } },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "うっ……何しやがるてめぇ！まさか……お前も俺達を裏切るのか？" },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "……すまない、ヤマト君" },
  { name: "ニコラス", who: "nicholas", expr: "surprised", text: "そういう事に……なっちゃうのかな……" },
  { text: "その表情は、まるで｜諦観《ていかん》するかのような、諦めの顔だった。嫌な予感がする。もう一人の人影、勇者と一緒に居たあの小さな人影は……誰だ？" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "気を付けろアカツキ、来るぞ！" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "えっ、無理です、暗すぎて見えません！" },
  { se: "slash" },
  { text: "耳を澄ませると、風を切る音。アカツキが、不思議そうな顔をして立ち尽くす。その後、アカツキの右腕が……重力に従って自由落下し、地面に転がった。" },
  { fx: "red" },
  { name: "アカツキ", text: "っああああああああっ！？腕が……私の腕が……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "チッ……クロセル！回復魔術を" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "分かっている！" },
  { text: "首が飛ばなかっただけ幸運だ。腕一本なら致命傷ではない。この風魔術。俺はこれを使う人間を知っている。暗闇の小さな人影が、その姿を現す。" },
  { name: "ティア", who: "tia", expr: "sad", text: "ごめんなさい、ヤマト" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "ティア……お前まで……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "どうして……どうしてなんだよ！お前達に何があったって言うんだ！なんで俺達に剣を向けるんだ！" },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "それは……" },
  { name: "ティア", who: "tia", expr: "sad", text: "ごめんなさい……言えないんだ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "くっ、そうかよ、この裏切り者め！俺は……お前達の事を……仲間だと信じてたのに" },
  { fx: "clear-red" },
  { text: "勇者もティアも、悲しそうな顔をして、俺の事を見つめる。エルの前に、勇者、ティア、ラプラスの三人が立ち並ぶ。そう……まるでエルを守るかのように。" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "ご主人、どうするのだ……？" },
  { name: "アカツキ", text: "私は……出来ればティア様、ニコラスさんの事を傷付けたくありません" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "分かってる、俺も同じ気持ちだ、だがやらないとやられる、そうだろう？" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "いやーボクとしては是非とも！此処で仲間通しの殺し合いを見ながらドンパチやりたい所なんですが……ご主人様の意向はそうじゃないんですよねー" },
  { hide: "all" },
  { chara: [
    { slot: "center", id: "yamato", expr: "sad" },
    { slot: "right",  id: "el",     expr: "normal" },
  ] },
  { name: "エル", who: "el", expr: "smile", text: "うん、私の望みは私を無事に逃してくれる事、あと……出来ればヤマト様には死んで欲しいんだけど、駄目かな" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "本当に、戻ってくる気は無いんだな" },
  { name: "エル", who: "el", expr: "smile", text: "私の正体がバレてしまった以上、もうヤマト様と一緒には居られない、楽しい旅を続ける事は出来ない" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "俺がお前を許すと言っても……か？" },
  { name: "エル", who: "el", expr: "normal", text: "うん、駄目だよ、でも安心して、一生の別れって訳じゃない" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "どういう事だ" },
  { name: "エル", who: "el", expr: "normal", text: "私とヤマト様は殺し合う関係、ヤマト様はこれからきっと記憶を取り戻す、そして私を殺しに来る、そうすれば……また会えるよ。早くして、答えないのなら私が決めるけど、良いの？" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "冗談じゃねぇ……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "待て！あと少しだけ待ってくれ！一分！いや30秒で良いから！" },
  { text: "思考をフル回転させる。エルと戦うか、逃がすか。ここで戦えば、エルを仕留める事が出来るかもしれない。エルは瀬野を殺した。到底許されない行為だ。" },
  { text: "だが、此処でエルを殺して何になる？俺の復讐心が満たされるだけじゃないのか？" },
  { choice: [
    { label: "……見逃す",   jump: "b08_spare" },
    { label: "斬りかかる", jump: "b08_attack", kind: "if" },
  ] },

  // --- B08 正史側: 見逃す ---
  { label: "b08_spare" },
  { bgm: "sad" },

  // ---------------------------------------------------
  // Scene 14: god_identity — 正体 (EP102)
  // ---------------------------------------------------
  { label: "god_identity" },
  { comment: "EP102: エル=唯一神の判明と｜慟哭《どうこく》" },
  { chara: [
    { slot: "left",   id: "akatsuki", expr: "serious" },
    { slot: "center", id: "yamato",   expr: "angry" },
    { slot: "right",  id: "crocell",  expr: "sad" },
  ] },
  { name: "エルの声", text: "さて、結論は出たかな？" },
  { text: "｜宵闇《よいやみ》の静寂に、エスクの射撃と、それを叩き落とす音だけが響く。第三の選択肢。一つだけ……ある、それをやる事に意味があるのか、本末転倒なのではないか。切実にそう思うが、提案してみるだけの価値はあるだろう。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "エル、もし……俺が死ぬと言ったら、お前達はこれまで通り、身を寄せ合って旅を続けられるか？" },
  { name: "エルの声", text: "いや、そもそも……もう私が旅を続ける理由は無いんだよ、聖教会から逃げ隠れする理由は無い、あれはあれでスリリングで……楽しかったけどね" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "くっ、駄目なのか……そもそも！お前は一体何者なんだよ！例え勇者とティアが居たとしても、聖教会には勝てないぞ！" },
  { name: "エルの声", text: "ヤマト様……馬鹿なの？多分、クロセルさんとかアカツキさんはもう気付いてるよ、気付いてないのは馬鹿なヤマト様、貴方だけだ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "クロセル、アカツキ……お前達はエルが何者なのか、知ってるのか？" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "この状況から考えて、分からない方がおかしいぞ" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "動揺しているのは分かりますが、冷静になって下さい、ヤマトさんなら分かる筈です、彼女の偽名、\"エル\"が何を意味するのか" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "この世界でエルが何を意味するかなんて分かる訳ねぇだろ……" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "違いますよヤマトさん、私達の世界の言葉です、el、エル、或いはエールとも" },
  { chara: { slot: "center", id: "yamato", expr: "surprised" } },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "俺の世界……地球の言葉か！？" },
  { text: "なんでエルの名前が地球の言葉に起因するんだ？エルも転生者なのか？いや、そんな事はどうでも良い。今は思い出せ、エルという言葉にどういう意味があった？" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "地球でエルと言えば、長さの単位、或いはヘブライ語で……" },
  { text: "そう呟いた所で、俺ははっと気が付く。無知な俺でも偶然知っていた、エルという名詞の意味。それは……" },
  { bgm: null },
  { wait: 600 },
  { fx: "flash" },
  { cg: "cg_el_betrayal" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "――唯一神だ" },
  { fx: "shake" },
  { bgm: "dark" },
  { name: "ラプラスの声", text: "あはははは！やっと気が付いたんですかヤマト様！？そうですよ！ご主人様はこの世界の神だ！" },
  { name: "エルの声", text: "ラプラス、黙りなさい" },
  { name: "ラプラスの声", text: "へーい" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "エルが……神？そんな筈は無い、神は上層に居て、聖教会に保護されている筈だ！" },
  { name: "エルの声", text: "あぁ、あれだね、あれは\"空っぽ\"なんだよ、神の抜け殻とでも称そうか" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "どういう……事だ？" },
  { name: "エルの声", text: "要するに、あれは私の元の肉体なんだ、諸事情で使い物にならなくなったから、このクリスタ・シュルツヴェールって人間の身体を貰ったって訳" },
  { text: "聖教会の崇める神が、抜け殻？いや、確かに納得出来る点はある。聖教会は露骨に神についての言及を避けていた。それが\"神が抜け殻だったから\"だとすれば、｜辻褄《つじつま》は合う。" },
  { text: "聖教会は神が抜け殻である事を人々に隠し、今までまるで\"神が居るかのように\"振る舞っていただけなのだ。だから、その真実を知ってしまったエルを捕らえようとした。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "ははっ……まさか聖教会も……エルが本当の神だとは思いもしなかったんだな……" },
  { text: "思い返せば、納得出来る点は他にもある。エルは俺が風邪を引いた時、「この世界では風邪一つでも命に関わるから」と言っていた。" },
  { text: "あの時、エルは俺が転生者だと知らなかった。なのに\"この世界\"と言うのはおかしい。まるで、シンシアの他に世界がある事を知っているかのような発言だった。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "待て、お前が神なら……あの時、ラプラスがティアを斬った時、祝福を移してティアを助けたのはなんでだ？" },
  { name: "エルの声", text: "あの時に言ったよね、『私はハッピーエンドが好きなんだ』って、あそこでティア様が死んじゃったら、物語として後味が悪いでしょ、だから助けた、それだけだよ" },
  { name: "ニコラス", text: "じゃあ、神は僕を見捨てた訳じゃ無かったんだね！" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "勇者は神の御告げ、いやもはや命令というべきか、それに絶対遵守だ、だから勇者とティアは……神に命令されて俺達に剣を向けた、そうなんだな！" },
  { name: "ニコラス", text: "……すまない" },
  { name: "ティア", text: "……ごめんなさい" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "いや、分かってる。神に何も言うなと命令されてるんだろう？大丈夫だ、お前達は裏切り者じゃない、仕方なく神に従ってるだけだ" },
  { name: "エルの声", text: "少しお喋りをし過ぎたね……ヤマトは馬鹿なままの方が、私には都合が良かったんだけど" },
  { text: "そうだ……あんなに前から、エルが自分の名前を名乗った時点から、ヒントはあったのだ。" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ご主人、少し良いか" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "なんだクロセル" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "エルは今、神として万全ではない、恐らく……神としての力を一部失っている" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "それは……なんでだ？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "神の抜け殻に力を置いてきたと考えるのが妥当だろう、エルが前に言っていただろう？\"神の元に置いてきた物を取りに行った\"と" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "それが、神の力だと言いたい訳か？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "あぁそうだ、そしてそれは全て回収された訳ではない、まだエルは神として万全ではないのだ" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "もし万全になったら……どうなる" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "我々では二度と勝てない……だろう" },
  { text: "エルが上層に行った理由。それは神の力を取り戻す為だ。エルは魔王との決戦に備えて、上層に行き、力を一部取り戻したのだ。" },
  { text: "そしてエルは神であるから、上層から下層に降りる抜け道も知っていた。このままエルを逃して、エルが神の抜け殻から力を回収しきった場合、万全になった神であるエルに、俺達は勝てない。" },
  { text: "此処でエルを逃したら、二度と仕留める事は出来ないのだ。だが、此処でエルを殺しても、ただ俺の復讐心が満たされるだけだ。" },
  { cg: null },
  { bgm: "sad" },
  { chara: [
    { slot: "center", id: "yamato", expr: "sad" },
    { slot: "right",  id: "el",     expr: "normal" },
  ] },
  { text: "ここで仲間同士で殺し合うか、四人をこのまま行かせるか。どちらを選んでも、後悔する未来しか見えない。だが、此処でエルを殺しても、ただ俺の復讐心が満たされるだけだ。なら……答えは一つ。", tid: "ch06__b08_spare__01" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "エル、お前を見逃す、何処にでも行け", tid: "ch06__b08_spare__02" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ご主人……良いのか？" },
  { name: "ラプラス", text: "えーつまんないじゃないですか、殺し合いましょうよー" },
  { name: "エル", who: "el", expr: "sad", text: "そう、分かった", tid: "ch06__b08_spare__03" },
  { chara: { slot: "center", id: "yamato", expr: "angry" } },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "あぁ、俺はお前を許さないが、殺して何か変わる訳でもない。エル、お前はもう仲間じゃない……俺の……俺達の敵だ", tid: "ch06__b08_spare__04" },
  { text: "本当は、今すぐにでもこの手であいつを引き裂いてやりたかった。瀬野を殺され、信じた仲間にまで裏切られて――はらわたが煮え繰り返る。それでも俺は、震える拳を握り締めて呑み込んだ。ここで振るう刃に、意味は無いと知っているから。" },
  { chara: { slot: "right", id: "el", expr: "smile" } },
  { name: "エル", who: "el", expr: "normal", text: "私とヤマト様は殺し合う関係、ヤマト様はこれからきっと記憶を取り戻す、そして私を殺しに来る、そうすれば……また会えるよ", tid: "ch06__b08_spare__05" },
  { name: "エル", who: "el", expr: "sad", text: "行くよ、ラプラス" },
  { name: "ラプラス", text: "しょうがないですねぇ……" },
  { text: "エルは俺に背を向けて歩き出す。ラプラス、勇者、ティアの三人も、それに従ってゆっくりと遠ざかっていく。", tid: "ch06__b08_spare__06" },
  { name: "ラプラスの声", text: "つーかずーっと何か飛んでくるのすごーくうざったいんですけど", tid: "ch06__b08_spare__07" },
  { name: "エルの声", text: "我慢して、役目でしょ", tid: "ch06__b08_spare__08" },
  { name: "ラプラスの声", text: "ボクが常時未来視使ったりしたら、その肉体持ちませんよ？" },
  { name: "エルの声", text: "次の依り代は既に用意させてる、帰るまで持てばそれで良い" },
  { name: "ラプラスの声", text: "随分と自分の肉体に冷たいですねぇ、その身体、気に入ってたんじゃないんですか？", tid: "ch06__b08_spare__09" },
  { name: "エルの声", text: "まぁ、そこそこ気に入ってたよ、ヤマト様の気を惹く事も出来たしね", tid: "ch06__b08_spare__10" },
  { text: "飛び出していきたい気持ちを抑え込む。我慢しろ、俺。エルとはもう決別したんだ。あいつはもう仲間じゃない、分かってる。分かってる筈なのに。", tid: "ch06__b08_spare__11" },
  { hide: "all" },
  { cg: null },
  { hide: "all" },
  { bgm: "sad2" },
  { chara: { slot: "center", id: "yamato", expr: "angry" } },
  { text: "気が付けば、エル達の姿は見えなくなっていた。遠くで聞こえていた射撃音も止んでいた。" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "くそっ！！！" },
  { fx: "shake" },
  { text: "俺は地面に拳を叩き付ける。一度じゃ足りない、何度も何度も叩き付ける。物に当たり散らしても、この気持ちを晴らす事など出来やしない。気が付けば、地面に血溜まりが出来ていく。それでも構わず、俺はひたすら地面を殴る。いや、痛めつけているのは地面じゃない、俺自身だ。" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "ご主人、手が傷付くぞ……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "うるせぇ！知ったことか！くそっ！くそっ！くそおおおおおお！！！" },
  { chara: { slot: "center", id: "yamato", expr: "sad" } },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "俺は……二度と仲間を失う訳にはいかないと、誓ったのに……" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ご主人は何も失っていない、エルは仲間ではなかった、それだけの話だ" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "あいつが仲間じゃなかった……そんなの……受け入れられる訳ねぇだろ……" },
  { text: "俺はべっとりと血の付いた掌を見ながら、その場に倒れ込む。今日は……疲れた。これは、悪い夢なのではないだろうか。このまま目を閉じて、意識を取り戻したら、何も変わりない日常が待っているのではないだろうか。" },
  { name: "クロセル", text: "これは現実だ" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "うるせぇ……そんなのは……分かってるんだよ……" },
  { text: "俺は胸を強く抑えながら、泣きたくなる気持ちを抑え込んだ。" },
  { text: "こんなの、俺らしくない。らしくないけど、こんな事を思ってしまう。願ってしまう。" },
  { text: "――これ以上、俺から大切な物を奪わないでくれ……と。" },

  // ---------------------------------------------------
  // Scene 15: resurrection — 蘇生 (EP102〜103)
  // ---------------------------------------------------
  { label: "resurrection" },
  { hide: "all" },
  { bg: "ariel_town_night" },
  { comment: "EP102: 蘇生術10による瀬野の蘇生" },
  { chara: [
    { slot: "left",   id: "akatsuki", expr: "surprised" },
    { slot: "center", id: "yamato",  expr: "sad" },
    { slot: "right",  id: "crocell", expr: "normal" },
  ] },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ご主人、まだやる事があるのではないか？思い出せ、今は……ご主人にしか出来ない事があるだろう" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "俺にしか出来ない事……？" },
  { text: "何か忘れている。とても大切な事を。変な夢を見て……起きたら瀬野が倒れてて……そうだ、瀬野！" },
  { text: "そうだ、瀬野！エルに瀬野が殺されたんだ。" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "そうだ、そしてご主人の力があれば、ゼノを蘇らせる事も、恐らくは可能だろう" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "なっ……ヤマトさん、そんな事が出来るんですか！？" },
  { text: "クロセルの言葉が確かならば、蘇生術の才能で、人を生き返らせる事が出来る。" },
  { chara: { slot: "center", id: "yamato", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "だが、この力を使えるのは一回だけだ、二度目はない" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ティアの時に使わなくて正解だったな、最も、ティアを生かしたのも瀬野を殺したのも、エルであるというのが皮肉な事だが" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "空が明るくなってきた……夜明けか" },
  { text: "夜だから気が付かなかったが、辺りは中々に悲惨な事になっていた。大量の弾痕と血痕。そしてアカツキの右腕。放り捨てられた氷の剣と槍。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そう言えばアカツキ、手は平気なのか？" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "血だらけの手のヤマトさんに言われたくないですけど……傷は塞いだので平気ですよ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "……クロセル、腕は治せないのか？" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "安心しろ、少し時間は掛かるが回復魔術で治せる、帰ったら治療するとしよう" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうか……じゃあ帰ろうぜ" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "うむ、そうだな" },
  { bg: "sen_mansion" },
  { text: "こうして、俺達はセン公爵の屋敷に戻った。俺は真っ先に自分の部屋に向かうと、瀬野の｜亡骸《なきがら》の前で呟く。" },
  { bgm: "holy" },
  { text: "瀬野の顔は、眠っているように穏やかだった。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……守れなかった。お前の警告ひとつ、俺は活かせなかった。だが、まだ終わらせねぇ。一度きりだ、瀬野。戻ってこい" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "――｜解除《アンロック》" },
  { se: "chime" },
  { text: "\"才能『蘇生術10』を強制解放しました　エラー……才能データが破損しました\"――頭の中に知らない知識が膨大に流れ込んでくる。" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "その詠唱は必要なのか？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……うるせぇ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "｜身体修復《ボディリペア》……｜心魂再生《ソウルリジェネレイト》……――｜蘇生《リザレクション》！" },
  { se: "magic" },
  { text: "俺が詠唱を始めると、瀬野の身体の傷が塞がっていき、その身体が白く発光を始める。" },
  { fx: "flash" },
  { cg: "cg_zeno_revive" },
  { text: "辺りが光に包まれ、視界が真っ白に塗り潰される。同時に……瀬野の身体が電気ショックを受けたかのように大きく跳ねた。" },
  { wait: 700 },
  { cg: null },
  { chara: { slot: "right", id: "crocell", expr: "laugh" } },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "うむ、息を吹き返している。予想通りではあるが、まさか聖なる武器による傷も治せるとはな……流石はご主人の才能だ" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "成功した……のか……" },
  { text: "身体から何かが失われたような感覚が残る。なんと言っても死者蘇生だ。だが、そんな代償は瀬野の命に比べれば軽い物だ。" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "身体の修復と反魂は可能だが、体力までは回復出来ないみたいだ、目覚めるのは暫く先になるだろうな" },
  { name: "エスク", text: "看病はお任せ下さい" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "なっ！？エスクお前何処から現れた！？" },
  { text: "気が付くとエスクが横に立っていた。俺は思わず飛び退く。部屋に入ってきた音も気配もしなかった。｜神出鬼没《しんしゅつきぼつ》にも程がある。" },
  { name: "エスク", text: "……？普通に扉から入りましたが？" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "我も気付かなかった、中々やるではないか" },
  { name: "エスク", text: "そうですか、お褒めに預かり光栄です" },
  { text: "俺もクロセルも人の世話をするのが得意とは言えない。看病はエスクに任せるとしよう。" },
  { name: "エスク", text: "それと、今夜の内容はご主人様に報告しておきましたが……問題ないでしょうか？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうか、構わないぞ、説明の手間が省けたな、助かる" },
  { text: "相変わらずエスクは優秀なメイドだ。エルも優秀ではあったが、単純な能力だけで言えばそれ以上だろう。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "さて、そろそろ時間か、クロセル、始まったら意識を奪ってくれ" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "そうだな、その方がご主人の為になる、任せておけ" },
  { text: "何度も使う内に、あの力の使い方も分かってきた。そして、｜時間制限《タイムリミット》もだ。経験上……そろそろ……\"致命的なエラーが発生した為……破損箇所のある才能を破壊します『蘇生術0』\"" },
  { fx: "red" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "うっぐっ……うあああああああああ！！！？" },
  { fx: "shake" },
  { chara: { slot: "right", id: "crocell", expr: "sad" } },
  { name: "クロセル", who: "crocell", expr: "normal", text: "今夜は余りにも色々な事が起きすぎた、ご主人はゆっくり休むと良い" },
  { fx: "clear-red" },
  { fade: "out" },
  { hide: "all" },
  { text: "頭と胸に激痛が走り、全身が爆発したような感覚。俺は、気が付いた時には既に、意識を失っていた。" },

  // ---------------------------------------------------
  // Scene 16: blank_year — 空白の一年間 (EP103)
  // ---------------------------------------------------
  { label: "blank_year" },
  { bg: "sen_mansion" },
  { fade: "in" },
  { comment: "EP103: 瀬野が語る空白の一年" },
  { bgm: "daily2" },
  { text: "俺が目を覚ましたのは、事件から二日後の事だった。瀬野は順調に回復し、アカツキの腕も無事に治った。今はセン公爵と残された四人が集い、あの夜の事と今後について話し合っていた。" },
  { text: "あ、エスクも居る。位置はセン公爵の座るソファの後ろだ。今の今まで気が付かなかったが。" },
  { chara: [
    { slot: "left",   id: "zeno",   expr: "normal" },
    { slot: "center", id: "yamato", expr: "normal" },
    { slot: "right",  id: "sen",    expr: "normal" },
  ] },
  { name: "セン公爵", who: "sen", expr: "serious", text: "そうか、つまり、君は仲間に裏切られ、逃げる事を許した訳だ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "一言で言えばそういう事になるな……" },
  { name: "セン公爵", who: "sen", expr: "serious", text: "それで、これからどうするんだい？私としては君達が今後も此処に滞在する事に異を唱えるつもりはないが" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "少なくとも瀬野が回復するまでは世話になるつもりだ、その後の事は……考えてない" },
  { name: "セン公爵", who: "sen", expr: "serious", text: "それにしてもまさか君達の中に神が居るとはね、冗談かと疑う程度には、私も驚いた" },
  { text: "エルが神であった事は、セン公爵にも話している。確かに嫌味な貴族男ではあるが、高貴な身分通り良識は弁えている、隠す必要もない。" },
  { name: "アカツキ", text: "私達も驚きました、まさか仲間の中に神が居るとは、多分……誰も思いもしなかったんだと思います" },
  { name: "セン公爵", who: "sen", expr: "normal", text: "だろうね、聖教会が神が抜け殻である事を隠していたんだ、分かる筈もない" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "俺達が聖教会に敵対したのは事実だ、少なくとも、何の目的も無く、教国に戻るつもりはない" },
  { name: "セン公爵", who: "sen", expr: "serious", text: "逆に言えば、何か目的が出来れば、教国に行くつもりなのかい？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ……まぁ、そうなるな……" },
  { text: "エルは、俺とエルは殺し合う関係だと言っていた。俺が記憶を取り戻せば、必ず俺はエルを殺しにいく、と。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そうだ、俺の記憶……瀬野、お前は俺が記憶を失っていると言ってたよな" },
  { name: "瀬野", who: "zeno", expr: "serious", text: "うん、ヤマトはこの世界に転生して来てから、僕と旅をした一年間の記憶を失っている" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "アカツキ、お前は前に西暦2014年に、この世界に来たと言っていたな" },
  { name: "アカツキ", text: "そうです、そして私が異世界に来てから五年が経過しています、つまり今の地球は西暦2019年であるはずなんです" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "俺達は西暦2018年にこの世界に来た、そして一年間の時を過ごし、俺は記憶を失った、だから俺は今が2018年であると誤認していた" },
  { text: "要するに、俺には\"空白の一年間\"があった訳だ。アカツキの言葉の意味を、もう少しちゃんと考えていれば予想出来る事実だった。どうして気付かなかったんだ。" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ご主人が気付かないのも無理はない、気に病むことはないぞ" },
  { name: "瀬野", who: "zeno", expr: "smile", text: "どうしてヤマトが記憶を失ってしまったのか分からないけど……今は僕の知っている事を話すよ" },
  { name: "セン公爵", who: "sen", expr: "serious", text: "ふむ、君達の旅がどんな物だったのか、私も興味がある、何しろアリエルツフィルの外の事は何も知らないからね" },
  { name: "クロセル", text: "我も気になるぞ、我と出会う前に最弱無才のご主人がどうやって生き延びてきたのか" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "うるせぇ、最弱無才とか言うな" },
  { text: "という訳で、俺達は空白の一年間が語られる事になった。その場に居る者は揃って、瀬野の口から紡がれる物語に、耳を傾けた。" },
  { hide: "all" },
  { bg: "country_road" },
  { comment: "回想: 転生直後 — 王都近くの大草原" },
  { bgm: "mystery2" },
  { pov: "zeno" },
  { text: "――これは、瀬野の語る一年前の話。" },
  { text: "僕とヤマトが最初に目を覚ましたのは、王都の近くの大草原だった。" },
  { name: "過去のヤマト", text: "｜魔術回路改竄《カスタマイズ》……｜略式詠唱展開《ファストキャスト》――属性魔術 ｜業炎《ヘルファイア》・｜終焉《ファイナル》" },
  { fx: "red" },
  { text: "草原のほぼ全域に、炎の壁が生まれた。その光景は、まさに地獄だった。" },
  { name: "過去の瀬野", text: "ヤマト！？何をやったのか知らないけどやり過ぎだよ！" },
  { name: "過去のヤマト", text: "こんなにやばい魔術だったのか……大丈夫、今消す" },
  { fx: "clear-red" },
  { text: "ヤマトが軽く手を振ると、辺りの炎が一瞬にして消え失せる。" },
  { name: "過去の瀬野", text: "才能って普通の人は2～3個くらいが基本らしいよ、ヤマトは幾つあるの？" },
  { name: "過去のヤマト", text: "そうだな……ざっと数えて46億個だ" },
  { name: "過去の瀬野", text: "そっか、46個か、すごく多いね……" },
  { name: "過去のヤマト", text: "46億個だ" },
  { name: "過去の瀬野", text: "って億！？億って言わなかった！？ヤマト桁間違えてない！？" },
  { text: "桁外れとかいうレベルじゃない。こんな人間が、この世界に二人と居るのだろうか。いや居ない、断言できる。" },
  { name: "過去のヤマト", text: "あと瀬野、お前にも才能があるぞ……射撃術、空間操作、時間操作、機械技術だ、使い方は脳にインプットされている筈だぞ" },
  { name: "過去の瀬野", text: "空間操作……あはは、石を右手から左手に移せた。マジックとかに使えそうだね" },
  { name: "過去のヤマト", text: "どうやら、この世界の名前はシンシア、今居る国はフォンベルク王国というらしいな" },
  { name: "過去の瀬野", text: "ヤマトの言う通り、僕達のこの力は\"才能\"であってたね、神が与える物だとか何とか" },
  { name: "過去のヤマト", text: "俺なんかにこんな膨大な数の才能を与えるとは、神も物好きな奴だな。さて……俺達には金が無い訳だが……瀬野、あっちの路地に行くぞ" },
  { bg: "royal_capital" },
  { bgm: "dark2" },
  { text: "ヤマトは路地で地面に手を翳し、空間操作で一人の男を落とし穴に落とす。そして錬金術で生み出した鈍色のナイフを突き付けた。" },
  { name: "過去のヤマト", text: "金を置いていけ、そうすれば命は見逃してやる" },
  { name: "冒険者の男", text: "あ？てめぇガキか？へへっ……残念だったな、俺は冒険者だ、勝負を挑む相手は、選んだ方が良いぞ" },
  { name: "過去のヤマト", text: "3秒だけ待ってやる、3" },
  { name: "冒険者の男", text: "ガキが舐めやがって……死ね！" },
  { name: "過去のヤマト", text: "2" },
  { text: "斬りかかってくる男に対して、ヤマトは身動ぎ一つせずナイフを突き付けた姿勢を維持する。男の剣は、ヤマトの身体を捉え、大きく斬り裂いた。……筈だった。" },
  { name: "過去のヤマト", text: "1" },
  { name: "冒険者の男", text: "なっ……剣がすり抜けただと！？" },
  { text: "ヤマトは一歩も動いていない。なのに、男の剣はまるで宙を斬ったかのようにヤマトの身体をすり抜ける。" },
  { name: "過去のヤマト", text: "0" },
  { se: "explosion" },
  { fx: "red" },
  { text: "ヤマトが男の心臓目掛けてナイフを突き出すと、破裂音が大きく響き渡る。辺りには血と肉片が飛び散る。ヤマトの前には、原型を留めない人の死体があった。" },
  { fx: "clear-red" },
  { name: "過去の瀬野", text: "ヤマト！やり過ぎだよ！" },
  { name: "過去のヤマト", text: "あれ……俺何かやっちゃったか？少し痛めつけるだけのつもりだったが……この身体、力の調整が難しいな……" },
  { text: "僕もヤマトも、人の死を見る事は初めてじゃない。霧雨組に居た頃と同じだ。もう動揺する事はない。昔みたいに弱虫な僕じゃないんだ。" },
  { text: "僕達は昔のように人から金を奪って生計を立てた。だが、そんな事を続けていつまでも無事な筈が無い。僕、瀬野 充は王国で犯罪者として指名手配された。" },
  { name: "過去のヤマト", text: "こんな力があるなら、俺はこの世界を支配できるんじゃないか？俺が世界最強になれば、この世界を支配出来る、その為には……この世界で一番強い奴を殺せる力が必要だ" },
  { text: "そして、ヤマトは帝国に居る強者を屠っていった。比喩ではない。文字通り、命を奪ったのだ。希少な存在である勇者や魔族、名の知れた冒険者など。" },
  { name: "過去のヤマト", text: "記憶操作" },
  { text: "殺人の現場を目撃されても、殺すか記憶を操作すれば問題はない。もう、ヤマトが人を何人殺したか分からない。ただ、数えきれない程の命を奪った事だけは紛れもない事実だ。" },
  { text: "そして帝国のある街で、一帯を支配する上級悪魔を殺した日。ヤマトは、ニヤリと大きく顔を歪めると、人差し指を突き出し、一つの目的を高らかに宣言した。" },
  { fx: "shake" },
  { name: "過去のヤマト", text: "――俺は神を殺して、この世界の新たな神になる" },
  { hide: "all" },
  { pov: null },
  { bg: "sen_mansion" },
  { comment: "回想明け" },
  { bgm: "comedy" },
  { chara: [
    { slot: "left",   id: "zeno",    expr: "smile" },
    { slot: "center", id: "yamato",  expr: "surprised" },
    { slot: "right",  id: "crocell", expr: "laugh" },
  ] },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "くっ……くくっ……あのご主人が……『俺はこの世界の神になる』だと？くっ……あはははは！" },
  { chara: { slot: "center", id: "yamato", expr: "angry" } },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "何がおかしくて爆笑してんだクロセル" },
  { name: "アカツキ", text: "なんか私の知ってるヤマトさんのイメージと少し違いますが……納得はしました" },
  { name: "瀬野", who: "zeno", expr: "normal", text: "僕は前のヤマトも、今のヤマトも好きだけどね" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "記憶が無いからまるで他人の話にしか聞こえないんだが、記憶を失う前の俺ってそんなだったのかよ……" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "くっ……ぷっ……くすくす……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "誰か俺の代わりにこいつぶっ飛ばしてくれないか？" },
  { text: "一人だけ笑い転げているクロセルを指差しながら、俺は周りに助けを求める。が、俺の怒りを代行してくれる奴は残念ながら居なかった。" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "はぁ……ふぅ……笑い疲れたぞ、それにしても、随分と予想外な\"空白の一年間\"だったな" },
  { name: "アカツキ", text: "そうですね……瀬野さんに守ってもらいながら逃げ隠れしているイメージだったんですが" },
  { chara: { slot: "right", id: "crocell", expr: "normal" } },
  { name: "クロセル", who: "crocell", expr: "serious", text: "うむ、だがこれでご主人の\"あの力\"の正体が少しだけ掴めたな" },
  { name: "アカツキ", text: "ヤマトさんが本来、無数に持っている才能は、今は使うことが出来ないが、その才能を二度と使えなくなる代償を払えば、一時的に引き出す事が出来る、と" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "そうだな、ご主人は何らかの手段で才能を封印されたと考えるのが妥当だろう、それを無理やり解放しているから、才能が壊れ、ディザビリティに変化すると考えられる" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "なるほど、俺の力はそういう仕組みになっていたのか" },
  { name: "アカツキ", text: "ヤマトさんの記憶が戻っていない以上、まだ推測の域を出ませんがね" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "46億の才能を持つ最強の男、だがしかし今は傷害を禁じられた最弱の男、か……なるほど、興味深い" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "それで俺の空白の一年には何があったんだ？どうしてアランの森で溺れてたんだ？" },
  { name: "瀬野", who: "zeno", expr: "normal", text: "その後、ヤマトは一人で教国に向かったんだ、僕には神を殺しに行くと言い残してね" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "ゼノはついて行かなかったのか？" },
  { name: "瀬野", who: "zeno", expr: "normal", text: "あはは……付いてこうとしたんだけど置いてかれちゃって……" },
  { name: "アカツキ", text: "仲間を置いてくなんてヤマトさん酷いですね" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "俺じゃねぇ！いや俺だけど！記憶が無いだけでそれをやってるのは俺なんだよなぁ……何も反論できねぇ……" },
  { name: "セン公爵", who: "sen", expr: "normal", text: "実に興味深い話をありがとう、ゼノ君" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ほら、ご主人も感謝するのだぞ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ、そうだな……ありがとう瀬野" },
  { name: "瀬野", who: "zeno", expr: "normal", text: "どういたしまして、ヤマト" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "後は、俺自身が思い出すしかないか" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "そうだな、我も出来る限りご主人の記憶が戻る手伝いをするぞ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "ありがたいが……半年以上旅をして何一つ思い出せなかったんだ、そんな直ぐに思い出せる物じゃないだろう" },
  { chara: { slot: "left", id: "sen", expr: "serious" } },
  { name: "セン公爵", who: "sen", expr: "smug", text: "記憶……か……彼女なら、或いは……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "何か方法に心当たりでもあるのか？" },
  { name: "セン公爵", who: "sen", expr: "serious", text: "無い事も無い、君の記憶が記憶操作によって失われた物ならば、同じ記憶操作で取り戻す事が出来るかもしれない、という賭けだ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "それなら俺が自分で記憶操作を｜解除《アンロック》すれば良いんじゃないか？" },
  { name: "瀬野", who: "zeno", expr: "normal", text: "僕の知る限り、ヤマトの記憶操作は他人にしか使っていなかった、自分の記憶を弄れるのかは分からないよ" },
  { name: "セン公爵", who: "sen", expr: "serious", text: "三大公爵家に名を連ねる、シェル家の人間が、高い記憶操作の才能を持っている。ただし危険だ。何しろ彼女達は記憶操作による洗脳じみた方法で一帯を統治している" },
  { name: "セン公爵", who: "sen", expr: "serious", text: "君達に力を貸してくれる保証はないし、最悪記憶を弄られる可能性もある、だが恐らく、今のシンシアで最も記憶操作に長けた人物は彼女しか居ないだろう" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "それは……やべぇ奴らだな、記憶操作に対抗する方法は無いのか？" },
  { name: "セン公爵", who: "sen", expr: "serious", text: "対抗出来る手段は、隠蔽の才能で記憶域を隠蔽するか、精神汚染耐性や意志の才能で耐える、と言った所だろうか。いや、言い忘れていた、記憶操作は、少なくとも才能指数7の段階では接触が条件だ、彼女に不用意に近付かなければ問題はない" },
  { chara: { slot: "center", id: "yamato", expr: "smirk" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "なるほど、触られなければ良いのか。リスクがあるのは事実だが、俺の記憶を取り戻すという事はそれ以上のリターンだ。よし、決めた。俺はシェル公の所に行くぞ、セン公爵、紹介状を書いてくれ" },
  { name: "セン公爵", who: "sen", expr: "serious", text: "あぁ、それは無理だよ、何しろ私とシェル家は犬猿の仲でね、何度か戦争になりかけた事もあるような関係なんだ、だから私の紹介は逆効果だよ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "なら自力でシェル公の元に近付かなければならないのか……面倒だな……お前が無能なせいで俺が困ってる、反省しろ" },
  { name: "アカツキ", text: "記憶を取り戻す手掛かりを事細かく教えて貰った相手にその態度は良くないと思いますよ、ヤマトさん" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "うるせぇ、いつもの癖だ" },
  { name: "セン公爵", who: "sen", expr: "normal", text: "くすくす……まぁ構わないよ、私は寛大だからね" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "本当に、セン公爵が寛大な心の持ち主で良かったな、ご主人、シェル公の前でもその態度だと、直ぐに記憶操作で態度を改められるぞ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "つまり……俺に礼儀作法を求めてるのか？" },
  { name: "アカツキ", text: "せめて敬語は使いましょうよ、王国に居た時は出来たんですし出来るのは知ってるんですよ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "いや……王と公爵じゃ位が違うだろ……" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "何を言っているのだご主人、公国では公が事実上の王だぞ、セン公爵も王族の人間と同程度に偉いのだぞ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "そうなのか……いやでもこの貴族男なんかウザいし……" },
  { name: "アカツキ", text: "態度を改める気が無いなら、シェル公の所に私は付いていきませんよ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "それは困る、俺とクロセルと瀬野じゃ貴族のご機嫌取りなんか出来ない" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "我は出来るぞ！" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "無理だ" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "何故即答なのだ！？" },
  { name: "アカツキ", text: "仕方ないですね……大丈夫です、私も付いていきます。ですがシェル公とのコミュニケーションには大きなリスクがあるんですからね、絶対に変な態度は取らないで下さいよ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ、肝に銘じる" },
  { name: "セン公爵", who: "sen", expr: "normal", text: "では、エスク、フェアリーケレッジまでの地図を書いてきてくれ" },
  { name: "エスク", text: "承知しました" },
  { text: "命令を肯定する言葉がエスクの口から紡がれた瞬間、その姿は消え失せていた。やっぱあいつ幽霊だろ。" },
  { name: "セン公爵", who: "sen", expr: "normal", text: "では、私は仕事もあるのでこの辺で失礼しよう、準備はエスクに一任したから、何かあったら彼女を頼ってくれ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "分かりました、貴重なお時間を割いて頂きありがとうございます" },
  { name: "セン公爵", who: "sen", expr: "normal", text: "構わない、とても有意義な時間だったよ、ではね" },
  { text: "セン公爵はそう言って部屋を後にする。" },
  { hide: "sen" },
  { chara: { slot: "left", id: "zeno", expr: "smile" } },
  { name: "瀬野", who: "zeno", expr: "smile", text: "僕も付いていって良い……んだよね？" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "当たり前だろ、置いていったりしない、準備をすると言ったが、今日明日に発つ訳じゃない、瀬野が旅に付いてこれる程度に回復するのを待つつもりだ" },
  { name: "瀬野", who: "zeno", expr: "smile", text: "そっか、良かった" },
  { text: "また置いていかれるとでも思ったのだろうか。こうして俺達は、瀬野が完全に回復するのを待って、旅の準備を整えるのだった。セン公爵の屋敷に滞在したのは二週間程度。誰にも見えない心の底で、俺は貴族男の奴に感謝の念を抱いた。" },

  // ---------------------------------------------------
  // Scene 17: fairy_college — フェアリーケレッジ (EP104〜105)
  // ---------------------------------------------------
  { label: "fairy_college" },
  { hide: "all" },
  { bg: "country_road" },
  { comment: "EP104: 道中の手品" },
  { text: "瀬野が完全に回復した数日後。俺達はフェアリーケレッジを目指して馬車に揺られていた。" },
  { chara: [
    { slot: "left",   id: "zeno",    expr: "smile" },
    { slot: "center", id: "yamato",  expr: "sad" },
    { slot: "right",  id: "crocell", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "おいすげぇ！馬車が広いぞ！横になれる！" },
  { name: "アカツキ", text: "ヤマトさん……" },
  { name: "瀬野", who: "zeno", expr: "sad", text: "ご主人……" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "なんだよ、その目は……" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "エル……ティア……勇者……本当に居なくなっちまったんだな……" },
  { name: "アカツキ", text: "やかましいとさえ感じていたあの頃の喧騒が、今は懐かしいですね" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ほら、折角の旅なのだからそんな暗い顔をするでない、我が明るくしてやろう！｜魔術回路改竄《カスタマイズ》！" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "馬車の中で魔術を放つのはやめろ" },
  { name: "瀬野", who: "zeno", expr: "smile", text: "じゃあ代わりに僕が盛り上げようか、ここに一つのビー玉があります" },
  { text: "これは予想できる、高速でビー玉を行き来させ、最終的に右手と左手どちらにビー玉が入っているか当てる奴だ。単純な遊びだが、余興だろうと俺は手を抜かない主義だ、目を凝らして、ビー玉の残像を追う。" },
  { text: "瀬野の時間操作によるビー玉マジック。まるでビー玉の時間が加速したかのように異常な速度で、ビー玉は瀬野の両手を高速で行き来する。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "くっ……速い！？下手したら銃弾より速いだろこれ！" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "くっ、中々やるようだな……――属性魔術 ｜海王覇気《インペリアルオーラ》・｜瞳《アイズ》！" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "おいクロセル視覚強化とはずるいぞ" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "何を言っているのだ、瀬野の奴も時間操作でビー玉の時間を加速させているのだからこれで平等だろう" },
  { name: "瀬野", who: "zeno", expr: "smile", text: "流石はクロセルさんだね、一発で見破るなんて" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ふっ、それほどでもない" },
  { text: "瀬野の時間操作vsクロセルの視覚強化魔術。余興の筈が何故か異能バトルに発展している。" },
  { name: "瀬野", who: "zeno", expr: "smile", text: "はい、ビー玉は右手と左手、どちらにあるでしょうか！" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "俺は分かった、クロセル、先に言っていいぞ" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ふっ、強がりおって、我も分かっている、ご主人こそ先に言って良いのだぞ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "ほう？そんなに俺に先に言って欲しいって事は、自分が分かっていないと証明している事になるぞ？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "心外だ、我は優秀な｜魔杖《まじょう》だからな、回答権を譲ってご主人に華を持たせてやろうとしているのだ、寧ろ感謝して欲しい" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうか、そこまで言うならこうしよう、同時に答えを言うんだ" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ご主人がそれで良いのなら、我もそれで良いぞ" },
  { text: "俺とクロセルの間で、日本人特有の譲り合いが発生している。この手の問題は基本的に平行線だ、痛み分けにするのが一番の解決策。俺はそう知っている。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "じゃあ3秒数えたら同時に言うぞ？3、2、1……" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "左！" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "右だ！" },
  { text: "だが、瀬野が手を開くと、どちらの手にもビー玉は無かった。" },
  { chara: [ { slot: "center", id: "yamato", expr: "surprised" }, { slot: "right", id: "crocell", expr: "surprised" } ] },
  { name: "クロセルとヤマト", text: "「「は？」」" },
  { name: "瀬野", who: "zeno", expr: "smile", text: "おや？何処にもビー玉はありませんね？何処に行ってしまったのでしょう" },
  { text: "瀬野が俺のポケットに手を突っ込み、ビー玉を取り出す。これは手品だ。俺とクロセルは見事に騙された。" },
  { name: "瀬野", who: "zeno", expr: "smile", text: "おや！こんな所にありました！びっくりですね！えへへ……結構練習したんだよ？" },
  { name: "瀬野", who: "zeno", expr: "smile", text: "……ってあれ？二人とも、どうしたの？" },
  { name: "クロセルとヤマト", text: "「「許さん！｜瀬野《ゼノ》！！！」」" },
  { text: "俺とクロセルは同時に同じ台詞を叫ぶと、二人して瀬野に飛び掛かった。その後、瀬野がどうなったかは、皆の想像にお任せするとしよう。" },
  { name: "瀬野", who: "zeno", expr: "scared", text: "うわーん！ヤマトとクロセルさんが僕を虐めるよぉー！僕は皆を喜ばせようと手品を披露しただけだったのに……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "俺とクロセルを騙すなんて悪質にも程がある" },
  { name: "瀬野", who: "zeno", expr: "scared", text: "手品ってそういう物だからね！？普通は逆ギレする観客とか居ないからね！？" },
  { name: "アカツキ", text: "全く……馬車が汚れたじゃないですか、高かったんですよ？" },
  { name: "瀬野", who: "zeno", expr: "sad", text: "うぅ……なんか今日はアカツキさんも辛辣だ……僕が悪いのか？そうだよな……僕が悪いんだな……" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ご主人、我も瀬野のような手品とやらを見せてやろうか？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "お前のはただの魔術だろ" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "奇術も魔術も大して変わらんだろう" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "だいぶ違うと思うんだがな……" },
  { text: "そんな風に話している間に、気が付けば仲間を失った事による暗い雰囲気は払拭されていた。" },
  { text: "最大公爵家が治める都市郡は、その中心を結ぶと綺麗な正三角形が生まれるように出来ている。最も、魔王軍の襲撃で多くの都市は壊滅した為に、現在機能している都市はセン公爵のアリエルツフィルとシェル公爵のフェアリーケレッジの二つだけらしい。" },
  { text: "それ以外の場所は魔物の｜蔓延《はびこ》る危険地帯だ。道中で何度も魔物と遭遇したが、大抵はクロセルの魔術で一撃だった。" },
  { hide: "all" },
  { bg: "fairy_celledge" },
  { bgm: "mystery" },
  { text: "そして三日。辿り着いた都市フェアリーケレッジには、異様な光景が広がっていた。" },
  { chara: [
    { slot: "left",   id: "zeno",    expr: "scared" },
    { slot: "center", id: "yamato",  expr: "surprised" },
    { slot: "right",  id: "crocell", expr: "serious" },
  ] },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ふむ、家屋な町並みはアリエルツフィルと大して変わらんが……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "人が……同じ格好をして歩いている？" },
  { text: "誰もが全く同じデザインの緑色の服を着て、揃って腕に緑色のリングを嵌めている。不気味なほど統一感のある街並みだ。髪の色を除けば、誰もが同じカラーリングの格好をしている。" },
  { name: "瀬野", who: "zeno", expr: "scared", text: "なんか不気味だね……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "この街の奴らは全員精神異常者か何かなのか……？しかも緑って何だよ気持ち悪い、自然愛護団体？" },
  { name: "アカツキ", text: "取り敢えず入りましょうか、私は馬車を預けてくるので、皆さんは先に宿に向かってて下さい" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "分かった、この街は何かおかしい、気を付けろよ" },
  { text: "俺達は街の案内に従って宿に向かう。店の人間も緑だ。これでは誰が客で誰が店の人間か見分けがつかない。逆に、それ以外の服を着ている人間は外部から来た人間だと一目で分かる事になる。宿の食堂で、バックパックに腰に剣を携えた、旅の冒険者らしき風貌の男に声を掛ける。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "少し良いか。俺も旅人なんだが、この街に来るのは初めてなんだ、この街がどんな場所なのか教えて貰えないか？" },
  { name: "シュン", text: "そうなのか、それぐらいならお安い御用よ。此処はフェアリーケレッジ、アステカス公国シェル公爵領の主要都市、魔王によって滅ぼされたと噂されていたが、何の偶然か奇跡的に残った幸運な都市だ" },
  { name: "シュン", text: "そして、この街は妖精を信仰している" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "妖精？ってのは……何だ？" },
  { name: "シュン", text: "そこからか、この世界の生物は大きく分けて七種類に分けられるってのは知ってるか？神、人間、魔族、妖精、魔物、動物、植物、妖精はその一つだ、人と同じで神が作った存在、人間とは比較にならない程多くの、高い才能を持つのが最大の特徴だ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そんな強大な存在なら、もう少し有名でもおかしくない気がするが" },
  { name: "シュン", text: "妖精は寿命と繁殖能力を持たない、だが死の概念はある、最初は人間と同等の数が生息していたと言われているが、長い年月を掛けてその数を減らした" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "なるほど、道理で見ない訳だ" },
  { name: "シュン", text: "既に絶滅したとも言われていたんだ、だが僅かだが生き残りが居た、ここフェアリーケレッジの別名は妖精都市、妖精が支配する都市だ" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "待て……その言い方だと、まさか……シェル公爵ってのは……" },
  { name: "シュン", text: "あぁ、その通りだ、シェル公爵は太古から存在する超常的な存在、妖精なんだよ" },
  { name: "シュン", text: "この街の人間がみんな緑色の服を着ているのは、どうやらシェル公爵の命令らしい、何の意味があるのかは知らないけどな" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうか、色々と分かった、助かったよ、俺はヤマトだ" },
  { name: "シュン", text: "俺はシュンだ、この街にはアリエルツフィルを目指す途中で寄ったんだが……やっぱ居心地が良いとは言えねぇな" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "同感だ、あまり長居したいとは思えない" },
  { name: "シュン", text: "あと数日は滞在するつもりだ、何かあったらまた声を掛けてくれ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "おう、ありがとな、シュン" },
  { text: "そして、この街の人間は妖精を、シェル公爵を信仰している――。丁度、アカツキも着いた所で、俺達三人は情報を共有した。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "本格的な調査は明日からだな、何とかしてシェル公爵に近付き、記憶操作を掛けて貰って俺の記憶を取り戻す" },
  { name: "アカツキ", text: "言葉にするのは簡単ですが、実際に実行するのは中々大変そうですね……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ、シェル公爵は他の三大公爵と仲が悪いらしいからな、ボルトの紹介状も逆効果だと見て良いだろう" },
  { name: "アカツキ", text: "ただの旅人である私達では、シェル公爵に近付くことからして難しいですからね" },
  { text: "相も変わらず前途多難だが、折角此処まで来たのだ、やるしかない。そうして俺達は明日から始まる調査に備えて、旅の疲れを癒やすのだった。" },
  { hide: "all" },
  { fade: "out" },
  { comment: "EP105: Side Story『使い捨ての身体』— クリスタの最期" },
  { pov: { name: "クリスタ", color: "#5FA8D3" } },
  { bg: "arcadia_upper" },
  { fade: "in" },
  { bgm: "sad2" },
  { text: "その頃、遠く聖都アルカディアで――" },
  { name: "クリスタ", text: "ごほっごほっ……" },
  { text: "私は目を覚ました。長い間眠っていたような気がする。そして、長い長い夢を見ていた気がする。知らない国に行って、王宮に仕えて、一人の男の人と出会って、その人と一緒に旅をする夢。" },
  { text: "楽しい夢だった。あの時間が永遠に続いて欲しいと思った。でも、あれは夢。だから、こうして目覚める時が来てしまう。僅かな名残惜しさを覚えつつ、私は目を開ける。" },
  { name: "クリスタ", text: "えっ……血……？" },
  { text: "私は倒れていた。眠っていたのだから当然と言える。だが、おかしな事に、私の頭の周りには、大きな血溜まりが出来ていた。一体誰の血だろう？こんなに一杯血を出したら、死んでしまう。" },
  { name: "神", text: "すごい、まだ生きていたんですか、中々にしぶといですね、私の\"前の身体\"は" },
  { name: "クリスタ", text: "だ……誰……？此処は……何処？" },
  { name: "イヴ・エンド", who: "eve_end", expr: "cold", text: "クリスタ・シュルツヴェールの肉体はどうしますか？" },
  { name: "神", text: "寿命は全部ラプラスに捧げましたし、第三権能、第四権能も回収しました、もう用はありませんが、どうせ長くは生きられない、放っておきなさい" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "畏まりました、神様" },
  { text: "クリスタ・シュルツヴェール。私の事だ。私が長くは生きられない？どういう事だろう。それに此処は何処だっけ。あまりにも長い夢を見ていたせいで、眠る前の記憶が思い出せない。私は、ゆっくりと、丁寧に……眠る前の記憶を辿る。" },
  { text: "私はクリスタ・シュルツヴェール。教国に生まれた、何の変哲も無い一人の少女だ。才能は家事1、氷魔術4、短剣術4。兄に比べれば見劣りするが、比較的才能には恵まれていた方だろう。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "教皇イヴ・エンドが神に代行して、クリスタ・シュルツヴェールを聖位階第三位に命ずる" },
  { text: "私は10歳にして福音使徒の聖位階第三位まで昇格した。｜聖一位《せいいちい》の福音使徒である兄クラウス・シュルツヴェールの功績も大きかったが、それだけではない。私のように、こんなにも幼い少女を上層に立ち入る権限を持つ｜聖三位《せいさんい》まで昇格させた理由は唯一つ。" },
  { text: "――次の神の｜依り代《よりしろ》となる為だ。聖教会は、非常時に備え常に｜聖三位《せいさんい》に次の神の｜依り代《よりしろ》となる少年少女を一人設置する。私は、その神の肉体の予備として選ばれ、福音使徒となったのだ。だが神は私を気に入らなかった。" },
  { name: "神", text: "確かに容姿は優れていますが、才能は平凡、貴女が私の次の肉体にはならない事を祈りたいですね" },
  { name: "クリスタ", text: "私なんかが……ごめんなさい……" },
  { name: "神", text: "まぁ、私の今の肉体はあと三年持ちます、その頃にはもっと良い肉体が用意されている事でしょう" },
  { text: "私は｜聖三位《せいさんい》にも関わらず、神の側に置かれた。そして、皮肉や嫌味を毎日のように聞かされていた。それでも、私は予備と言えど神の肉体に選ばれた事が誇らしかったし、神が私を嫌っても私自身は神の事を絶対と信仰し、崇めていたから、苦ではなかった。そんな、ある日の事だった。" },
  { name: "クリスタ", text: "神様、お食事の時……間……神様！？" },
  { text: "私が聖域に昼食を運んできた時、聖域は酷い有様だった。何者かによって至る所が破壊され、透明な破片が辺り一面に散らばっている。その中央には血溜まりに倒れ込んだ神様の姿と、少し遠くに福音使徒ではない、見慣れない男が倒れていた。私は食事を取り落とすと、慌てて神様に駆け寄る。" },
  { name: "クリスタ", text: "神様！？待って下さい、今傷を塞ぎます" },
  { name: "神", text: "致命傷ですね、やむを得ませんか" },
  { text: "神は胸元に大穴を開けつつも、まだ生きていた。奇跡的に片肺と心臓は無事だったらしい。それでも致命傷には変わりがない。私は氷魔術で傷を塞ぐ。が、内蔵の修復は回復魔術では無い為に出来ない。" },
  { name: "クリスタ", text: "ちょっと待ってて下さい、今助けを呼んできます！" },
  { name: "神", text: "待ちなさい、今から行っても間に合いません、その肉体を寄越しなさい" },
  { name: "クリスタ", text: "えっ……？" },
  { text: "助けを呼びに行こうとすると、神は私の手を掴む。私の肉体を寄越せ、つまり神様は私の身体を｜依り代《よりしろ》にしようとしている。" },
  { name: "クリスタ", text: "……いや……嫌だ！やめて！" },
  { text: "突然、恐怖が全身を襲う。こうなる事が役目だと、ずっと前から分かっていたはずなのに。いざその状況に直面すると、突然な肉体との別れ、精神の死に全身が恐怖に包まれる。" },
  { name: "神", text: "全ての権能を移す時間は無いですね、まぁ良いでしょう、後で回収しに来れば良い" },
  { name: "クリスタ", text: "誰か！助けて！" },
  { name: "神", text: "第二権能発動……第三権能の移行を開始……成功……" },
  { text: "私は全力で逃げようとするが、そんな抵抗も神の前では無意味だった。神が何かを呟いた途端、身体に謎の力が宿る。これは……誰かの感覚だろうか。" },
  { text: "視覚、聴覚、触覚、そんな物が私の中で無数に重複して感じられるようになる。複数人の感覚を、一人の脳で処理出来る筈がない、気持ち悪い、気が狂いそうだ。" },
  { name: "クリスタ", text: "うっぐっ……おえっ……" },
  { name: "神", text: "まぁ当然、貴女には使えないでしょうね、精神の移行を開始……成功……" },
  { text: "まずい、そう思った時にはもう遅かった。身体の中に覚えのない記憶が流れ込んでくる。これは神の記憶だろうか。記憶は私の身体の中でその存在感を増幅させていき、やがて私の意識は神の意識に押し出されるようにして途切れた。" },
  { name: "クリスタ", text: "そうだ……私は……神に身体を乗っ取られて……" },
  { name: "神", text: "どうやら思い出しましたか、私も貴女の身体の悪口を散々言っていた記憶がありますが、実際使ってみると悪くもなかったですよ" },
  { name: "クリスタ", text: "返してくれた……の？" },
  { name: "神", text: "まぁ、そういう事にもなりますかね、おめでとうございます、貴女は自由の身ですよ" },
  { text: "聞いたことのない声が聞こえる。だが、発言からして間違いなく神様だろう。私の身体を捨てて、新しい身体に乗り移ったと言った所か。" },
  { name: "クリスタ", text: "ありがとう……ございます……神様……" },
  { name: "神", text: "えぇ、私に感謝しなさい、価値の無い、貴女の身体を有効活用してあげたのだから" },
  { text: "私は長くない。先程、神様はそう言っていた。それでも、｜刹那《せつな》の間でも、私は私を取り戻す事が出来た。それに、あの幸せな夢を見られたのだ。それだけで私の人生には価値があったと言えるだろう。" },
  { name: "クリスタ", text: "ごほっ……" },
  { wait: 1000 },
  { fade: "white" },
  { text: "私は小さく咳き込む。すると、まるで電力の供給が切れたかのように、全身から力が失せていく。やがて、自覚する事も無く、ぷっつりと意識が途切れた。こうして、クリスタ・シュルツヴェールは、その生命の持つ時間を使い切った。" },
  { name: "神", text: "イヴ、それの片付けは任せますよ" },
  { name: "イヴ・エンド", who: "eve_end", expr: "cold", text: "畏まりました、神様は権能の回収ですか？" },
  { name: "神", text: "えぇ、権能を回収したら、前の前の肉体も捨てて構いません、あれは神の権能を宿しただけの死体ですし" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "分かりました" },
  { text: "聖都アルカディア上層。そこに本当の神が戻ってきた日であった。" },

  // ---------------------------------------------------
  // Scene 18: shell_meeting — シェル公爵 (EP106) ◆B07
  // ---------------------------------------------------
  { label: "shell_meeting" },
  { pov: null },
  { fade: "out" },
  { hide: "all" },
  { bg: "fairy_celledge" },
  { fade: "in" },
  { comment: "EP106: ジャングルの大聖堂 — シェル公爵との面会" },
  { bgm: "mystery2" },
  { text: "フェアリーケレッジ二日目。俺達はシェル公爵の屋敷の近くまで来ていた。屋敷を一言で言うとすれば……ジャングルだ。" },
  { text: "熱帯雨林と見紛う程に大量の木、木、木。そのどれもが十数メートル近い高さを持ち、地上部分は蔦が張り巡らされ、緑に覆われている。此処が街の中だと言う事を忘れてしまいそうだ。それ程までに、異常な光景であった。" },
  { text: "十数メートルの樹林に覆われた、ノートルダム大聖堂のような白い建物。" },
  { chara: [
    { slot: "center", id: "yamato",  expr: "surprised" },
    { slot: "right",  id: "crocell", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "明らかにおかしい……よな" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "うむ、この樹林には何らかの環境適応、成長促進が行われていると考えるのが妥当だろう、少なくとも公国の気候では此処までの異常成長はあり得ない" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "クロセル、内部の生命反応を探査できるか？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "中の生命反応は28、殆どが人間だな、あの聖堂らしき場所に人が固まっている" },
  { text: "俺は何の躊躇いも無く屋根から飛び降り、丁度通りかかった人の頭を踏んだ反動をディザビリティで吸収して無傷で着地する。驚いた様子で頭を擦る通行人に、ついでだとばかりに声を掛ける。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "少し話を聞いても良いか？あの屋敷には教会のように誰でも入れるのか？" },
  { name: "通行人", text: "シェル公爵を信仰する心の持ち主であれば、誰でも入れますよ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "……つまり、この街の人間でなければ入れないと？" },
  { name: "通行人", text: "そうとは限りません、シェル公爵は寛大なお方です、あの方を熱心に信仰する者であれば街の人間で無くても入れて貰えるかと" },
  { text: "どうやら、シェル公爵の屋敷が教会のような機能を有しているのは事実らしい。シェル公爵の信徒を装えば、屋敷に入り、あわよくば近付く事も出来るかもしれない。俺達は信徒を装う事にした。クロセルが通信魔術でアカツキと瀬野を呼び寄せる。" },
  { name: "アカツキ", text: "ふぅ、お待たせしました" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "来たか、って……瀬野はどうした？" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ゼノなら居るぞ、少し縦軸が誤った座標に飛んでしまったらしい" },
  { name: "瀬野", text: "ぅわあああああああああああ！？" },
  { se: "explosion" },
  { text: "上から落ちてきた瀬野が地面に叩き付けられる。空間操作の練習で飛んだら、座標を誤って高所から落ちてきたらしい。魔族の肉体のお陰で大怪我で済んでいる。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "クロセル……なんで受け止めてやらなかったんだ" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "当たりどころが悪くなければ死なない距離だったからな、まぁ待て、今回復魔術を掛けてやろう" },
  { name: "瀬野", text: "ふぅ、死ぬかと思ったよ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "少し目立ちすぎたな……一旦退くぞ" },
  { name: "アカツキ", text: "奇妙な事に、街の何処にも、ある物が売っていなかったんです。この街の人間が全員付けている、あの緑色の腕輪です" },
  { name: "瀬野", text: "あの腕輪だけは説明がつかないんだ、非売品でありながら街の人間全員の装着が、まるで義務付けられている" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、シェル公爵が着用を義務付けてる、んだろうが……あれには何の意味があるんだ？" },
  { name: "アカツキ", text: "無難な説を唱えるならば、街の人間とそれ以外の人間を区別する為……とかですかね" },
  { name: "瀬野", text: "あっ、もしシェル公爵の屋敷に乗り込むならさ、これを使ってよ" },
  { text: "瀬野が亜空間から緑色の服を四人分取り出す。空間操作の才能で亜空間を作り出し、そこに物を収納しているのだ。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "なるほど、転移にショートカットに四次元ポケットと、便利だな空間系の才能は" },
  { name: "アカツキ", text: "八種類の基本属性魔術と比較して、空間魔術と時間魔術の二つは便利系魔術とも称されます、属性魔術と違って派手な事は出来ませんが利便性だけならトップクラスですね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "つまり魔術は十種類に分類出来るって事か？" },
  { name: "アカツキ", text: "そうですね、十種類です、詠唱全体の最初から二つ目の部分を中唱と言うんですけど、そこの魔術言語で何の種類の魔術かを判別する事が出来ます" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "トゥームとかいう奴だな、あれにもちゃんと意味があったのか" },
  { name: "アカツキ", text: "なので相手の詠唱から魔術の属性を推測、対処する事も可能です、例えば相手が炎の魔術で攻撃してくると分かれば、此方は水の魔術で対抗すれば有利が取れる、と言った感じですね" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "だが略式詠唱を使えば相手に魔術の内容も属性も悟られる事が無い、我が略式詠唱を好む理由の一つだな" },
  { text: "俺は緑色の服に着替え始める。しかし、何故かクロセルとアカツキだけが、服を持ったまま立ち尽くしている。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "あっなんだ？着替えさせて欲しいのか？仕方ねぇなぁ……" },
  { text: "俺がアカツキの方に歩み寄ろうとすると、背後から殺気を感じる。この距離での不意打ちには流石の俺でも対処出来ない。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "うぐっ……クロ……セル……" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "これはご主人が悪いぞ、暫し眠っておれ" },
  { text: "首をやられた。一瞬にして意識が遠のく。意識の終端では、冷たい瞳で俺を見つめる、クロセルの顔が見えた。" },
  { text: "……五分後、俺は後頭部にたんこぶを作って目を覚ました。腑に落ちないが、聞いても答えては貰えないだろう。" },
  { text: "緑衣を纏った俺達は、堂々と大聖堂へと足を踏み入れる。中に入ってみたが、特に咎められる事は無かった。" },
  { text: "入って直ぐの場所に広い礼拝堂のような空間が広がっている。その最奥には｜暗幕《あんまく》が垂れ下がり、街の人は皆揃って｜傅《かしず》き、左手人指し指を額に付けるようにして、その｜暗幕《あんまく》に向かって祈っている。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "此処で祀ってるのって神とかじゃなく、シェル公爵……だよな？なら信者達が祈ってる｜暗幕《あんまく》の奥に居る人影って……" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "あれは｜案山子《かかし》などでは無く生きた生物だ、つまりシェル公爵で間違いないだろう" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "なら近付いてみるか" },
  { name: "アカツキ", text: "無策で突っ込む気ですか！？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "シェル公爵が常に居るとは限らない、会える時に会っとくのが良いと思うが" },
  { name: "アカツキ", text: "それはそうですけど……" },
  { text: "俺は祈る人達の横を通り過ぎ、｜暗幕《あんまく》へ近付いていくと、それを潜って奥に入り込んだ。緑衣の男が立ちはだかる。" },
  { name: "緑衣の男", text: "何者だ！此処は立ち入り禁止だぞ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "シェル公爵と話がある、通してくれ" },
  { name: "緑衣の男", text: "お前達……この街の人間じゃないな？駄目だ、お前達のような怪しい者をシェル様に近付ける訳には行かない" },
  { chara: [
    { slot: "farleft", id: "akatsuki", expr: "serious" },
    { slot: "left",    id: "crocell",  expr: "normal" },
    { slot: "center",  id: "shellmi",  expr: "smug" },
    { slot: "right",   id: "yamato",   expr: "normal" },
  ] },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "至極尤もな正論だ、だがしかし、話ぐらいなら聞いてやっても良いのではないか？" },
  { name: "緑衣の男", text: "シェル様……しかし……" },
  { name: "シェル公爵", who: "shellmi", expr: "sad", text: "遠路遥々訪ねてきてくれたんだ、何の土産も持たせず帰すのも可哀想だろう" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "アカツキ、頼んだ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "まずは何の断りも無くこの場に立ち入った非礼をお詫びします、申し訳ありませんでした" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "くくく……構わんよ、長い事生きていると刺激に飢えてしまってね。魔術9の｜魔杖《まじょう》、操作系才能持ち、複数のディザビリティの持ち主。中々に愉快なメンバーだ、面白いじゃないか、名前を聞かせてもらえるかな？" },
  { text: "漆黒のドレスに黒いベール。クロセルの身長程もある高い椅子に座る、身長140cm程度の小柄な人影。一目で俺達の才能を｜看破《かんぱ》した辺り、只者では無い。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "俺はヤマト……です" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "我が名はクロセルだ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "アカツキと申します" },
  { name: "瀬野", text: "瀬野 充です" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "では私も名乗るとしようか、私の名前はオルガン・ヴィーナス・シェル、愛称はシェルミだ、好きに呼んでくれて構わん。それで、わざわざ正装をしてまで来てくれたというからには、何か私に用事があって来たのではないのかね？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "これは正装なのか……？変装の間違いじゃ……" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "シェル公爵、私達は貴女の力を借りるために此処にやって来ました。シェル公爵の持つ記憶操作の才能の力を借りたいのです" },
  { name: "シェル公爵", who: "shellmi", expr: "normal", text: "私の力か……生憎、戦闘向きの才能は持ち合わせていないんだが……" },
  { name: "シェル公爵", who: "shellmi", expr: "surprised", text: "ほう？私が記憶操作の才能を持っているという事は一種の機密事項の筈だが……何処でそれを知った？" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "嘘はつけませんね……私達はアリエルツフィルから来ました" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "なるほど、あのロリコンの変態が私の事を喋った訳か、それなら確かに｜辻褄《つじつま》は合う" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "単刀直入に言いましょう、シェル公爵にはヤマトさんの記憶を操作して失われた記憶を取り戻して欲しいんです" },
  { name: "シェル公爵", who: "shellmi", expr: "normal", text: "記憶喪失か、私の才能では同じ記憶操作で失われた記憶なら取り戻せるが、脳へのダメージで失われた記憶は元に戻せないぞ？" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "駄目で元々です、私達もヤマトさんがどうして記憶を失ったのか分からないので、試してみて欲しいんです" },
  { name: "シェル公爵", who: "shellmi", expr: "normal", text: "良いだろう、だが勿論タダでとは言わない、何らかの対価を要求する" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "金銭でしたら……幾ら必要ですか？" },
  { name: "シェル公爵", who: "shellmi", expr: "normal", text: "いや、勘違いしないで欲しい、貴族という物は意外と金に興味が無いんだよ、私も金に興味はない、別の対価で頼むよ" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "では……情報ではどうでしょう、私達の知る限りの情報を提供すると言ったら" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "あはははは！君達、私が妖精だという事は知っているのだろう？妖精は寿命を持たない唯一の存在、要するに世界で一番長く生きている存在だ、そんな私の知らない事を君達が知っているとは到底思えないな" },
  { text: "どうする？他に対価になる物など持っていない。魔剣グレモリー……いや、あいつを誰かの手に渡すのは約束を違える事になる。それは俺のポリシーに反する。" },
  { name: "シェル公爵", who: "shellmi", expr: "normal", text: "いや、ふむ……そうだな……それも一興か" },
  { chara: { slot: "right", id: "yamato", expr: "surprised" } },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "あ？どうしたシェル公爵" },
  { chara: { slot: "center", id: "shellmi", expr: "normal" } },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "いやなに、やはり対価は要らない、無償でヤマトの記憶を取り戻してやろう" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "本当ですか！？" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "妖精は気まぐれでね。私の気が変わらない内に、早く済ませるとしようじゃないか" },
  { text: "彼女が頭のベールを外す。現れたのは金髪｜碧眼《へきがん》の少女だった。とても数千年を生きている存在とは思えない。" },
  { text: "彼女が手を伸ばす。何だか嫌な予感がした。この人間は本当に信用できるのか？" },
  { choice: [
    { label: "記憶操作を受ける",   jump: "b07_accept" },
    { label: "断って屋敷を出る", jump: "b07_refuse", kind: "if" },
  ] },

  // --- B07 正史側: 受ける ---
  { label: "b07_accept" },
  { text: "リスクは承知の上だ。それに……俺には密かに仕込んでおいた切り札がある。俺は覚悟を決め、シェル公爵の前に進み出た。", tid: "ch06__b07_accept__01" },
  { chara: { slot: "center", id: "shellmi", expr: "smug" } },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "大人しくしていてくれよ、何しろ眠っている記憶を呼び覚ますのは中々に面倒な仕事だ、途中で中断して記憶に障害が残っても私は責任を取らない", tid: "ch06__b07_accept__02" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ……動かなきゃ良いんだろ", tid: "ch06__b07_accept__03" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "そう……それで良い、では始めるとしよう……――記憶操作", tid: "ch06__b07_accept__04" },
  { se: "magic" },
  { fx: "flash" },
  { text: "シェル公爵の手が俺の頭を掴み、強く締め付ける。痛くはない、が……今までの記憶、見たことのある物も見たことの無い物も、ごちゃまぜになりながらフラッシュバックする。", tid: "ch06__b07_accept__05" },
  { text: "脳に尋常ではない負荷がかかっている。視界が明滅し、今が何時で此処が何処だか分からなくなる。駄目だ、耐えきれない。そのまま俺は、静かに意識を失った。", tid: "ch06__b07_accept__06" },
  { fade: "out" },
  { hide: "all" },

  // ---------------------------------------------------
  // Scene 19: recontract — 契約破棄と再契約 (EP107〜109)
  // ---------------------------------------------------
  { label: "recontract" },
  { bg: "fairy_celledge" },
  { fade: "in" },
  { comment: "EP107: クロセル視点 — 洗脳されたヤマト" },
  { bgm: "tension" },
  { pov: "crocell" },
  { text: "シェル公爵が手を離すと同時に、糸が切れるように地面に倒れ込んだヤマトに、私は駆け寄って声を掛ける。当然だが外傷はない。精神に強いショックを受けて一瞬意識を失っていたようだ。" },
  { text: "ヤマトは片手で頭を抑えながら、ゆっくりと立ち上がる。" },
  { chara: [
    { slot: "left",   id: "yamato",  expr: "normal" },
    { slot: "center", id: "shellmi", expr: "normal" },
    { slot: "right",  id: "crocell", expr: "serious" },
  ] },
  { name: "シェル公爵", who: "shellmi", expr: "normal", text: "さて、こんな物かな、気分はどうかね？ヤマトとやら" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "あぁ……全部……思い出した……実に良い気分だ……" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "成功したんですか？" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "もちろん、成功したさ。君達の予想通り、記憶操作を受けていたようだね、随分と乱雑に記憶が消去されていた、例えるならば鈍器で殴って記憶を飛ばすような荒療治だ、君の記憶を消した人物には、よほど時間が無かったんだろう" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "ありがとう、シェル様" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "くくく……礼には及ばないさ、私も面白い物が見れたからね" },
  { text: "ヤマトが転生者で、王国の指名手配犯で、聖教会に敵対する存在である事。それらを知られていたら、最悪、口止めが必要になる。" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "まさか……シェル公爵もヤマトの記憶を見たのか？" },
  { name: "シェル公爵", who: "shellmi", expr: "sad", text: "確かに私の記憶操作で他人の記憶を見る事も出来るが、今はやっていない、取り戻した部分の記憶が少し流れ込んできただけだ" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "……嘘はついていないようだな" },
  { name: "シェル公爵", who: "shellmi", expr: "normal", text: "仮に君達に都合の悪い事実を知ってしまったとしても、どうこうするつもりはないさ、私はフェアリーケレッジの外の世界に然程興味は無いんだ" },
  { name: "アカツキ", text: "取り敢えず……目標達成、で良いんですかね？" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "おう、俺は記憶を取り戻した、この世界に来てから、今に至るまで……全てのな" },
  { text: "少しだけヤマトの雰囲気が変わったようにも見える。なんだろう、胸騒ぎがする。本当にヤマトは記憶を取り戻して大丈夫だったのだろうか。" },
  { name: "屋敷の男", text: "用が済んだならさっさと出ていけ、シェル様は忙しいのだ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、分かった" },
  { text: "屋敷の男に催促され、ヤマトは｜暗幕《あんまく》を潜って聖堂から出ていく。続いて瀬野が出ていき、私とアカツキが残される。" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "無礼にも突然押しかけたのにも関わらず要望に応えて頂き、本当にありがとうございました" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "くくく……構わないと言っているだろう？この街は良い所だ、精々ゆっくりしていくと良い" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "はい、それでは失礼します" },
  { text: "深く一礼して、アカツキが出ていく。最後に残された私は、高い椅子に腰掛けるシェル公爵を見上げながら、見つめ合う。" },
  { chara: { slot: "center", id: "shellmi", expr: "smug" } },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "どうした？｜魔杖《まじょう》クロセル" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "いや、なんでもない……貴様が何か企んでいるように見えてな" },
  { name: "シェル公爵", who: "shellmi", expr: "sad", text: "分析の才能で私の心を読もうとしているようだが、無駄だよ、私は人間でも魔族でも無い、｜原初《げんしょ》の超越者……妖精だ" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "そのようだな、何か余計な事をしてみろ、私は貴様を許さない" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "おぉ怖い怖い、だがまぁ案ずる事は無いさ、私は君達に危害を加えるつもりは一切無いのだからね" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "……" },
  { text: "私はシェル公爵を睨み付けると、そのまま踵を返して聖堂を後にした。" },
  { hide: "center" },
  { hide: "left" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "はぁ……はぁ……" },
  { text: "だが、屋敷を出た途端、ヤマトは地に膝をついて肩で息をし始めたのだ。" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "どうしたのだ？ご主人は" },
  { name: "アカツキ", text: "さぁ……屋敷を出た途端苦しみ始めたので私もびっくりしました" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "いや、なんでもない……気にするな" },
  { name: "瀬野", text: "ヤマトの記憶について、僕と別れた後の事……聞かせて貰えるんだよね？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、望むなら聞かせてやろう" },
  { chara: [
    { slot: "center", id: "yamato",  expr: "normal" },
    { slot: "right",  id: "crocell", expr: "sad" },
  ] },
  { text: "そして宿に戻り、部屋の前。ヤマトは私に片手を差し出した。それは、私の部屋の鍵だった。" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ご主人？　これは？　……ははっ、何を言っているのだ、我はご主人と同じ部屋で良いと前から……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "一人部屋が嫌ならアカツキと寝ろ、俺を一人にしてくれ。あの方以外の人間と馴れ合うつもりはない、例えお前であってもな" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "なっ……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "じゃあな、おやすみ" },
  { text: "ヤマトは私に鍵を押し付けると、扉を締める。私を残して施錠される音が、寂しげに廊下に響いた。あれは一過性の物。一晩経てば元のヤマトに戻ってる。そう思ったのだが。" },
  { hide: "center" },
  { text: "翌日、昼を過ぎてもヤマトは部屋から出てこない。空間魔術で部屋に入ると、中は空。ヤマトは行方不明になっていた。" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "我を連れずに単独行動するなど普通ではない、何らかのトラブルに巻き込まれた可能性も……" },
  { name: "瀬野", text: "あはは……クロセルさんって、結構心配性なんだね" },
  { name: "アカツキ", text: "いやどう見ても心配しまくりじゃないですか、そこまで行くと一種の過保護ですよ？" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "うぬぬ……そんな事を言うなら我一人で探す！" },
  { name: "アカツキ", text: "ごめんなさい、私達もちゃんと探すのを手伝いますよ、私の直感も嫌な予感がすると告げてますし" },
  { text: "私はアカツキとゼノと手分けして、フェアリーケレッジを駆け回って捜索した。身体強化、視覚強化、嗅覚強化、触覚強化を同時に身体に付与する。この無尽蔵の魔力は何処から来ているのだろう。少なくとも魔術9の才能ではない。才能指数10クラスの力だ。" },
  { text: "胸騒ぎがする。ずっとヤマトと一緒に居た私には分かる。これは確実に異常事態だ。私は数回の跳躍で、シェル公爵の屋敷の前に降り立った。" },
  { name: "屋敷の信徒", text: "親方ーっ！空から女の子が！" },
  { name: "親方", text: "3秒で受け止めろ！" },
  { name: "屋敷の信徒", text: "もう着地してます！" },
  { text: "色々な色を帯びた視線を浴びながら、私は堂々と門を潜ろうとする。が――" },
  { name: "門番", text: "止まりなさい！此処はシェル様を信仰する者以外、立ち入り禁止だ！" },
  { text: "そういえば今日は、あの緑の服を着ていない。昨日はあれを着ていたから咎められなかったのだろう。私は門番に、｜緑衣《りょくい》を着ていない男――ヤマトが来ていないかを尋ねた。だが、現れた不審者はお前だけだと言う。" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "ふむ……そうか……" },
  { text: "街は隅々まで捜した。消去法で、ヤマトが居る可能性のある場所は此処以外に無い。ならば――中に入る手立てを講じるまでだ。" },
  { text: "私、というより魔剣の類には、人の姿に実体化する特性がある。モデルとなる服のイメージさえあれば、再度実体化するだけでどんな格好にもなれる。私に着替えという行為は必要ないのだ。" },
  { text: "一度杖の姿に戻り、緑衣を纏って再び実体化する。複雑な服ではない、実に簡単だ。こうして私は、堂々とシェル公爵の屋敷へと足を踏み入れた。" },
  { text: "そして私が見付けたのは――シェル公爵の屋敷、礼拝堂。緑衣を着て、｜暗幕《あんまく》に向かって祈りを捧げるヤマトの姿だった。" },
  { chara: { slot: "center", id: "yamato", expr: "serious" } },
  { name: "クロセル", who: "crocell", expr: "serious", text: "こんな所で何をしているのだ……アカツキやゼノが心配しているのだぞ" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "……｜邪魔《じゃま》だ。俺は今シェル様に祈りを捧げてるんだ、｜邪魔《じゃま》をするな" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "……は？" },
  { text: "覗き込もうとした私の顔に、ヤマトの平手が飛ぶ。ディザビリティで、ばしんと弾かれる。理解するのに、数秒を要した。" },
  { chara: { slot: "right", id: "crocell", expr: "angry" } },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "えっ、えっ！？えぇ！？何故だ、ご主人！頭がどうかしたのか！？" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "うるさい、集中が途切れる" },
  { text: "ヤマトは街の人と同じ緑の服装をして、シェル公爵に祈っていた。記憶操作による洗脳……？　街全体がシェル公爵の支配下にあったのだ。私はシェル公爵に向けて魔術を放った。が――" },
  { fx: "red" },
  { text: "｜暗幕《あんまく》の前に、人影が立ち塞がる。シェル公爵を庇い、膝から崩れ落ちたのは――全身に水の弾丸を受け、蜂の巣になったヤマトだった。" },
  { chara: { slot: "right", id: "crocell", expr: "sad" } },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "えっ……そんな……ご主人！" },
  { comment: "EP108: 契約破棄" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "ご主人！ごめんなさい……今治すから……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "近付くな！シェル様に危害を加えようとしたお前を俺は信用しない" },
  { name: "シェル公爵", who: "shellmi", expr: "normal", text: "ヤマトとやら、残念ながら私は回復魔術が使えないんだ、だからあれを使うと良い、一度見てみたかったんだよ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "――｜解除《アンロック》……回復魔術 ｜自己再生《セルフヒール》" },
  { se: "chime" },
  { fx: "clear-red" },
  { text: "才能指数10の回復魔術が、たちまちヤマトの全身の傷を再生する。一度きりの力を、こんな所で――。" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "ほう、これが才能指数10の力……圧倒的な能力、神の力というのは本当のようだ" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "ダメ！そんな安易に才能の開放を使っちゃダメだよ！才能指数10の回復魔術があればあと一回だけなら瀕死の人間を救えたのに……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "うるさい、俺の中ではシェル様が一番だ、お前の命令を聞く理由はない、そもそもお前の主人は俺だろう？俺の命令が何故聞けない？" },
  { chara: { slot: "left", id: "shellmi", expr: "smug" } },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "あぁ、それの事だが……ヤマト、お前に｜魔杖《まじょう》クロセルはもう不要だろう？契約を破棄したらどうだ？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "ありがたいお言葉、そうさせて頂きます――｜契約破棄《コネクト・キャンセル》" },
  { fx: "shake" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "なっ……ご主人！？本気で言ってるの！？ダメ！" },
  { text: "ぷつん……と何かが切れる感覚。私の身体と繋がっていた何かが切り離される。肉体を持って｜顕界《けんかい》しているだけで魔力が減っていく……私が特別だったんじゃない……契約者のヤマトが特別だったんだ……" },
  { text: "まずい……この状態で戦闘したら魔力が尽きる。温存しても半日と｜顕界《けんかい》出来まい。今すぐ誰かと再契約せねば、私は消える。" },
  { bgm: "sad2" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "私はお前を絶対に許さない！ヤマトの記憶を操作し、契約まで破棄させた癖に、傷付けるつもりがないだと……冗談にも程がある！" },
  { name: "シェル公爵", who: "shellmi", expr: "normal", text: "まぁ待つんだ、私は別にお前を傷付けたい訳じゃないんだ。さて……単刀直入に言うとしよう、私が本当に欲しいのは｜魔杖《まじょう》クロセル、お前だ。私と再契約しろ、そうすればこの男、ヤマトの洗脳を解いてやろう" },
  { text: "ヤマトは飽くまでも交渉材料、人質だ。もし契約してしまえば、私はシェル公爵に依存し、命令に逆らえなくなる。今のヤマトとほぼ同様の状態になる。" },
  { text: "妖精の寿命は無限のリソース。契約者がリソース切れで死に、契約が切れる事もない。破棄するにはヤマトがシェル公爵を説得するか、シェル公爵を殺すしかないのだ。" },
  { text: "その時、私はふと疑問に思う。ヤマトは私の事をどう思っているのだろう。私がシェル公爵の物になった時、彼は私を取り戻そうと｜奔走《ほんそう》してくれるのだろうか。" },
  { text: "それを望むのは、我儘な事なのだろうか。従者である私は、彼自身の幸福を優先するべきだ。私の事など忘れて、アカツキやゼノと三人でこれからも幸せに暮らす。そんな未来が、正しい在り方なのかもしれない。" },
  { chara: { slot: "right", id: "crocell", expr: "sad" } },
  { text: "気が付けば、私の頬には涙が流れていた。頭では分かっている。私のやるべき事は唯一つ。それでも、私の心はただ叫び続ける。ご主人の力になりたかった。ご主人の従者でありたかった。もっと一緒に……居たかった。" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "最初は嫌な主人だなとも思ったよ、やけに偉そうだし、直ぐに手を出すし、弱いし。でも皇帝に捕まって、助けに来てくれた時、私はご主人に一生仕えると決めたんだ" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "もう二度と、大切な主人を失いたくない。分かった……我は、｜魔杖《まじょう》クロセルは、シェル公爵、お前と契約する" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "おぉー、中々に早い決断だ、それは英断だぞ、何と言っても妖精は気まぐれだからね" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "こちらから出す条件は二つ、当初の予定通りヤマトの記憶を復元する、そしてお前の改変した記憶を元に戻す" },
  { text: "もう私に選択肢はない。これが最善だった。これ以外に、ご主人をシェル公爵の支配から解き放つ術は無い。私は私の忠義を尽くした、それだけで満足だ……。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "こちらは契約のスクロールです、魔術によって生み出した物でして、交渉内容を記し、両者のサインをする事で成立、書かれた条文を守らなかった場合、死の呪いが掛かります、条文は書いておきました" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "ほう、そんな物が、死の呪いは魔杖にも掛かるのか？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "はい、魔剣であろうと例外なく破壊されます" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "助かる、くくく……実に従順な眷属だ、手放すのが惜しいな" },
  { text: "ヤマトの差し出した「契約のスクロール」に、シェル公爵がサインし、私もサインした。これで全てが終わる……筈だった。" },
  { comment: "EP109: 再契約 — どんでん返し" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "先にご主人の記憶操作を行え、契約はその後だ" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "いや逆だ、先に契約して貰おうか、記憶操作はその後だ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "シェル様、条文では先に俺の記憶操作をすると書いてあります、順番通りで無ければ呪いが発動します" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "そうなのか？なら何故順番を逆に書かなかったのだ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "申し訳ありません、考えが至りませんでした" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "まぁいい、この契約のスクロールにサインした以上、約束を破る事は出来ないのだからな" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "私も暗幕の中に入れて、ヤマトの記憶が正しく戻ったか確認する" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "構わんよ、私は魔杖クロセルが手に入るならばそれでいいんだ" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "では今度こそ記憶操作だ、ヤマトとやら、頭を垂れよ……――記憶操作" },
  { pov: "yamato" },
  { text: "条文に従い、先にヤマトの記憶が復元される。前回は意識を失ったが、今度は意識を保てたらしい。ヤマトは頭を抱えた状態で、ゆっくりと立ち上がる。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "なるほど、これが本当の俺の記憶か……" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "ご主人……我が分かるか？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……まぁな" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "待ってくれシェル公爵、最後に少しご主人と話がしたい" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "あぁ構わんよ、これが魔杖クロセルとヤマトの別れになるのだからね" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "ご主人、こういう時、何と言って良いのか……" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "クロセル……その……なんだ……" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "良いのだ！ご主人は強い、私なんかよりずっとな、それに今のご主人には仲間が居る、だから大丈夫、一人でも大丈夫" },
  { text: "一人でも大丈夫。それは俺に対しての言葉じゃない。クロセルが自分自身に言い聞かせているのだと、勘の悪い俺でも分かった。クロセルの足元に、ぽつぽつと雨粒の跡が生まれていく。" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "でも……私はご主人の力になりたかった、ご主人の従者でありたかった、もっと一緒に……居たかった！" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "口調崩壊してないか？" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "うるさい！人が真剣に話しているというのに……ご主人は……何とも思わないのか？" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "いや、俺も別にお前の事は嫌いじゃないが……" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "そっか……昨日からさっきまでのご主人の態度、嫌われたのかと思って……怖かった。でも違うんだね、あれはシェル公爵に操られてたからで……本当は嫌いじゃないんだ、良かった……" },
  { text: "クロセルはゆっくりと顔を上げると、涙に濡れた顔で、俺に向けて笑ってみせた。そして、シェル公爵に向き直る。" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "くっくっくっ……感動の再会といきたい所だが、残念ながらお別れの時間だ、約束通り私と契約してもらおう、｜魔杖《まじょう》クロセル" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "――我は契約に従い……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "待て、クロセル。おい、それ貸せ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "クロセル……そこまで字、上手くないんだな" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "うるさいぞ！そんな事を言う為に止めたのか！？" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "冗談だ、取り敢えず説明が面倒だから二人には手っ取り早く状況を理解して貰おう" },
  { text: "ヤマトは私の手から契約のスクロールを奪い取ると、両手で顔の前に掲げ――" },
  { wait: 600 },
  { fx: "flash" },
  { text: "――そのまま真っ二つに破いた。" },
  { name: "クロセルとシェル公爵", text: "「「はああああああ！？」」" },
  { text: "こんな修羅場でも、敬虔な村人達はシェル公爵に祈りを続けている。頭がおかしい――いや、おかしくされているのだから仕方ない。" },
  { fx: "shake" },
  { name: "クロセル", who: "crocell", expr: "dizzy", text: "ご主人、何をしているのだ！？そんな事をしたら！最悪二人共死ぬ可能性もあるのだぞ！？" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "あぁ、そんな事は無いから安心しろ。契約のスクロールなんてあるわけねぇだろ、お前が知らないようなマジックアイテムを俺が持っていると本気で思ったのか？" },
  { chara: { slot: "left", id: "shellmi", expr: "angry" } },
  { name: "シェル公爵", who: "shellmi", expr: "angry", text: "何故だ？私の記憶操作は完璧だったはず、お前にそれに対抗出来る才能など……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "下僕の言う事を素直に信じたら痛い目を見るって話だよ" },
  { name: "シェル公爵", who: "shellmi", expr: "angry", text: "私の記憶操作に！どうやって対抗したというのだ！" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "お前に説明する義理はない、敵に手の内を明かすわけ無いだろ" },
  { text: "俺は冷たく吐き捨てると、近くの時計を一瞥する。回復魔術の解除からの経過時間を考えると……そろそろだろう。" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "演技だった……と……？" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "いや、半分は本気だ、記憶操作には対抗したが、完全ではなかった、俺はシェル公爵の命令に逆らえなかったし、俺の過去の記憶は取り戻されていなかった。だから俺は従順でありながら、なんとか寝首を掻く必要があったって訳だ" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "クロセル、俺はお前のなんだ？" },
  { chara: { slot: "right", id: "crocell", expr: "blush" } },
  { name: "クロセル", who: "crocell", expr: "sad", text: "ご主人……だった、大切な人……" },
  { chara: { slot: "center", id: "yamato", expr: "smirk" } },
  { cg: "cg_recontract" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "――再契約だ、クロセル！お前は俺の物だ、誰にも渡さねぇ！" },
  { fx: "flash" },
  { bgm: "romance" },
  { chara: { slot: "right", id: "crocell", expr: "laugh" } },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "っ！我は契約に従い、貴方の剣となりその生命を守ろう" },
  { text: "契約は成立した。クロセルの気配が強くなったのを感じる。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "クロセル、任せて良いな？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "無論" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "命令は要らないな" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "あぁ、ご主人の指揮は最弱無才だからな！" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、じゃあ後は頼んだ、俺の最強の｜魔杖《まじょう》……" },
  { text: "\"致命的なエラーが発生した為……破損箇所のある才能を破壊します『回復魔術0』\"――頭と胸に激痛。" },
  { text: "そして今の俺には\"精神汚染耐性\"のディザビリティがある、つまり二度と記憶操作、洗脳、催眠術の類に抵抗する事は出来ない。だが自然と不安はなかった。クロセルは絶対に俺を守ってくれる、そんな確信があった。" },
  { fx: "shake" },
  { name: "シェル公爵", who: "shellmi", expr: "angry", text: "人間如きに……この私が嵌められただと……？許せない、ぐぬぬぬ……" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "貴様の才能は既に分析済みだ、戦闘系の才能はない、大人しく諦めろ" },
  { text: "足に力が入らなくなり、視界が傾き降下していく。意識が闇に落ちる｜刹那《せつな》、俺は頭に仄かな温もりを感じた。" },
  { cg: null },
  { fade: "out" },
  { hide: "all" },
  { fade: "in" },
  { bgm: "romance" },
  { chara: [
    { slot: "center", id: "yamato",  expr: "normal" },
    { slot: "right",  id: "crocell", expr: "normal" },
  ] },
  { name: "クロセル", who: "crocell", expr: "normal", text: "おはよう、ご主人" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "クロ……セル……？……なんで俺はお前に膝枕されてるんだ？" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "嫌だったか？くくく、嬉しい癖に" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "馬鹿、んなわけねぇだろ、んで？シェル公はどうなったんだ" },
  { text: "クロセルが指差した先には、2m程度の透明な氷の檻があり、その中でシェル公が体育座りをしてクロセルを睨み付けていた。接触されると危険だから閉じ込めておいたらしい。" },
  { chara: { slot: "left", id: "shellmi", expr: "sad" } },
  { name: "シェル公爵", who: "shellmi", expr: "sad", text: "ぐぬぬぬ……屈辱だ……高貴な私をこんな狭い場所に閉じ込めるなど……" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "うむ、我に良い案があるのだ。才能の解放を使ってシェル公爵を記憶操作する。フェアリーケレッジの人達をシェル公の洗脳支配から救う事が出来るのだぞ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "お前、俺がシェル公に記憶操作された時にどう思った？人にされて嫌な事はしちゃいけないって習わなかったのか？" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "ご主人が道徳を語るのか？でもでも、これは人の為になる事なのだぞ、フェアリーケレッジの人達を救う事が出来る" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "｜意趣返し《いしゅがえし》って訳か、まぁ……それが最善か" },
  { text: "俺は片手でクロセルの頭をどけて起き上がる。そして、ふと気付いた。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "……服が着替えてある" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "血まみれだったからな、着替えはご主人の部屋から持ってきたぞ。ゼノとアカツキはまだ帰ってきていないからな" },
  { text: "俺はクロセルの頭に｜拳骨《げんこつ》を飛ばす。ばしんと弾かれる。こいつに裸を見られたのは……まぁ俺の方は然程気にする事でもないが、何も気にしていないような素振りに腹が立つ。" },
  { hide: "all" },

  // ---------------------------------------------------
  // Scene 20: false_god_truth — 偽りの神 (EP110〜113)
  // ---------------------------------------------------
  { label: "false_god_truth" },
  { pov: null },
  { bg: "fairy_celledge" },
  { fade: "in" },
  { comment: "EP110〜111: ダーリン化と街の解放" },
  { bgm: "daily" },
  { text: "クロセルが氷の檻を解くと、俺はシェル公に迫る。クロセルとの迫真の演技で、シェル公は何か変な方向へと勘違いしたようだ。" },
  { name: "シェル公爵", text: "やめろ！来るな！妖精は繁殖能力が無いのだから、そんな事をしても無駄だぞ……！" },
  { name: "ヤマト", text: "安心しろ、強引に植え込んでやるよ" },
  { name: "シェル公爵", text: "こいつは変態なのか！？" },
  { text: "俺はシェル公を押し倒し、床に手を付いて顔を近付ける。才能の解放を使い、記憶操作の才能をインストールする。才能指数10であれば、触れる必要もない。" },
  { name: "ヤマト", text: "――記憶操作" },
  { se: "chime" },
  { text: "逆らわないように、俺の言う事を聞くように、あとは最低限の道徳ってとこか。経験則だが、新たに別の記憶を入力する時の方が負荷は大きい。……つもりだったのだが。やり過ぎたらしい。" },
  { text: "才能の解放を使った以上、俺も数分後には意識を失う。シェル公をソファに寝かせ、俺もソファに腰掛けると、なんだか強い視線を感じる。" },
  { name: "ヤマト", text: "あぁ、クロセル。アカツキとゼノに伝言を頼めるか。……心配掛けて悪かった、ってな" },
  { name: "クロセル", text: "その台詞は！我にこそ！言うべきだろうが！" },
  { se: "slash" },
  { text: "クロセルの華麗なグーパンが顔面に叩き付けられる。グーは……ダメだろ……。俺はそう呟くと、そのまま地面にキスをして、再び意識を失った。" },
  { hide: "all" },
  { bg: "fairy_celledge_inn" },
  { text: "そして、再契約から数時間の後。俺達は宿の一室に一堂に会していた。だが……記憶操作は完璧だったが、その、なんというか……やり過ぎた。" },
  { chara: [
    { slot: "left",   id: "shellmi",  expr: "love" },
    { slot: "center", id: "yamato",   expr: "sad" },
    { slot: "right",  id: "akatsuki", expr: "jito" },
  ] },
  { name: "シェル公爵", who: "shellmi", expr: "love", text: "ダーリン♡" },
  { name: "瀬野", text: "あはは……ヤマト、モテモテだね……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "おい……いい加減離れろ……視線が痛い、主にクロセルとアカツキの" },
  { name: "クロセル", text: "ご主人は我の物だぞ！触れて良いのは我だけだ！" },
  { name: "シェル公爵", who: "shellmi", expr: "normal", text: "いーやーだ！ダーリンは私の男なの！ね？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "いや違うが、あとクロセル、俺はお前の物でもないからな" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "本当にどうしようもなく救いようのないロリコンだったんですね、ヤマトさん" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "やり過ぎただけだ！記憶操作がディザビリティになった以上、やり直しも出来ねぇんだよ！" },
  { text: "俺の命令に逆らえない程度に好意を抱くように調整したはずなのだが、その結果がこうだ。記憶操作をやり直したり出来ないか、と聞いたが、ディザビリティになった以上、似たような才能を使っても失敗するらしい。" },
  { text: "困っていると、瀬野が珍しく冴えた意見を出した。" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "保護というか誘拐ですよね？" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "ちょっぴりどころかほぼ別人になってるのだが？" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "うるせぇ！というか提案したのお前だろクロセル！" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "ここまでやれとは言っていないぞ！" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "取り敢えず状況は理解しました、それで……これからどうするんですか？" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "シェル公に街の人の記憶操作を解除させて平和的に町を治めて貰おうかと……思ってたんだが……" },
  { name: "シェル公爵", who: "shellmi", expr: "love", text: "やーだ、私はダーリンと一緒に居るの！" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "とまぁ、そうする場合。俺は一生をこの街で終える事になりそうなんだ" },
  { name: "瀬野", text: "ボルト君を頼ったらどうかな。もし記憶操作を解いたりしたら、今後のシェル公の統治に反発が出る可能性もあるよね、だからフェアリーケレッジの統治は別の人間に委任するのが一番だと思うんだ。ボルト君は｜公主《こうしゅ》であったドラゴファースト家の人間だ、それならこの町の人間も納得してくれるんじゃないかな" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "それ、良いと思いますよ。ボルトさんならきっとやってくれます" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "なるほど。アカツキ、転移魔術でボルトを連れてこれるか？" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "大丈夫だと思います、ボルトさんが聖協会に捕まってたりしたら厳しいと思いますが" },
  { name: "クロセル", text: "ご主人……アカツキに頼りっぱなしだな" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "うるせぇ、いつもの事だろ" },
  { text: "吐き捨てるように言って、俺は目を逸らす。俺とて、アカツキとクロセルに頼りっぱなしなのは理解している。だから感謝もしているつもりだ。言葉や態度に出すのが気恥ずかしいだけであって。" },
  { text: "アカツキと瀬野が転移魔術で聖都へ飛び、留まっていたボルトとファイを無事に連れ帰ってきた。ボルトは「これもドラゴファースト家の復興の第一歩になるかもしれません」と快諾してくれた。シェル公には屋敷に戻り事態を収拾するよう命じておく。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "じゃあ命令だシェル公、屋敷に戻って事態を収拾しろ、明日屋敷に集まるように街の人全員に伝えるんだ" },
  { name: "シェル公爵", who: "shellmi", expr: "love", text: "ダーリンの命令とあらば必ずや、任せてくれたまえ" },
  { text: "シェル公は立ち上がると、俺に向けて小さくウインクをして部屋から出て行った。そんなシェル公を終始睨み付けていたクロセルが、小さく溜息を吐く。" },
  { hide: "left" },
  { chara: { slot: "left", id: "crocell", expr: "surprised" } },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "どうしたクロセル、ライバルが現れて焦ってるのか？" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "あぁ……って！そんな訳無いだろう！我は別に妬けてなどいない！" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "安心しろ、俺の相棒はクロセル、お前だけだ" },
  { name: "クロセル", who: "crocell", expr: "blush", text: "なっ……う、うん、そうだぞ、良く分かっているではないか！" },
  { hide: "all" },
  { text: "その夜、俺とクロセルはベッドに身を寄せて眠る。クロセルが俺の腹の上に飛び込んできたのはご愛嬌だ。" },
  { chara: [
    { slot: "center", id: "yamato",  expr: "normal" },
    { slot: "right",  id: "crocell", expr: "normal" },
  ] },
  { name: "クロセル", who: "crocell", expr: "normal", text: "｜怒涛《どとう》の二日間だったな" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "まだ終わってないぞ、大変なのはこれからだ" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "そう言えばご主人、記憶が戻ったのだろう？その話はしてくれないのか？" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "あぁ、それもあるな、だがちょっと不可解な事があるというか、俺も理解出来ない点が幾つかあるんだ、まぁこの件に収拾が付いたらみんなの前で話すよ" },
  { text: "そう、俺の記憶は戻った。だがシェル公の記憶操作は完璧なはず。それでも何故か\"存在する筈の一部の期間\"の記憶が欠落しているのだ。これが何を意味するのか、今の俺には分からない。" },
  { text: "脳裏で、あの時のエルの言葉が再生される。「私とヤマト様は殺し合う関係、ヤマト様はこれからきっと記憶を取り戻す、そして私を殺しに来る、そうすれば……また会えるよ」――俺は神を殺す存在。いや、違うな。正確に言えば……" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ご主人、おやすみ" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "あぁ、おやすみクロセル" },
  { text: "眠ろう。今はただ。俺の心は揺れ動いている。エルや勇者達と刃を交える未来など、考えたくはないんだ。" },
  { hide: "all" },
  { bg: "fairy_celledge" },
  { text: "だが翌朝、屋敷へ向かうと、俺とシェル公は武装した公国兵に囲まれていた。シェル公が「変態の大罪人だ、引っ捕らえよ！」と叫んでいる。" },
  { chara: [
    { slot: "left",   id: "shellmi",  expr: "angry" },
    { slot: "center", id: "yamato",   expr: "serious" },
    { slot: "right",  id: "crocell",  expr: "normal" },
  ] },
  { name: "クロセル", who: "crocell", expr: "serious", text: "これは……ご主人が悪いな。ご主人のディザビリティは何だ。指揮のディザビリティだ" },
  { text: "そうだ、俺は\"俺の命令には絶対服従\"という記憶操作をシェル公に施した。つまり……あいつに何かを命令すると全て失敗する。指揮のディザビリティ――俺の命令を承諾した者は必ず失敗する。だが、アカツキ曰く、これは逆に最強の才能だという。" },
  { name: "アカツキ", text: "命令に従うと絶対に失敗するという特性を利用するんです、まぁ試しにシェル公爵に『この場に居る全員に誤解を広めろ』とでも命令してみてください" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "シェル公、命令だ、この場に居る奴らに誤解を広めろ、今以上に俺達を憎むように" },
  { name: "シェル公爵", who: "shellmi", expr: "angry", text: "この者達は神にも等しきこの私を誘拐し、神聖なこの身体を犯した。変態の大罪人だ、今すぐ引っ捕らえよ！" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "おいシェル公。そこまで言えとは言ってないぞ" },
  { text: "シェル公が命令に従い……そして確実に失敗する。兵士達はざわめき、武器を下ろして包囲を解いていった。なるほど、この\"裏技\"か。" },
  { name: "アカツキ", text: "ヤマトさんの命令に従った場合、絶対に失敗するんです。今のシェル公はヤマトさんの命令に一片の疑問や不信感を抱くことはない。つまりシェル公に対してどんな事でも失敗させる事が出来るんです" },
  { text: "要は剣術のディザビリティで剣戟を防いだり、傷害のディザビリティで立体機動を取れるのと同じだ。ディザビリティも、使い方次第では優秀な才能となり得る。大失敗をしたと思っていたが、怪我の功名と言うべきか、結果として良い方に転がったので良しとしよう。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "よし、じゃあシェル公、命令だ、この街の人全員に記憶操作を施せ、その際に、絶対に記憶操作を解くな" },
  { name: "シェル公爵", who: "shellmi", expr: "love", text: "あぁ、任せてくれたまえ、ダーリンの頼みとあらば必ずや" },
  { name: "シェル公爵", who: "shellmi", expr: "sad", text: "ふむ……何故だ？絶対に解けないように記憶操作を施しているのに……記憶操作が解けてしまうようだ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "気にするな、続けて良いぞ" },
  { name: "シェル公爵", who: "shellmi", expr: "sad", text: "悪いね、ダーリン、力になれなくて……" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "これなんか罪悪感が湧いてくるんだが" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "これ以外に方法が無いので仕方ないが、確かに我だったら心が折れてるな……" },
  { name: "アカツキ", text: "……｜健気《けなげ》に命令に従ってるのに絶対に成功出来ないのって……少し残酷ですね" },
  { text: "記憶操作が解けた街の人達は混乱状態に陥るが、その記憶が消える訳ではない。アカツキと瀬野が順番に屋敷の外に連れ出していく。そして外では、Vことボルトの演説が響いていた。" },
  { name: "V", text: "聞いて下さい。今まで、フェアリーケレッジは、洗脳じみた手法で支配されてきました。皆さんはその被害者なのです。僕はボルト・ドラゴファースト、このアステカス公国を守る使命を託された人物です。僕はこの街をシェル公爵の支配から解放する為にやって来ました" },
  { name: "V", text: "僕はこの街に自由を齎します。そして、このアステカス公国を復興します。その為に、どうか僕に協力してはくれないでしょうか。今すぐにとは言いません、皆さんの今までの暮らしを大きく変えるような改革もしません。僕は街の人、この国の人の意見を積極的に取り入れ、今よりもっと良いフェアリーケレッジを作りたいと考えています。その為に……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "選挙の演説を聞いてるみたいだ……まぁ、街の人の反応は良いみたいだな" },
  { text: "街の人の反応は良いようだ。記憶操作の解けた状態で考えれば、シェル公爵のやり方はおかしいのだ。ボルトと共に連れてきた妹のファイは、危険を避ける為クロセルの元で預かっている。一言も言葉を発する事なく、呆然と上を見上げていた。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "ボルトはどうやってこいつと意思疎通を取ってるんだ？俺こいつの声すら聞いたこと無いんだが" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ご主人は怖いからな……ご主人の前だと話せないのだろう。アカツキとかとは普通に話していたぞ？" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "嘘だろ……" },
  { text: "ファイは俺の前でだけ一言も喋らないらしい。嫌われているのか、怖がられているのか。別に、慣れっこだ。気にしてなどいない。うん。" },
  { name: "シェル公爵", who: "shellmi", expr: "sad", text: "ダーリン、街の人全員に記憶操作を施そうとして……全員失敗した" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "これで全員か？よし、よくやった" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "シェル公、お前は俺の物だな？" },
  { name: "シェル公爵", who: "shellmi", expr: "love", text: "……？あぁ、私はダーリンだけの物だが" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "お前の財産、屋敷、そしてお前自身は全て俺の物だ、俺がどう使っても構わないな？" },
  { name: "シェル公爵", who: "shellmi", expr: "love", text: "あぁ、もちろんだとも" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "……最低な発言が聞こえるんですが" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "シェル公、お前の財産及びフェアリーケレッジの統治権をボルトに譲る、分かったな" },
  { text: "アカツキとクロセルから軽蔑の視線を感じる。悪者になるのは慣れてるが、この視線だけはどうも慣れない。これも街の人を救う為だ……その為には俺が悪者にならないといけないのさ。" },
  { name: "シェル公爵", who: "shellmi", expr: "love", text: "ふむ……構わないよ、私にはダーリンが居ればそれで十分だからね" },
  { text: "こうして街全員の洗脳は、一人残らず解除され、街の人々は新たな統治者ボルトを受け入れた。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "ファイとシェル公爵を連れてると、アカツキが母親のように見えるな" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "妖精は成長しないらしいからな、残念だ" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "何が残念なのか説明して貰えるか？ご主人" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "……冗談だ、目が怖いぞクロセル" },
  { text: "割と本気で殺意を感じた。気のせいだと信じたい。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "じゃあアカツキはシェル公とファイを連れて帰ってろ" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "分かりました、ヤマトさんとクロセルさんは？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "ボルトが心配だからな、一応様子を見て、一段落付いたら戻る" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "分かりました" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "当然だが、シェル公は部屋から出すなよ？" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "分かってますよ、では" },
  { hide: "left" },
  { text: "アカツキはシェル公爵とファイの手を掴むと、眩いばかりの光を放ちながら転移して消えた。そして俺はクロセルと共に、ボルトの元へと向かった。" },
  { hide: "all" },
  { bg: "sen_mansion" },
  { comment: "EP112: 神を殺して神になる — 神戦の記憶" },
  { bgm: "mystery" },
  { text: "アリエルツフィルに帰還した俺達は、セン公爵の応接間で、取り戻した記憶の全てを語る事になった。もちろん、シェル公も連れて。" },
  { name: "セン公爵", text: "くっ……くくく……いやなに、まさかあのシェル公爵を逆に記憶操作して懐柔するとはね、驚かされる。結果論とは言えど、君の働きには感謝するよ" },
  { name: "アカツキ", text: "これで三大公爵は｜破綻《はたん》、今後はドラゴファースト家とセン家の二大公爵家がアステカス公国を統治していく事になるんですね" },
  { name: "セン公爵", text: "そうなるね。これで次期｜公主《こうしゅ》は決まったような物だが……些末な事だ。アイシィには借りがある" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "シェル公が変な気を起こさなければもう少し早く話せたんだけどな" },
  { name: "シェル公爵", text: "あの時の私はどうかしていたのだよ、本当にすまないと思っている" },
  { name: "アカツキ", text: "どうかしているのは今の方だと思いますけどね……" },
  { text: "ぼそりとアカツキが小さく呟く。まぁ御尤もな事だ。この件に関しては全面的にクロセルに責任があるので俺は何も言わないことにする。" },
  { chara: { slot: "center", id: "yamato", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "俺は神になる為に教国へと向かった。この世界で神が神足り得るのは、その身に宿した7つの権能があるからだ。俺は神からそれを奪おうとした" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ぷっ……あはっ、あははははは" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "おい殴るぞクロセル" },
  { name: "セン公爵", text: "神になるというのは、この世界で一番強い存在になる、という意味合いで間違ってないのかな？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "それもあるが、それだけじゃない。俺はこの世界最強の存在だった、認識｜攪乱《かくらん》と風操作の才能で上層に侵入した、教皇は偶然不在でな" },
  { hide: "all" },
  { bg: "arcadia_upper" },
  { bgm: "battle" },
  { pov: { name: "ヤマト", color: "#BDC3C7" } },
  { text: "――一年前。聖域での、神との一騎打ち。" },
  { chara: [
    { slot: "center", id: "yamato",     expr: "smirk" },
    { slot: "right",  id: "el_goddess", expr: "normal" },
  ] },
  { name: "神", who: "el_goddess", expr: "normal", text: "何者ですか？" },
  { name: "過去のヤマト", who: "yamato", expr: "serious", text: "俺はヤマト、この世界の神になる男だ" },
  { name: "神", who: "el_goddess", expr: "normal", text: "イヴ！誰かイヴを呼びなさい！侵入者ですよ！" },
  { name: "過去のヤマト", who: "yamato", expr: "smirk", text: "無駄だ、防音結界を張ってある" },
  { name: "神", who: "el_goddess", expr: "smile", text: "何が目的……はもう言いましたね、私から権能を奪うんですか？" },
  { name: "過去のヤマト", who: "yamato", expr: "serious", text: "あぁ、神については色々と調べさせて貰った、お前を殺し、権能を奪う" },
  { name: "神", who: "el_goddess", expr: "sad", text: "はぁ……権能は殺さずとも奪えますよ" },
  { name: "過去のヤマト", who: "yamato", expr: "angry", text: "知っている。だが、お前を殺すのはもう一つ理由があるんだ、俺はさながら正義のヒーローだ、ファーストミッションは……――偽りの神を堕とす事" },
  { name: "神", who: "el_goddess", expr: "normal", text: "過激ですね。その黒髪、転生者ですか" },
  { name: "過去のヤマト", who: "yamato", expr: "normal", text: "ん？お前が転生させたんじゃないのか？" },
  { name: "神", who: "el_goddess", expr: "normal", text: "確認ですよ確認、それで……戦うんですか？ヤマトくん、貴方は間違っています" },
  { name: "過去のヤマト", who: "yamato", expr: "serious", text: "間違ってるのはお前の方だ、俺はお前をこの世界から追放する" },
  { name: "神", who: "el_goddess", expr: "normal", text: "無駄です、そんなことをしたらこの世界は滅びるんですよ？" },
  { name: "過去のヤマト", who: "yamato", expr: "angry", text: "それは違う、俺は知っているんだ、お前が世界を欺いた偽物の神だということを！" },
  { name: "神", who: "el_goddess", expr: "smile", text: "……証拠はあるのですか？" },
  { name: "過去のヤマト", who: "yamato", expr: "serious", text: "――無い、その惚けた口調が他の何よりも確かな証拠だ！" },
  { name: "神", who: "el_goddess", expr: "sad", text: "残念です、私と貴方は同じ存在、分かり合えると思ったのですが" },
  { name: "過去のヤマト", who: "yamato", expr: "angry", text: "俺がお前と同じだと？" },
  { name: "神", who: "el_goddess", expr: "normal", text: "……喋りすぎましたね、では始めましょう。――｜創造《ワールドクリエイト》！" },
  { fx: "flash" },
  { text: "ヤマトの剣が、何か硬い物に弾かれる。それは少女の剣ではない。空間その物が、攻撃を拒むかのように立ち塞がる。" },
  { name: "過去のヤマト", who: "yamato", expr: "serious", text: "瞬時に不可視の障壁を生み出したか、才能指数10のルールが通用しない、それはつまり……神の権能の一つか" },
  { name: "過去のヤマト", who: "yamato", expr: "smirk", text: "だが今ので分かった、お前自身の才能は大した事無い、神の力は相殺されている、故に権能で生み出した障害物は物理的に上位の攻撃を加えれば破壊できる" },
  { name: "神", who: "el_goddess", expr: "blank", text: "この権能を舐めて貰っては困ります、生み出せる物は文字通り……無限ですよ" },
  { text: "少女が一瞬にしてヤマトの懐に潜り込み、心臓目掛けて突き上げる。が、ヤマトは風操作の才能で空中を自在に動き、少女の背後に回って剣を振り下ろす。" },
  { text: "キンキンキンキン！　どんな硬い障壁であろうと、この男に貫けない道理はない。それが、全ての才能という名の可能性を持つ彼の力だ。" },
  { name: "神", who: "el_goddess", expr: "blank", text: "何度でも展開出来ると言ったはず！" },
  { name: "過去のヤマト", who: "yamato", expr: "smirk", text: "権能による物質の展開には0.03秒掛かる、俺の剣速はそれより速い、一度目は気付かなかったが、二度目は……" },
  { text: "横薙ぎの一閃が、神の少女の身体を切り裂いた。だが、間合いが甘かった。致命傷には至らない。" },
  { name: "過去のヤマト", who: "yamato", expr: "serious", text: "まだ抵抗するか" },
  { name: "神", who: "el_goddess", expr: "smile", text: "私にとっては実に有意義で、甘美な時間ですが……幸せな時は有限ですので" },
  { chara: { slot: "right", id: "el_goddess", expr: "blank" } },
  { name: "神", who: "el_goddess", expr: "sad", text: "――｜能力封印《スキルロック》・｜才能《アビリティ》" },
  { fx: "flash" },
  { chara: { slot: "center", id: "yamato", expr: "surprised" } },
  { name: "過去のヤマト", who: "yamato", expr: "sad", text: "は……？神の権能にそんな物があったのかよ……" },
  { name: "神", who: "el_goddess", expr: "smile", text: "私の勝ちですよ、もし降参するのなら、命だけは助けてあげても良いでしょう" },
  { name: "過去のヤマト", who: "yamato", expr: "angry", text: "くそっ……舐めた真似をしやがって！" },
  { text: "手負いの少女が剣を振る。その一振りが、易々とヤマトの｜剣戟《けんげき》を防いだ。才能指数10の｜剣戟《けんげき》を、神の権能を抜きにして防いだのだ。ヤマトが才能指数10の力を失った事を意味する。" },
  { name: "神", who: "el_goddess", expr: "smile", text: "終わりにしましょう、ヤマトくん" },
  { name: "過去のヤマト", who: "yamato", expr: "surprised", text: "っ……これは……" },
  { name: "神", who: "el_goddess", expr: "smile", text: "この世界のルールです、才能の無い者は、才能を持つ者に勝つ事は出来ない！つまり！今やお前は！" },
  { name: "過去のヤマト", who: "yamato", expr: "angry", text: "黙れ……" },
  { wait: 600 },
  { name: "神", who: "el_goddess", expr: "smile", text: "――無能だ" },
  { fx: "shake" },
  { name: "過去のヤマト", who: "yamato", expr: "angry", text: "嫌だ！くそっ……俺は……お前の思う通りには……ならない！" },
  { text: "全才能の封印。最強の男は、一瞬にして最弱になった。今のヤマトが、神に勝てる可能性は、恐らくゼロに等しいだろう。だが、その時――ヤマトの頭の中にノイズが走る。まるで何かが見えているのか、神とは見当違いの方向に視線を向け、硬直する。" },
  { name: "過去のヤマト", who: "yamato", expr: "smirk", text: "――｜解放《リベレーション》" },
  { fx: "flash" },
  { se: "slash" },
  { text: "カクン、と力なく頭を垂れたかと思えば、気配が変わる。まるで別人のような目つきで、ヤマトは少女を睨み付けた。" },
  { name: "過去のヤマト", who: "yamato", expr: "smirk", text: "やっと見つけたんだ、逃がす物か……！" },
  { text: "ヤマトは剣を構え、｜怒涛《どとう》の勢いで突貫する。次の瞬間、ヤマトの剣は神の防御をすり抜けるかのように手を離れ、そのまま少女の胸元を大きく貫いた。何が起きているのか、少女には理解出来なかった。" },
  { name: "神", who: "el_goddess", expr: "sad", text: "まずい……致命傷だ……誰か……ごほっ……クリスタを……" },
  { name: "過去のヤマト", who: "yamato", expr: "serious", text: "終わりだ、偽物の神" },
  { text: "ヤマトは剣を拾い上げ、再び倒れ伏した神の前に立つ。両手で剣を握り、止めとばかりに振り下ろそうとした。が、その瞬間、ヤマトが剣を取り落とし、両手で胸と頭を押さえる。" },
  { name: "過去のヤマト", who: "yamato", expr: "angry", text: "ぐっ……があああああああ！？これが……代償かああああああ！？" },
  { name: "神", who: "el_goddess", expr: "blank", text: "それ以上は……させない……｜能力封印《スキルロック》・｜記憶《メモリー》" },
  { text: "今までの記憶が、次々と消えていく。こうして俺は記憶と才能を封じられ、敗北したのだ。" },
  { name: "神", who: "el_goddess", expr: "smile", text: "やはり付け焼刃では勝てないか……仕切り直しだ……三度目は無い" },
  { hide: "all" },
  { pov: null },
  { bg: "sen_mansion" },
  { comment: "EP113: 偽りの神 — 最終決戦への決意" },
  { bgm: "mystery" },
  { chara: [
    { slot: "left",   id: "akatsuki", expr: "serious" },
    { slot: "center", id: "yamato",   expr: "normal" },
    { slot: "right",  id: "crocell",  expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "俺は神になる為に教国へと向かった。この世界で神が神足り得るのは、その身に宿した7つの権能があるからだ" },
  { name: "瀬野", text: "7つの権能？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "第二権能『神格移譲』第三権能『使徒命令』第四権能『祝福移譲』第七権能『能力封印』と……俺が知ってるのはこれだけだな。エルが魔王戦前に上層に行ったのは、第四権能を取り戻す為だったんだ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そうだな、俺の才能が全て封印されてるのも神の権能の力だ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "神の封印を破って才能を行使できるのは、何なんですか？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "わからん、神の封印が不完全なのか、或いは何らかの要因があるのか……まぁ今は置いておこう" },
  { text: "才能を解放する力。あれが何なのか、未だに俺も分からない。気合や根性、少年漫画のような理由であんな都合の良い力が使える筈もない。何か理由がある筈なんだ。それを忘れてはいけない、そんな気がしている。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "幸運にも教皇の部屋を見つけてな、そこに一冊の本が置いてあった。Cynthia Chronicle、表紙にはCCと大きく書かれていた" },
  { name: "瀬野", text: "幸運の才能、だろうね。僕と一緒に旅をしていた時も、賭場で荒稼ぎしてたし" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうそう、最初は奪った物が元手だったが、その先はちゃんと自力で手に入れた金なんだぞ" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "賭け事も実質相手から奪ってるのと同じじゃないですかね……" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "CCだと！？この世界には｜原初《げんしょ》の妖精が記したとされる二つの記録書物が存在する。一つが魔術全書、Magic Manuscript……通称MM。そしてもう一つが聖典、Cynthia Chronicle、通称CC。この世界に二つとして存在しない伝説の品だ" },
  { name: "瀬野", text: "有名な話だよ。千年前、神を巡った戦争でCCは失われたとされていたが……" },
  { name: "シェル公爵", text: "まさかイヴ・エンドが隠し持っていたとはね、道理で私の情報網を持ってしても見つからない訳だ" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "因みに、MMは王国の手で保管されている、その前は魔王クロセル、つまり我が所有していた" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "勇者キュリオスが王国に持ち帰ったんだな" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "うむ、そうなっている筈だ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "CCの内容に関してだが、神の継承は第二権能で記憶や人格と権能を移譲する事で行われている、そして神の権能を宿した肉体は一つに付き約一割寿命が短くなる" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "なるほど、だから神は10年周期で新しい身体に記憶と権能を継承するんですね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "だがCCにも全ての権能が書いてあった訳じゃない、『神格移譲』『使徒命令』『祝福移譲』の3つだけしか記載されていなかった、俺の記憶によると残りの4つのうち『能力封印』が確定、『創造』っていう効果不明の権能も存在する、残りの2つは未だに謎だ" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "使徒命令は勇者に対する絶対命令権、祝福移譲は勇者の祝福を移す力だな" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "CCの本質は、簡単に言えばこの世界に生物が生まれてから今に至るまでの歴史書だ。実際、教皇の手で加筆されたと思わしき部分もあった" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そして聞いて驚け、この世界の創世神話には、衝撃の事実が記されていた" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "まだ世界が生まれてない頃。虚無空間に、一つの神性が存在した。それがCynthia……シンシアだ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "シンシアはこの世界の名前であると同時に、｜原初《げんしょ》の神の名でもあった……？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "まぁ順番としては逆だ、神の名前を元に世界が名付けられた" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "だが現在聖教会が信仰している神は名もなき唯一神、つまりシンシアではない？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そういう事だ。シンシアはこの世界を作り、七つの種族を生み出し才能を与えた。だが、ある時、ある人間が、シンシアから神が神足り得る為に必要な物、七つの権能を奪ったんだ" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "それが……今の神……エルという訳だな" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そうだ。エルは神の権能を持っただけの人間であり、その本質を言い表すとすれば……――偽りの神だ" },
  { fx: "shake" },
  { text: "驚いた顔の奴、納得したという顔の奴、興味が無いとでも言いたげな奴、反応は様々だが……誰も反証を唱える事は出来なかった。エルと時間を共にした俺達なら分かる。" },
  { text: "あいつは、あまりにも、人間じみているのだ。転生を繰り返し、長い年月を生きていても、人間らしさというのは消えないという事なのだろう。" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "なんか……突拍子も無い話ばっかりで……" },
  { name: "瀬野", text: "理解が追いつかない……よね……僕もだよ" },
  { text: "アカツキと瀬野が溜息を吐いて、ソファに背を預けながら宙を仰いだ。一方、クロセル、セン公、シェル公はそこまで驚いた様子もない。流石は大物、と言った所だろうか。" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "待て？ご主人、CCは教皇の部屋で見つけたのだな？なら教皇は、エルが偽りの神である事を知っているはず。それなのにそれを公表せず、エルを信仰し続けている" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "……確かにおかしいな。あいつが｜固執《こしつ》してるのは\"この世界の神\"という概念ではなく、神を名乗るエル自身という訳か" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "それを聞くと、聖教会が途端に｜胡散臭《うさんくさ》い組織に聞こえてきますね……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "最初から｜胡散臭《うさんくさ》いだろ。教皇が神の味方ではなくエルの味方だというのなら、聖教会を味方に付ける事は難しそうだ。権能がある以上、勇者も味方には付けれない" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あと、最後に一つ。これが本題とも言えるんだが……俺はこの世界に転生する時、一つの言葉を受け取った。シンシアから、だ。シンシアは権能を失い、直接この世界に干渉する力を失った。だが、他世界への干渉能力は残されている。それは……至極明快だ。ただ一言。" },
  { wait: 800 },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "――『神を殺して』" },
  { fx: "flash" },
  { text: "俺が紡いだ言葉で、再び辺りは静寂に包まれる。" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "神というのは……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "エルの事だろう。エルは決別した時に俺にこう言った。『私とヤマト様は殺し合う関係』ってな" },
  { name: "瀬野", text: "僕やアカツキさんは、そんな言葉を受け取ってはいなかったけど……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "こういう言い方は失礼かもしれないが、恐らく……シンシアの試行錯誤の結果なんだろう。多くの人間を転生させ、俺のような完璧な存在を生み出そうとした。そして成功した、だからなけなしの力で俺に\"言葉\"を届けたんだ" },
  { chara: { slot: "left", id: "akatsuki", expr: "sad" } },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "つまり……私達はシンシアの失敗作って事ですか……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "まぁ、俺の仮説が正しいとは限らない、俺達を転生させたのはエルでもシンシアでもない第三者という可能性もある" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "神以外の存在がそんな事を出来るとは思えないがな" },
  { text: "ささやかな俺のフォローをクロセルが｜一蹴《いっしゅう》する。取り敢えず一発ぶん殴っといた。弾かれた。" },
  { name: "セン公爵", text: "それで、これからどうするんだい？このまま私の屋敷に｜居候《いそうろう》してくれても構わないし……或いは君の使命って奴を果たしに行くのも良いんじゃないかな" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "……前にクロセルは言ったよな、完全体のエルに俺は勝てない、と" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "確かに言ったな。だがそれは過去の話だ。今は違う。ご主人は完全体のエルに致命傷を負わせる事に成功している。つまり、勝機はある" },
  { text: "俺は一度、エルを殺そうとした。しかしそれは、本当の意味でエルと出会う前の話だ。例え偽りの絆だったとしても、エルは俺と共に旅をした大切な仲間でもあるんだ。だが俺はシンシアの作り出した、エルを殺す機械。その使命を果たす義務がある。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "エルは……敵だ。俺はあいつを、偽りの神を堕とす。そして権能をシンシアに返し、この世界を在るべき姿に戻す" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "これは俺とシンシアの我儘だ。お前達は付いて来る義務はない。降りる奴は遠慮なく言ってくれ" },
  { text: "これは魔王との戦いよりも過酷な物になる。そんな最後の旅路に、同行を無理強いする訳にはいかない。" },
  { bgm: "resolve" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "我はご主人の物だ、最期までご主人の剣であり、盾となろう" },
  { name: "シェル公爵", text: "ダーリンの為ならば、私は当然力になろう" },
  { name: "瀬野", text: "僕はヤマトに付いて行くよ、今度は置いていかないでね" },
  { chara: { slot: "left", id: "akatsuki", expr: "blush" } },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "アカツキ、どうする？遠慮するな、やめたいなら……" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "行きますよ。今更降りる訳無いじゃないですか、本当に仕方ない人ですね……ヤマトさんには、私が居ないと駄目なんですから" },
  { name: "セン公爵", text: "えっ？これ私も含まれてるのかい？気持ちは嬉しいが私には他にやるべき事が……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "なわけねぇだろ馬鹿貴族" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "当然だけど、エスクも連れて行かせないよ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "分かってる、俺とクロセル、アカツキ、瀬野、シェル公の五人だ" },
  { text: "結局、全員付いてくることになりましたとさ。" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "そうと決まれば早速上層に……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "気が早すぎるぞクロセル、こればっかりは入念に準備をしてから行くべきだ。対策するべきは……勇者二人とラプラス、教皇、エル、大量の福音使徒にまだ見ぬ勇者達……" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "恐ろしい程に圧倒的な戦力差ですね……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、だから準備するんだ。あらゆる事態に対応できるようにな" },
  { text: "これは英雄の物語ではない。正義であるエルを、悪である俺達が倒すのだ。誰にも称賛されない。ただ憎まれるだけの旅。得られる物など何もない。ただ、失うだけだ。そして、俺はその日から、最終決戦への準備に明け暮れる事になった。" },
  { text: "全てはシンシアの意思のままに。" },
  { wait: 800 },
  { text: "――｜神《エル》を殺す為に。" },
  { fade: "out" },
  { hide: "all" },
  { jump: "ch07:stardust_return" },

  /* =====================================================
     ============ B07分岐: 妖精の申し出を断る ==============
     ============ BAD END『緑の祈り』 =====================
     ===================================================== */
  { label: "b07_refuse" },
  { comment: "B07分岐: 記憶操作を断る → bad_green" },
  { bgm: "tension" },
  { chara: { slot: "right", id: "yamato", expr: "normal" } },
  { name: "ヤマト", who: "yamato", text: "……悪いが、やっぱりやめておく。妖精サマの気まぐれに、命を預ける訳にはいかないんでね。対価の無い取引ってのが一番高くつく。前の世界でそう学んだんだ", tid: "ch06__b07_refuse__01" },
  { chara: { slot: "center", id: "shellmi", expr: "surprised" } },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "ほう？折角の申し出を断るのかね？", tid: "ch06__b07_refuse__02" },
  { chara: { slot: "center", id: "shellmi", expr: "smug" } },
  { name: "シェル公爵", who: "shellmi", expr: "sad", text: "くくく……賢明、と言いたい所だが、君は一つ思い違いをしているよ。この街に足を踏み入れた時点で、君達は私の客人だ。客人は丁重に……もてなさなければね", tid: "ch06__b07_refuse__03" },
  { chara: { slot: "right", id: "yamato", expr: "angry" } },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……どういう意味だ？", tid: "ch06__b07_refuse__04" },
  { name: "シェル公爵", who: "shellmi", text: "さぁ？妖精は気まぐれだからね。気を付けて帰りたまえ、ヤマト君", tid: "ch06__b07_refuse__05" },
  { text: "背中に纏わり付くような視線を振り切り、俺達は大聖堂を後にした。", tid: "ch06__b07_refuse__06" },
  { hide: "all" },
  { bg: "fairy_celledge" },
  { chara: [
    { slot: "left",   id: "akatsuki", expr: "serious" },
    { slot: "center", id: "yamato",   expr: "normal" },
    { slot: "right",  id: "crocell",  expr: "normal" },
  ] },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "本当に良かったんですか？記憶を取り戻す手段は、恐らく彼女しか……", tid: "ch06__b07_refuse__07" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あの目を見ただろ。あいつは俺の記憶なんかに興味はない。別の何かを狙ってやがった。明日の朝一番でこの街を出る。記憶の事は……また別の手を探せば良い", tid: "ch06__b07_refuse__08" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "うむ、我も同感だ。あれは獲物を見る目だったぞ", tid: "ch06__b07_refuse__09" },
  { text: "宿に戻った俺達は、早めに休む事にした。何か、見落としている気がする。だがそれが何かは、分からなかった。", tid: "ch06__b07_refuse__10" },
  { fade: "out" },
  { hide: "all" },
  { comment: "その夜 — 街全体の祈り" },
  { bgm: "dark2" },
  { text: "――その夜。深夜のフェアリーケレッジの全ての家の窓に、ぽつり、ぽつりと灯りが点っていく。", tid: "ch06__b07_refuse__11" },
  { text: "緑衣の住民達が、一人、また一人とベッドから起き上がり、シェル公爵の大聖堂に向かって、左手人指し指を額に付け――祈り始める。", tid: "ch06__b07_refuse__12" },
  { name: "住民達", text: "シェルミ様。我らの街に迷い込んだ、哀れな旅人達に。どうか、貴女様の安らぎを……", tid: "ch06__b07_refuse__13" },
  { text: "数千の祈り。数千の信仰。それは才能指数10の記憶操作の触媒となり、静かに、静かに、一軒の宿を包み込んでいった。", tid: "ch06__b07_refuse__14" },
  { se: "magic" },
  { fx: "flash" },
  { text: "誰も、何も、気付かない。", tid: "ch06__b07_refuse__15" },
  { text: "夢の中の俺は、緑色の世界に居た。優しくて、暖かくて、何の不安もない世界。誰かが俺の頭を撫でている。小さくて、冷たい手だった。", tid: "ch06__b07_refuse__16" },
  { name: "誰かの声", text: "おやすみ、ヤマト君。明日からは、君も私の可愛い子供だ", tid: "ch06__b07_refuse__17" },
  { fade: "out" },
  { wait: 1200 },
  { comment: "翌朝 — 洗脳の完成" },
  { bg: "fairy_celledge" },
  { fade: "in" },
  { text: "目覚めた朝。窓から差し込む光が、やけに優しかった。", tid: "ch06__b07_refuse__18" },
  { chara: [
    { slot: "center", id: "yamato",  expr: "normal" },
    { slot: "right",  id: "crocell", expr: "laugh" },
  ] },
  { text: "隣でクロセルが、腕に嵌めた緑の腕輪を撫でて微笑んでいる。", tid: "ch06__b07_refuse__19" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "おはよう、ご主人。今日も良い朝だな", tid: "ch06__b07_refuse__20" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "あぁ……そうだな。良い朝だ", tid: "ch06__b07_refuse__21" },
  { name: "クロセル", who: "crocell", text: "シェルミ様は素晴らしいお方だぞ、ご主人", tid: "ch06__b07_refuse__22" },
  { chara: { slot: "center", id: "yamato", expr: "smile" } },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "あぁ、当然だろ。シェルミ様はこの街の……いや、この世界の太陽だ", tid: "ch06__b07_refuse__23" },
  { text: "あれ……俺は昨日、何をしようとしてたんだっけか。街を出る？馬鹿な。こんなに素晴らしい街を、どうして出る必要がある？", tid: "ch06__b07_refuse__24" },
  { text: "記憶？……あぁ、どうでも良い。そんな物より、今日の祈りの時間の方がずっと大切だ。", tid: "ch06__b07_refuse__25" },
  { chara: { slot: "left", id: "akatsuki", expr: "smile" } },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "ヤマトさん、早く支度して下さい。朝の礼拝に遅れますよ", tid: "ch06__b07_refuse__26" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "おう、今行く", tid: "ch06__b07_refuse__27" },
  { text: "緑のシャツに袖を通す。サイズはぴったりだった。最初から、そうである事が決まっていたかのように。", tid: "ch06__b07_refuse__28" },
  { hide: "all" },
  { text: "大聖堂の礼拝堂で、俺達は祈りを捧げる。クロセルも、アカツキも、瀬野も、皆同じ緑色だ。", tid: "ch06__b07_refuse__29" },
  { text: "｜暗幕《あんまく》の奥から、シェル公爵の満足げな声が響く。", tid: "ch06__b07_refuse__30" },
  { name: "シェル公爵", text: "くくく……最強の｜魔杖《まじょう》に、操作系才能の魔族、聡明な転生者。実に良い拾い物をした。妖精は気まぐれだが――一度手に入れた物は、決して手放さないのだよ", tid: "ch06__b07_refuse__31" },
  { text: "指数10の記憶操作に、抗う才能を持たない者は――", tid: "ch06__b07_refuse__32" },
  { text: "洗脳されたことにすら、気付けない。", tid: "ch06__b07_refuse__33" },
  { wait: 800 },
  { text: "聖都では、偽りの神が次の物語の幕を開け。誰にも知られぬまま、最弱無才の物語は、この緑の街で静かに終わった。", tid: "ch06__b07_refuse__34" },
  { text: "緑衣の信徒が数人増えた妖精都市は、今日も平和で、誰一人として不幸ではない。", tid: "ch06__b07_refuse__35" },
  { wait: 800 },
  { text: "それが、いちばん恐ろしい。", tid: "ch06__b07_refuse__36" },
  { fade: "out" },
  { hide: "all" },
  { jump: "ending:bad_green" },

  /* =====================================================
     ============ B08分岐: エルに斬りかかる ===============
     ============ BAD END『操り人形』 =====================
     ===================================================== */
  { label: "b08_attack" },
  { comment: "B08分岐: 30秒の｜猶予《ゆうよ》 — 斬りかかる → bad_puppets" },
  { text: "エルは瀬野を殺した。仲間を、親友を殺したんだ。", tid: "ch06__b08_attack__01" },
  { text: "ここで逃せば、万全になった神に二度と手は届かない。なら――答えは一つだろ。", tid: "ch06__b08_attack__02" },
  { chara: { slot: "center", id: "yamato", expr: "angry" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "瀬野の仇だ……ここでお前を討つ！", tid: "ch06__b08_attack__03" },
  { fx: "shake" },
  { text: "氷の槍を構え、俺は地を蹴った。強化魔術の出力を全開にして、一直線にエルへと迫る。", tid: "ch06__b08_attack__04" },
  { chara: { slot: "right", id: "el", expr: "sad" } },
  { name: "エル", who: "el", text: "そっか……残念だよ、ヤマト様", tid: "ch06__b08_attack__05" },
  { text: "エルは悲しそうに目を伏せると、囁くように、静かに言った。", tid: "ch06__b08_attack__06" },
  { name: "エル", who: "el", expr: "sad", text: "ごめんね。……それでも、生きるためには仕方ないんだ。私だって、好きでこうしてる訳じゃないんだよ", tid: "ch06__b08_attack__07" },
  { text: "それは、命乞いの言葉のようにも、許しを乞う言葉のようにも聞こえた。神が、たった一人の人間に向けて、頭を垂れるみたいに。", tid: "ch06__b08_attack__08" },
  { chara: { slot: "right", id: "el", expr: "blank" } },
  { name: "エル", who: "el", expr: "smile", text: "ニコラス、ティア。彼らを殺しなさい", tid: "ch06__b08_attack__09" },
  { fx: "flash" },
  { text: "俺の槍がエルに届くより早く、金色の閃光が割り込んだ。", tid: "ch06__b08_attack__10" },
  { chara: [
    { slot: "left",   id: "nicholas", expr: "serious" },
    { slot: "center", id: "yamato",   expr: "surprised" },
    { slot: "right",  id: "tia",      expr: "sad" },
  ] },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "聖剣……抜刀……", tid: "ch06__b08_attack__11" },
  { fx: "shake" },
  { text: "受け止めた氷の槍が、粉々に砕け散る。俺は地面を転がりながら、辛うじて致命の一撃を躱した。", tid: "ch06__b08_attack__12" },
  { chara: { slot: "center", id: "yamato", expr: "angry" } },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "勇者！てめぇ、正気か！？", tid: "ch06__b08_attack__13" },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "ごめん……ごめんよ、ヤマト君……身体が……勝手に……", tid: "ch06__b08_attack__14" },
  { text: "勇者の頬を、涙が伝っていた。泣きながら、それでも彼の剣筋には一切の躊躇いがない。まるで、身体の主導権ごと、誰かに握られているかのように。", tid: "ch06__b08_attack__15" },
  { name: "エル", who: "el", expr: "sad", text: "勇者は神の御告げ……いや、神の命令に絶対遵守。この世界のルールだよ。……気付いてないのは、馬鹿なヤマト様、貴方だけだ", tid: "ch06__b08_attack__16" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "エル……お前……まさか、お前が……！？", tid: "ch06__b08_attack__17" },
  { name: "ティア", who: "tia", expr: "sad", text: "ごめんなさい……ごめんなさい……ごめんなさい……", tid: "ch06__b08_attack__18" },
  { fx: "flash" },
  { text: "謝罪を繰り返しながら、ティアの｜鎌鼬《かまいたち》が夜を裂く。クロセルが俺を突き飛ばし、その白い肩から｜血飛沫《ちしぶき》が舞った。", tid: "ch06__b08_attack__19" },
  { name: "クロセル", text: "ぐっ……ご主人、下がれ！勇者二人を相手に勝ち目はない！", tid: "ch06__b08_attack__20" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "クロセル！？くそっ……！", tid: "ch06__b08_attack__21" },
  { fx: "red" },
  { bgm: "dark" },
  { text: "そこから先は、地獄だった。", tid: "ch06__b08_attack__22" },
  { text: "クロセルの水弾が勇者の鎧に弾かれ、ティアの風が応戦するアカツキを切り刻む。腕を失ったアカツキが、それでも詠唱を止めない。", tid: "ch06__b08_attack__23" },
  { name: "アカツキ", text: "ヤマトさん……逃げて……下さい……っ", tid: "ch06__b08_attack__24" },
  { chara: { slot: "center", id: "yamato", expr: "sad" } },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "仲間同士で……何やってんだよ、俺達は……！", tid: "ch06__b08_attack__25" },
  { text: "勇者の聖剣がクロセルの氷剣を砕き、ティアの｜鎌鼬《かまいたち》がクロセルの小さな身体を吹き飛ばす。", tid: "ch06__b08_attack__26" },
  { text: "魔王をも封じた最強の｜魔杖《まじょう》が。世界で一番と二番の魔術師の片割れが。最強の剣士と勇者の才能を前に、ゆっくりと削られていく。", tid: "ch06__b08_attack__27" },
  { chara: { slot: "left", id: "nicholas", expr: "surprised" } },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "うあああああ！僕は！僕はああああ！", tid: "ch06__b08_attack__28" },
  { text: "泣き叫びながら剣を振るう勇者。謝り続けながら風を放つ少女。これが神の力。人の絆ごと、操り人形に変える力。", tid: "ch06__b08_attack__29" },
  { fx: "shake" },
  { text: "やがて、氷の砕ける音が止んだ。", tid: "ch06__b08_attack__30" },
  { fade: "out" },
  { hide: "all" },
  { fade: "in" },
  { bgm: "sad" },
  { text: "血の海の中、俺は這うように、動かなくなったクロセルへと手を伸ばす。", tid: "ch06__b08_attack__31" },
  { chara: { slot: "center", id: "yamato", expr: "sad" } },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "クロセル……おい……嘘だろ……俺の側に居ろって……命令しただろうが……", tid: "ch06__b08_attack__32" },
  { text: "白い髪が、赤黒く染まっている。その手は、もう俺の拳を弾き返してはくれなかった。", tid: "ch06__b08_attack__33" },
  { chara: { slot: "right", id: "el", expr: "sad" } },
  { text: "神は、その光景を見下ろしていた。読み終えた本を閉じるような目で。けれどその瞳の奥に滲んでいたのは、退屈ではなく――哀しみのように見えた。", tid: "ch06__b08_attack__34" },
  { name: "エル", who: "el", text: "あーあ。……せっかくの、大切な登場人物が、こんなに減っちゃった", tid: "ch06__b08_attack__35" },
  { chara: { slot: "center", id: "yamato", expr: "angry" } },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "エル……てめぇ……！", tid: "ch06__b08_attack__36" },
  { chara: { slot: "right", id: "el", expr: "smile" } },
  { name: "エル", who: "el", expr: "normal", text: "怒っていいよ。私を恨んでいい。……それくらいの事を、私はしたんだから", tid: "ch06__b08_attack__37" },
  { wait: 800 },
  { name: "エル", who: "el", expr: "smile", text: "ねぇ、ヤマト様。私ね、ほんとうは――", tid: "ch06__b08_attack__38" },
  { chara: { slot: "right", id: "el", expr: "sad" } },
  { name: "エル", who: "el", expr: "sad", text: "――ハッピーエンドに……したかったな", tid: "ch06__b08_attack__39" },
  { text: "ぽつりと零れたその独白は、勝者の言葉とは思えないほど、寂しげだった。生きるために、神であるために、彼女はきっと、こうするしかなかったのだ。それでも、その選択を、彼女自身が一番悲しんでいた。", tid: "ch06__b08_attack__40" },
  { name: "エル", who: "el", text: "……次は。次こそは、間違えないようにするよ。何度でも、やり直して。だから――またね、ヤマト様", tid: "ch06__b08_attack__41" },
  { text: "神にとって人の絆は、いつでも書き換えられる脚本にすぎない。けれど、その脚本を握る指先が、微かに震えていたのを、俺は見た気がした。", tid: "ch06__b08_attack__42" },
  { text: "操り人形になった勇者達が、ゆっくりと俺を取り囲む。月だけが、白く輝いていた。", tid: "ch06__b08_attack__43" },
  { fx: "red" },
  { fade: "out" },
  { hide: "all" },
  { jump: "ending:bad_puppets" },

]);
